-- v29.73 · mushroom_register_i18n — EN/ES/FR/IT-Übersetzungen der Steckbrief-Prosa
-- 5 Felder (identifying_features, symptoms_if_toxic, emergency_action, cooking_preparation, cultural_notes)
-- × 85 Pilze × 4 Sprachen. DE-Quelle bleibt in mushroom_register.
-- Übersetzung translate+adversarial-safety-Verify-Workflow (medizinische Felder geprüft;
-- 145/144/Tox Info Suisse/Silibinin + lat. Artnamen erhalten — HL#24).
create table if not exists public.mushroom_register_i18n (
  slug text not null references public.mushroom_register(slug) on delete cascade,
  lang text not null,
  identifying_features text, symptoms_if_toxic text, emergency_action text,
  cooking_preparation text, cultural_notes text,
  verified boolean not null default false,
  created_at timestamptz not null default now(),
  primary key (slug, lang)
);
alter table public.mushroom_register_i18n enable row level security;
drop policy if exists "mushroom_register_i18n_read" on public.mushroom_register_i18n;
create policy "mushroom_register_i18n_read" on public.mushroom_register_i18n for select to anon, authenticated using (true);
revoke insert, update, delete on public.mushroom_register_i18n from anon, authenticated, public;

on conflict (slug, lang) do update set
  identifying_features=excluded.identifying_features, symptoms_if_toxic=excluded.symptoms_if_toxic,
  emergency_action=excluded.emergency_action, cooking_preparation=excluded.cooking_preparation,
  cultural_notes=excluded.cultural_notes, verified=true;

