insert into public.mushroom_register_i18n
  (slug, lang, identifying_features, symptoms_if_toxic, emergency_action, cooking_preparation, cultural_notes, verified)
values
($p1$agaricus_augustus$p1$,$p1$en$p1$,$p1$Large cap, initially spherical, with yellowish-brown scales on a pale ground; distinct smell of anise/bitter almond; flesh weakly yellowing when cut; membranous ring; gills free, pale when young, chocolate-brown when old. WARNING: often accumulates cadmium, therefore only occasionally and in moderation.$p1$,$p1$Species edible; if confused with the Yellow-staining Mushroom (Carbol champignon), gastrointestinal complaints. Inherent risk: heavy-metal accumulation (cadmium). Deadly if confused with the Amanita (Death Cap).$p1$,null,$p1$Cook thoroughly; popular for its anise smell; because of cadmium only in moderation.$p1$,$p1$Confusion/look-alikes: Yellow-staining Mushroom (A. xanthodermus) and Inky Mushroom (A. moelleri) – toxic (carbolic smell, chrome-yellow stem base); as a young mushroom can be confused with the white/green death cap (check volva/white spore powder) – deadly.$p1$,true),
($p1$agaricus_campestris$p1$,$p1$en$p1$,$p1$MEADOW habitat, white cap, pink gills that turn brown$p1$,null,null,$p1$like cultivated button mushroom$p1$,$p1$CAUTION confusion with Yellow-staining Mushroom (Carbol Champignon), toxic$p1$,true),
($p1$agaricus_xanthodermus$p1$,$p1$en$p1$,$p1$Cap 5-14 cm, white to whitish, centre often brownish. Flesh white, at the stem base staining strongly CHROME-YELLOW when pressed/cut. Unpleasant smell of carbolic/phenol/ink (intensified when heated). Gills pink when young, then chocolate-brown.$p1$,$p1$Gastrointestinal syndrome: 15 min to 2 h after consumption nausea, vomiting, diarrhea, abdominal cramps. Severe in sensitive individuals. Toxic both raw and cooked.$p1$,$p1$In case of symptoms, Tox Info Suisse 145. Usually symptomatic (fluids/electrolytes).$p1$,$p1$Do not consume. The carbolic smell intensifies when heated.$p1$,$p1$Confusion/look-alikes: death caps (Amanita phalloides/verna) among white button mushrooms – check bulb/volva; edible mushrooms (Field, Anise, Horse Mushroom) do not stain chrome-yellow and do not smell of carbolic.$p1$,true),
($p1$albatrellus_confluens$p1$,$p1$en$p1$,$p1$Dough-yellow to fawn-/golden-brown, lobed-knobbly cap 3-20 cm, looking as if formed from dough; often several fruiting bodies fused together with branched stems; underside with fine round, yellowish-white pores (no gills). Mycorrhizal with pine/conifers on acidic soils. Mild when young, increasingly bitter when old.$p1$,$p1$Raw/insufficiently cooked, gastrointestinal intolerance; old specimens bitter/hard to digest$p1$,null,$p1$Only young specimens; intolerable raw, cook thoroughly. Of little flavour when fresh, best pickled as a vinegar/oil mushroom. Old ones become bitter. (In CH observe local protection/collecting regulations.)$p1$,null,true),
($p1$amanita_citrina$p1$,$p1$en$p1$,$p1$Cap 4-10 cm, pale lemon-/sulphur-yellow (also white form var. alba), with adhering white-brownish veil remnants. Gills white, free. Stem with ring and rimmed, bulbous base. Smell of raw potatoes/radish.$p1$,$p1$Inedible to mildly toxic. Consumption is strongly discouraged – because of its potato-like smell/taste and, above all, the high risk of confusion with the deadly white/green Amanita (Death Cap/Destroying Angel).$p1$,$p1$If consumed and uncertain about the species, Tox Info Suisse 145 – rule out confusion with the deadly Amanita (Death Cap).$p1$,$p1$Do not consume. Because of the extreme risk of confusion with deadly species, avoid altogether.$p1$,$p1$Confusion/look-alikes: Green death cap (Amanita phalloides) and Spring/White death cap – the white form var. alba is especially dangerously confusable (deadly!).$p1$,true),
($p1$amanita_excelsa$p1$,$p1$en$p1$,$p1$Cap 5-16 cm, grey-brown, with grey, adhering, easily wipeable veil flakes (not warty like the panther cap). Stem white-grey, with a GROOVED/striate ring (decisive!), bulbous, not sharply rimmed base. Radish-like smell. Syn. Amanita spissa.$p1$,$p1$Toxic raw (like all Amanita with a ringed stem). NOT approved as an edible mushroom in Switzerland. The MAIN DANGER is confusion with the strongly/potentially deadly toxic Panther Cap (Amanita pantherina): pantherina syndrome – confusion, hallucinations, convulsions, in severe cases coma; deaths documented in children/at high doses.$p1$,$p1$If confusion with the Panther Cap is suspected, immediately Tox Info Suisse 145.$p1$,$p1$Do NOT consume. In Switzerland not approved as an edible mushroom; because of life-threatening panther cap confusion, strongly avoid. Ring/bulb are not a reliable distinction for beginners.$p1$,$p1$Confusion/look-alikes: panther cap (Amanita pantherina) – strongly, potentially deadly toxic; the panther cap has a SMOOTH ring and a rimmed bulb, the Grey Spotted Amanita a GROOVED ring and an unrimmed bulb.$p1$,true),
($p1$amanita_muscaria$p1$,$p1$en$p1$,$p1$RED cap with white spots, white stem with ring + bulb$p1$,$p1$30 min–2 h confusion, hallucinations, nausea$p1$,$p1$Tox Info Suisse 145 / Emergency 144. Hospital.$p1$,$p1$NEVER EAT$p1$,$p1$Fairy-tale mushroom. Deadly rarely but dangerous$p1$,true),
($p1$amanita_pantherina$p1$,$p1$en$p1$,$p1$BROWN cap, white spots, bulb with 2-3 rings (girdles) at the stem base$p1$,$p1$More severe than the Fly Agaric, nausea, confusion, convulsions$p1$,$p1$Tox Info Suisse 145 / Emergency 144. Urgently to hospital.$p1$,$p1$NEVER EAT$p1$,$p1$More toxic than the fly agaric, more common than the death cap$p1$,true),
($p1$amanita_phalloides$p1$,$p1$en$p1$,$p1$RING on the stem + bulb in a membranous SHEATH + white gills + olive-green cap$p1$,$p1$8-24h gastrointestinal storm, then apparent improvement, then liver failure on day 3-5$p1$,$p1$IMMEDIATELY Tox Info Suisse 145 / emergency 144. Hospital, Silibinin, liver transplant if necessary.$p1$,$p1$NEVER EAT$p1$,$p1$90%+ of mushroom-poisoning deaths in Europe. LEARN TO RECOGNISE UNMISTAKABLY$p1$,true),
($p1$amanita_rubescens$p1$,$p1$en$p1$,$p1$Reddish-brown cap with grey (NOT pure-white) veil flakes; decisive: flesh and maggot tunnels redden/turn wine-red (especially the stem base); ring grooved on the upper side; white gills, white spore powder. NEVER rely on a single feature – check all features together. Only for experienced collectors.$p1$,$p1$Toxic when raw (hemolysins destroy red blood cells); must be thoroughly cooked through. Confusion with the panther cap leads to severe (pantherina syndrome), sometimes fatal poisonings.$p1$,$p1$If panther cap confusion is suspected (confusion, intoxication, convulsions) Tox Info Suisse 145 / emergency 144.$p1$,$p1$Never raw; cook thoroughly (destroys haemolysins); use only with certain identification (reddening test + all features).$p1$,$p1$Confusion/look-alikes: panther cap (Amanita pantherina) – strongly toxic, fatalities known (pure-white flakes, grooved cap margin, rimmed-bulbous base, smooth ring, flesh NEVER reddens; toxins heat-stable).$p1$,true),
($p1$amanita_verna$p1$,$p1$en$p1$,$p1$Completely PURE-WHITE death cap: cap 5-10 cm, snow-white, smooth silky-glossy. Gills white, free, dense. Stem white with a hanging ring and a membranous sheath (volva) at the bulbous base. Appears mainly in spring/early summer. KOH test of the cap skin turns yellow.$p1$,$p1$Phalloides syndrome: 6-24 h latency, then massive vomiting, cholera-like diarrhea, abdominal pain, apparent improvement, then liver and kidney failure. Even a single fruiting body can be fatal.$p1$,$p1$Immediately Tox Info Suisse 145 / emergency call 144. Keep food remnants. Clinic: Silibinin/N-acetylcysteine, activated charcoal – every hour counts.$p1$,$p1$Never consume. Amatoxins are heat-stable, NOT destroyed by cooking/drying.$p1$,$p1$Confusion/look-alikes: button mushrooms/Agaricus (these have pink-brown gills, no white volva); a white, free-gilled mushroom with a volva is ALWAYS suspect.$p1$,true),
($p1$auricularia_auricula_judae$p1$,$p1$en$p1$,$p1$Ear-shaped, gelatinous-elastic, rubbery fruiting body, 2-10 cm, translucent red-brown to black-brown; upper side velvety and finely hairy, underside smooth and veined. Grows mostly on dead elder, also on ash/maple/beech. Dries hard, swells when soaked. No poisonous look-alikes.$p1$,null,null,$p1$A flavour-neutral filling/mixing mushroom (Mu-Err of Asian cuisine); storable when dried, soak before use; heat well. In soups, wok dishes, salads.$p1$,null,true),
($p1$austernpilz$p1$,$p1$en$p1$,$p1$Grows SIDEWAYS on trees in a fan-like arrangement.$p1$,null,null,$p1$Frying, soup; cultivable.$p1$,$p1$Winter-season mushroom; cultivable indoors.$p1$,true),
($p1$boletus_aereus$p1$,$p1$en$p1$,$p1$Cap coffee-, dark- to bronze-brown, sometimes almost black, finely velvety when young; stem thick and club-shaped with a fine white to light-brownish net; pores white, yellowish when old; flesh white, NOT turning blue, mild. Heat-loving.$p1$,null,null,$p1$Excellent, firm-fleshed edible mushroom; fried, steamed, dried. Collect sparingly due to its rarity.$p1$,null,true),
($p1$boletus_reticulatus$p1$,$p1$en$p1$,$p1$Cap pale ochre to light brown, dry and finely felty (often cracking into fields/patches), stem with a whitish to light-brown, distinctly raised net over its entire length; tubes whitish, yellow-olive when old; flesh white, not turning blue, mild. An early species (from June). Important: rule out the Bitter Bolete (Tylopilus felleus — pink tubes, coarse dark net, extremely bitter) by a taste test.$p1$,null,null,$p1$Excellent edible mushroom; young raw as a salad or fried, steamed, dried. Use young, as it becomes maggoty early.$p1$,$p1$Verwechslung/Doppelgänger: Parasol (Macrolepiota procera) und essbare Safranschirmlinge$p1$,true),
($p1$butterpilz$p1$,$p1$en$p1$,$p1$SLIMY cap skin must be removed; ring on the stem.$p1$,null,null,$p1$Peel off the cap skin, then fry.$p1$,$p1$Peeling off the cap skin is mandatory — otherwise digestive problems.$p1$,true),
($p1$caloboletus_calopus$p1$,$p1$en$p1$,$p1$Cap light grey, clay-coloured to grey-brown, finely felty and dry; pores light yellow, turning blue when pressed; stem two-coloured – yellow above, brilliant CARMINE RED below, with a fine net (the source of the name 'Beautiful-foot Bolete'); flesh yellowish, turning blue when cut, very BITTER.$p1$,$p1$Toxic raw; if eaten, gastrointestinal complaints (nausea, vomiting, diarrhea). Additional main problem: persistent extreme bitterness.$p1$,$p1$If complaints occur, call Tox Info Suisse 145 (24h); replace fluids, and have more severe symptoms medically evaluated.$p1$,$p1$DO NOT EAT – poisonous raw and extremely bitter; the bitterness does not disappear with cooking. Even small amounts ruin a dish; if eaten, gastrointestinal complaints.$p1$,null,true),
($p1$calocybe_gambosa$p1$,$p1$en$p1$,$p1$Fleshy cream-white cap; decisive: densely spaced gills that are white at EVERY age and white spore powder; strong mealy-cucumber smell and taste; flesh does NOT turn red; a spring mushroom. The mealy smell + white gills distinguish it from the deadly fibrecap.$p1$,$p1$Species edible; LIFE-THREATENING if confused with Inocybe erubescens (muscarine syndrome: heavy salivation/lacrimation/sweating, pupil constriction, vomiting, diarrhea, respiratory distress).$p1$,$p1$If a fibrecap (Inocybe) confusion is suspected (muscarine symptoms), IMMEDIATELY contact Tox Info Suisse 145 / emergency 144 – atropine as antidote.$p1$,$p1$Cook through well; a prized edible mushroom – only with unambiguous identification (white gills, mealy smell, no reddening).$p1$,$p1$Confusion/look-alike: Brick-red fibrecap (Inocybe erubescens) – DEADLY poisonous, high muscarine content; also a spring species; flesh reddens, grey-brown gills, brown spore powder. Also the poisonous Livid Pinkgill (Entoloma sinuatum).$p1$,true),
($p1$calvatia_gigantea$p1$,$p1$en$p1$,$p1$Giant white sphere without a stem, 5-50 (up to 150) cm in diameter, up to over 20 kg; snow-white when young with a smooth leathery skin, later green-yellow (then inedible). In meadows, parks, forest edges. ONLY eat when the inner flesh is snow-white and without gill insertions - always cut through!$p1$,null,$p1$Always cut lengthwise: if there is an internal gill structure/cap outline (instead of uniform white flesh), discard it - deadly confusion with a young death cap (Amanita).$p1$,$p1$Only young specimens that are snow-white inside; sliced, breaded and fried ("Beamtenkotelett", schnitzel-like). Discard if the inner flesh is discoloured yellow.$p1$,$p1$Confusion/look-alike: Amanita phalloides/virosa (young death caps as a white sphere - but recognisable inside by the gill insertion and cap outline).$p1$,true),
($p1$cantharellus_tubaeformis$p1$,$p1$en$p1$,$p1$Small funnel-/trumpet-shaped mushroom, cap 1-7 (9) cm, yellow-brown to olive-grey, centre furrowed/perforated; underside with forked, decurrent, grey-yellow ridges (not true gills); stem thin, hollow, yellow. No dangerous confusions known.$p1$,null,null,$p1$A very good mixing and drying mushroom despite its thin flesh; cook through well. Ideal in mushroom dishes, soups, dried.$p1$,null,true),
($p1$champignon-de-paris$p1$,$p1$en$p1$,$p1$Fine white ring on the stem, pink gills in young specimens, brown cap colouring in the cultivated form.$p1$,null,null,$p1$Raw in salads or fried; heat briefly to preserve the flavour.$p1$,$p1$The most-purchased edible mushroom in Switzerland, mainly from cultivated production.$p1$,true),
($p1$chlorophyllum_brunneum$p1$,$p1$en$p1$,$p1$Coarsely scaly brown cap; flesh and gills turn saffron-red/orange when damaged (reddening); decisive: distinctly rimmed, bulbous, set-off stem bulb; simple (often movable) ring; NO snake-skin patterning on the stem (the difference from the edible Parasol, Macrolepiota procera). Often grows on/next to compost.$p1$,$p1$Gastrointestinal poisoning: nausea, vomiting, diarrhea, abdominal cramps; severity varies individually; not suitable as an edible mushroom.$p1$,$p1$If complaints occur after consumption, contact Tox Info Suisse 145.$p1$,null,$p1$Confusion/look-alike: Parasol (Macrolepiota procera) and edible saffron parasols – confusion leads to poisoning (the Parasol has a snake-skin-patterned stem, no rimmed bulb).$p1$,true),
($p1$clitocybe_dealbata$p1$,$p1$en$p1$,$p1$Small white mushroom, cap 2-5 cm, chalk-white to cream-white, convex when young, later flat to depressed. Gills whitish-cream, crowded, slightly decurrent. Grows gregariously on lawns, meadows, pastures – often in fairy rings, frequently beside the fairy ring mushroom (Marasmius oreades / Nelkenschwindling).$p1$,$p1$Muscarine syndrome: 15-30 min after consumption, heavy salivation/lacrimation/sweating, miosis, abdominal pain, nausea, diarrhea, blurred vision, labored breathing. Antidote: atropine.$p1$,$p1$Tox Info Suisse 145. Antidote atropine at the clinic.$p1$,$p1$Never consume. Muscarine is heat-stable.$p1$,$p1$Confusion/look-alikes: fairy ring mushroom (Marasmius oreades, edible) and young field mushroom – same meadow habitat; also with Clitocybe rivulosa (likewise poisonous).$p1$,true),
($p1$clitocybe_nebularis$p1$,$p1$en$p1$,$p1$Large misty-grey, frosted-looking cap with an inrolled margin; cream-coloured, closely spaced, slightly decurrent gills; robust pale stem; strikingly sweetish-rancid smell.$p1$,$p1$Frequently individual intolerance: gastrointestinal disturbances (nausea, vomiting, diarrhea) even with cooked mushrooms; nebularine is NOT removed by boiling.$p1$,null,$p1$VAPKO German-speaking Switzerland today classifies its consumption as questionable (edibility rating changed to 'not an edible mushroom') – consumption is discouraged; if at all, then only well-cooked and in small amounts.$p1$,$p1$Confusion/look-alikes: livid pinkgill (Entoloma sinuatum) – highly poisonous (yellowish, later pink, distantly spaced gills); also the poisonous tiger sawgill (Tricholoma pardinum).$p1$,true),
($p1$clitocybe_rivulosa$p1$,$p1$en$p1$,$p1$Small whitish mushroom, cap 2-4 cm, white-frosted when young, often concentrically blotched/grooved with frosting (the frosting cracking open), translucent flesh-pink. Gills pale cream-pink, crowded, slightly decurrent. Grows gregariously on meadows, lawns, path edges, often in rows/fairy rings.$p1$,$p1$Muscarine syndrome: 15-30 min after consumption, heavy salivation/lacrimation/sweating, miosis, abdominal pain, nausea, diarrhea, blurred vision. Antidote: atropine.$p1$,$p1$Tox Info Suisse 145. Antidote atropine at the clinic.$p1$,$p1$Never consume. Muscarine is even released from its precursor during cooking – heating does NOT detoxify.$p1$,$p1$Confusion/look-alikes: fairy ring mushroom (Marasmius oreades) and field mushroom (same habitat); also with the field funnel cap (likewise poisonous).$p1$,true),
($p1$cortinarius_orellanus$p1$,$p1$en$p1$,$p1$Orange-brown cap, orange gills, FIBROUS-orange stem, LATE Sep-Nov$p1$,$p1$LATE kidney failure 3-14 days later$p1$,$p1$Immediately call Tox Info Suisse 145 / emergency 144. Clinic, dialysis preparation (kidney failure).$p1$,$p1$NEVER EAT, often confused with the chanterelle$p1$,$p1$Treacherous: poisoning only appears 1-2 weeks after consumption$p1$,true),
($p1$cortinarius_rubellus$p1$,$p1$en$p1$,$p1$Cap 3-8 cm, yellow- to orange-brown/rust-red, conical with a pointed umbo, dry and finely felted. Gills cinnamon- to rust-brown, distantly spaced. Cortina (veil). In acidic, humus-rich coniferous forests, especially spruce. Smell radish-like.$p1$,$p1$Orellanus syndrome: very long latency of 2 days to 3 weeks. First thirst, nausea, head/limb/kidney pain, then severe, often irreversible kidney failure. ~50% remain dependent on dialysis.$p1$,$p1$Immediately call Tox Info Suisse emergency number 145. Because of the extremely long latency, go to the clinic immediately even if suspicion arises late – monitor kidney function, dialysis if needed.$p1$,$p1$Never consume. Orellanine is heat-stable and resistant to drying.$p1$,$p1$Confusion/look-alikes: Cortinarius orellanus (likewise deadly); when young, confusable with Cortinarius caperatus and the chanterelle.$p1$,true),
($p1$eierschwamm$p1$,$p1$en$p1$,$p1$Ridges instead of gills, entirely egg-yolk yellow, apricot-like smell$p1$,null,null,$p1$Fry fresh, do not wash$p1$,$p1$A flavour classic$p1$,true),
($p1$entoloma_sinuatum$p1$,$p1$en$p1$,$p1$Large, fleshy mushroom, cap 6-20 cm, whitish-grey to clay-yellow/ivory when young, smooth, wavy with age. Most important feature: gills whitish/yellowish when young, then turning FLESH-PINK from the spores (pinkgill). Mealy/rancid smell. Robust white stem without a ring.$p1$,$p1$Severe gastrointestinal syndrome: approx. 0.5-4 h after ingestion, violent, colicky gastrointestinal symptoms, vomiting, diarrhea, electrolyte loss, circulatory problems. Potentially life-threatening for children, the elderly and the debilitated.$p1$,$p1$Tox Info Suisse 145. Aggressive rehydration/electrolyte replacement; inpatient care for at-risk individuals.$p1$,$p1$Never consume. Toxins are cooking-stable; one of the most common triggers of severe gastrointestinal poisoning in Europe.$p1$,$p1$Confusion/look-alikes: St. George's mushroom (Calocybe gambosa, edible – white dense gills, earlier in the year), the miller (Clitopilus prunulus), young field mushrooms, the shield pinkgill.$p1$,true),
($p1$flaemmling$p1$,$p1$en$p1$,$p1$Small cap size, fibrous-finely flecked, grows on wood$p1$,$p1$no toxins$p1$,$p1$not necessary$p1$,$p1$Only when young and fresh, cooking recommended$p1$,$p1$Tender, but short shelf life$p1$,true),
($p1$fliegenpilz-grosspilz$p1$,$p1$en$p1$,$p1$Brain-like folded cap, hollow cavity, similar to morel$p1$,$p1$Headache, nausea, diarrhea, dizziness, cramps$p1$,$p1$Poison emergency hotline 145, stomach-protective care$p1$,$p1$Not edible$p1$,$p1$Often confused with the edible morel$p1$,true),
($p1$fliegenpilz-roetlich$p1$,$p1$en$p1$,$p1$Brown with white flecks, ring and small bulb$p1$,$p1$Headache, dizziness, confusion$p1$,$p1$Poison emergency hotline 145, treatment$p1$,$p1$Not edible$p1$,$p1$Rarer than the fly agaric$p1$,true),
($p1$fliegenpilz_var_alba$p1$,$p1$en$p1$,$p1$White cap with white flecks, white ring and volva, can be confused with edible mushrooms$p1$,$p1$Intoxication, muscle cramps, confusion, hallucinations$p1$,$p1$Poison emergency hotline 145, consider gastric lavage$p1$,$p1$Not edible$p1$,$p1$Variant form of the fly agaric, poisonous like the red form$p1$,true),
($p1$flockenstieliger-hexen-roehrling$p1$,$p1$en$p1$,$p1$Red pores, turning blue under pressure, red flecks on the stem, yellow flesh that discolours to red$p1$,$p1$Nausea, vomiting, stomach cramps if insufficiently heated$p1$,$p1$Medical advice in case of poisoning symptoms$p1$,$p1$Cook/boil through for at least 20 minutes, do not eat raw, prepare thoroughly$p1$,$p1$Edible only after thorough preparation; often confused with the poisonous Flockenstieliger Hexen-Röhrling (dotted-stem bolete)$p1$,true),
($p1$flockenstieliger_hexenpilz$p1$,$p1$en$p1$,$p1$RUDE little dots on the stem, tubes red, turns blue QUICKLY under pressure$p1$,$p1$cooked: no problems; raw: mild discomfort$p1$,null,$p1$MUST be cooked 15+ min; raw causes mild poisoning$p1$,$p1$Despite its alarming appearance, very popular$p1$,true),
($p1$fomitopsis_betulina$p1$,$p1$en$p1$,$p1$Annual, bracket-/hoof-shaped polypore, 5-20 cm, exclusively on birch; upper surface smooth, grey- to light-brown with an overhanging inrolled margin, underside with fine white pores. Flesh white when young, soft-corky, later increasingly bitter. Well-known vital/medicinal mushroom (Ötzi mushroom).$p1$,null,null,$p1$Not an edible mushroom (tough, bitter). Traditionally as a medicinal/vital mushroom: young white fruiting bodies dried as tea/extract. Not as a dish.$p1$,null,true),
($p1$galerina_marginata$p1$,$p1$en$p1$,$p1$Small cap 1-7 cm, yellow-brown to honey-coloured/dark brown, often with a darker centre, hygrophanous. Gills pale when young, later rust-brown, attached. Fragile thin ring on the stem (often disappears quickly). In clusters or single on dead conifer (also broadleaf) wood, rotting stumps.$p1$,$p1$Phalloides syndrome: 6-24 h latency, then severe vomiting, diarrhea, abdominal pain, apparent recovery, followed by liver and kidney failure. 100-150 g can be fatal.$p1$,$p1$Immediately call Tox Info Suisse emergency line 145 (or 144). Keep mushroom remains. Clinic with suspected amatoxin poisoning. Silibinin therapy. Every hour counts.$p1$,$p1$Never consume. Amatoxins are heat-stable and CANNOT be destroyed by cooking/drying.$p1$,$p1$Confusion/look-alike: sheathed woodtuft (Kuehneromyces mutabilis) – edible, but the most dangerous confusion; Galerina has no scaly stem below the ring.$p1$,true),
($p1$gemeiner-fliegenpilz-var-alba$p1$,$p1$en$p1$,$p1$White to greyish-brown cap without flecks, white veil beneath the ring, bulb at the stem base with a volva$p1$,$p1$Delayed onset after 6-24h, severe stomach complaints, liver failure, fatal$p1$,$p1$Call emergency physician immediately, emergency treatment required$p1$,$p1$Not edible$p1$,$p1$One of the deadliest mushroom species in Europe; risk of confusion with the white champignon (button mushroom)$p1$,true),
($p1$hallimasch$p1$,$p1$en$p1$,$p1$RING on the stem, honey-yellow, parasitic on tree roots, in clusters$p1$,$p1$raw: gastrointestinal$p1$,$p1$if feeling unwell, go to hospital$p1$,$p1$MUST BE COOKED 15+ min, never raw$p1$,$p1$Mass occurrence. NEVER raw, very good when cooked$p1$,true),
($p1$herbsttrompete$p1$,$p1$en$p1$,$p1$Hollow trumpet, dark grey-black$p1$,null,null,$p1$dry for a winter seasoning$p1$,$p1$Swiss gourmet treasure$p1$,true),
($p1$hygrophoropsis_aurantiaca$p1$,$p1$en$p1$,$p1$Bright orange(-yellow), cap 2-12 (15) cm, finely felty, margin long inrolled; underside with true, thin, strongly forked, decurrent orange-yellow GILLS that detach easily (the true chanterelle has blunt, firmly fused ridges). Flesh thin, soft, mild/somewhat musty.$p1$,$p1$Gastrointestinal complaints with abdominal pain, diarrhea, nausea, vomiting in larger quantities or in sensitive individuals.$p1$,$p1$In case of complaints, drink plenty of fluids, contact Tox Info Suisse 145; keep mushroom remains.$p1$,$p1$Not recommended for consumption; mildly poisonous, gastrointestinally toxic in larger amounts. Conservative: avoid.$p1$,$p1$Confusion/look-alike: true chanterelle (Cantharellus cibarius) – the false one is the more poisonous; additionally beware the jack-o'-lantern (Omphalotus) with strongly orange-red finds.$p1$,true),
($p1$hypholoma_fasciculare$p1$,$p1$en$p1$,$p1$Cap 2-6 cm, sulphur- to greenish-yellow, centre often orange-/red-brown. Characteristic: gills sulphur-yellow when young, then greenish, finally olive-blackish. Stem yellow, without a true ring (at most a fleeting cortina zone). In clusters on stumps/deadwood. Flesh very bitter.$p1$,$p1$Gastrointestinal syndrome: vomiting, diarrhea, sweating outbreaks, in severe cases visual disturbances and elevated liver values. The strongly bitter taste serves as a warning.$p1$,$p1$Tox Info Suisse 145. Mostly symptomatic; in severe courses monitor liver values.$p1$,$p1$Do not consume. Bitter substances and toxins are cooking-stable.$p1$,$p1$Confusion/look-alike: sheathed woodtuft (Kuehneromyces mutabilis, edible, scaly stem/ring) and the edible conifer tuft / smoky-gilled woodlover (grey gills, mild).$p1$,true),
($p1$infundibulicybe_geotropa$p1$,$p1$en$p1$,$p1$Large funnel-shaped cap with a characteristic central boss (umbo); pale leathery-brown, finely felty when young; white decurrent narrow gills; tough firm stem. Use only young caps, older ones are tough. Slightly poisonous raw – only when cooked.$p1$,$p1$The species itself is not poisonous (slightly stomach-irritating when raw); danger only from confusion with white poisonous funnel caps (Trichterlinge) (muscarine syndrome).$p1$,null,$p1$Only young caps, remove stems (tough); cook through well; popular in soups and mixed dishes.$p1$,$p1$Confusion/look-alike: frosty funnel (Clitocybe phyllophila) and white poisonous funnel caps – muscarine-containing, poisonous (smaller, thinner-fleshed, without an umbo).$p1$,true),
($p1$inocybe_erubescens$p1$,$p1$en$p1$,$p1$Cap 3-9 cm, whitish-cream when young, radially fibrous/cracking, discolouring brick-red to wine-red with age and when injured. Gills pale when young, then olive-/clay-brownish, often reddening. Appears in spring/early summer (at the same time as St. George's mushroom). Spermatic smell.$p1$,$p1$Muscarine syndrome (PSL): 15-30 min after ingestion, heavy sweating, salivation/lacrimation, miosis, abdominal pain, vomiting, diarrhea, drop in blood pressure, bradycardia. 40-50 g fresh can be fatal. Antidote: atropine.$p1$,$p1$Immediately Tox Info Suisse 145 / emergency call 144. Antidote atropine in the clinic; monitor circulation.$p1$,$p1$Never consume. Muscarine is heat-stable.$p1$,$p1$Confusion/look-alike: St. George's mushroom (Calocybe gambosa, edible) – same spring season; also confusable with the miller (Clitopilus prunulus) and young champignons.$p1$,true),
($p1$kuehneromyces_mutabilis$p1$,$p1$en$p1$,$p1$In tufts on hardwood stumps; hygrophanous honey-brown cap that fades from the margin inward, becoming two- or multi-coloured; distinct ring zone on the stem, below the ring zone brownish-scaly (no silvery fibrils); pleasant mushroomy smell. Harvest ONLY with the complete stem - the only reliable way to distinguish it from the Funeral Bell (Galerina).$p1$,$p1$The species itself is edible; LIFE-THREATENING DANGER only from confusion with Galerina marginata (amatoxin syndrome: 6-24h symptom-free, then liver/kidney failure).$p1$,$p1$If confusion with Galerina is suspected, IMMEDIATELY Tox Info Suisse 145 (emergency 144) – amatoxins, any delay is life-threatening; act even if feeling well after the latency period.$p1$,$p1$Cook thoroughly; use only the caps (stems are tough); beginners should refrain because of the deadly risk of confusion.$p1$,$p1$Confusion/look-alike: Funeral Bell (Galerina marginata) - DEADLY, contains amatoxins like the Death Cap; grows intermixed on the same substrate.$p1$,true),
($p1$lactarius_deliciosus$p1$,$p1$en$p1$,$p1$ORANGE MILK when broken, no colour change$p1$,null,null,$p1$frying, pickling, pizza topping$p1$,$p1$Italian classic; the orange milk is its hallmark$p1$,true),
($p1$lactarius_deterrimus$p1$,$p1$en$p1$,$p1$Cap 4-9 (12) cm, orange/orange-flesh-red, faintly zoned, distinctly GREEN-SPOTTING, moist to slimy, depressed at the centre. KEY: milk at first CARROT-/ORANGE-RED, turning WINE-RED/dark red within 15-20 min. Stem orange, WITHOUT pits (difference from the Saffron Milk Cap!). Flesh orange, often greening. Taste mild to slightly bitter. Strictly bound to spruce.$p1$,null,null,$p1$Edible, but less highly regarded than the Saffron Milk Cap (often slightly bitter, frequently maggoty). Fry/grill; not raw. Prefer young, firm specimens.$p1$,$p1$Confusion/look-alike: No deadly confusion. Can be confused with the Saffron Milk Cap and the Salmon Milk Cap (all edible). IMPORTANT: only milk caps with ORANGE-RED milk of this Saffron Milk Cap group are edible; avoid milk caps with white milk or milk that turns sulphur-yellow (e.g. the Woolly Milk Cap L. scrobiculatus).$p1$,true),
($p1$lactarius_piperatus$p1$,$p1$en$p1$,$p1$Large, 6-16 cm, white to cream, when young spotted creamy-yellowish, cap funnel-shaped, surface SMOOTH/bald (not felty - difference from L. vellereus), unzoned. KEY: very CROWDED and narrow, often forked, decurrent gills; white milk abundant, BURNING/PEPPERY HOT, drying olive-/greenish. Flesh white, hard. Stem relatively long, white.$p1$,$p1$When eaten fresh/raw, the acridity may cause gastrointestinal irritation (nausea, vomiting, diarrhea); primarily inedible due to its burning acridity.$p1$,$p1$In case of gastrointestinal symptoms, Tox Info Suisse 145, replace fluids.$p1$,$p1$Inedible - barely edible because of its extreme, persistent acridity; raw/fresh strongly irritating. Not recommended.$p1$,$p1$Confusion/look-alike: No deadly confusion; very similar to the Woolly Milk Cap (felty cap, DISTANT gills), the Greening Peppery Milk Cap (Lactifluus glaucescens) and the white brittlegills (Russula delica) - all acrid/inedible. Distinguish by the crowded gills + smooth cap.$p1$,true),
($p1$lactarius_vellereus$p1$,$p1$en$p1$,$p1$Large, 8-20 (25) cm, chalk-white, cap funnel-/bowl-shaped depressed, surface finely FELTY-WOOLLY (velvety), unzoned, when old ochre-spotted. KEY: very DISTANTLY spaced, thick gills; white milk emerges only sparingly, tastes BURNINGLY ACRID, drying grey-greenish. Flesh hard, white. Often pushes up soil/leaf litter ("earth-shover").$p1$,$p1$When eaten raw/fresh, terpenes cause gastrointestinal irritation up to moderate poisoning (nausea, violent vomiting, cramps; onset 30-60 min); in large quantities visual/coordination disturbances. Primarily inedible (acridity, toughness).$p1$,$p1$In case of gastrointestinal symptoms, Tox Info Suisse 145, replace fluids.$p1$,$p1$Inedible (burningly acrid, hard) - eaten raw/fresh the terpenes can cause gastrointestinal poisoning. Not recommended for the kitchen.$p1$,$p1$Confusion/look-alike: No deadly confusion; similar to the Peppery Milk Cap (L. piperatus, smooth cap, crowded gills) and the white brittlegills (Russula delica). Distinction: vellereus has DISTANT gills + a felty cap.$p1$,true),
($p1$lactarius_volemus$p1$,$p1$en$p1$,$p1$Cap 5-12 cm, orange-brown/cinnamon-brown to foxy yellow-brown, when young velvety, centre depressed, dry. KEY: exudes white milk VERY ABUNDANTLY, MILD (not acrid!), turning fingers/gills rapidly BROWN; characteristic fishy/herring-like smell (disappears on hard frying). Gills cream-coloured, crowded, browning. Flesh firm, white.$p1$,null,null,$p1$Excellent for frying/grilling (hence the name); young specimens are considered edible raw (because of the fox-tapeworm risk/Echinococcus in Switzerland, raw consumption is nevertheless NOT recommended). The fishy smell vanishes on hard frying. Do NOT boil/braise - it becomes slimy.$p1$,$p1$Confusion/look-alike: No dangerous confusion; similar only to the Rugose Milk Cap (Lactifluus rugatus, inedible). Other milk caps with white milk are mostly acrid (taste test).$p1$,true),
($p1$laetiporus_sulphureus$p1$,$p1$en$p1$,$p1$Bracket-/roof-tile-like fan-shaped fruit bodies, sulphur-yellow to orange-yellow, single bracket up to over 30 cm; when young soft and juicy, when old tough and pale. Underside with fine yellow pores (no gills). Grows in tufts on hardwood trunks. Only when young, well cooked through.$p1$,$p1$Gastrointestinal disturbances (diarrhoea, vomiting) when consumed raw/insufficiently cooked; with finds on toxic wood (especially yew) additionally dizziness/drowsiness, potentially more severe poisoning.$p1$,$p1$In case of symptoms, Tox Info Suisse 145; never eat raw, do not use yew/black locust/oak as substrate.$p1$,$p1$Only young, juicy margins; NEVER raw - always cook thoroughly (blanching recommended), breaded like a schnitzel. Prefer finds on fruit wood/willow. IMPORTANT: AVOID specimens on YEW (taxine!), black locust, as well as oak/beech - the substrate toxin can pass into the mushroom.$p1$,null,true),
($p1$leccinum_aurantiacum$p1$,$p1$en$p1$,$p1$Cap golden-orange to orange-red to orange-brown, cap skin somewhat overhanging; stem whitish with predominantly reddish-brownish (not black) scales; flesh white, reddening/wine-red on cut, then grey-black. With aspen/poplar (also oak).$p1$,$p1$Raw or insufficiently cooked: gastrointestinal complaints; rarely also intolerance even after cooking$p1$,null,$p1$Excellent, firm-fleshed edible mushroom. RAW INTOLERABLE/TOXIC - cook thoroughly for at least 15-20 min. Flesh darkens during cooking. Only smaller amounts, since gastrointestinal intolerance has occasionally been reported even when cooked.$p1$,null,true),
($p1$leccinum_pseudoscabrum$p1$,$p1$en$p1$,$p1$Cap yellow-brown to grey- to black-brown, characteristically wrinkled-pitted/hammered; stem stout with dark brown scales; tubes creamy-white, when old olive-grey; flesh white, on cut first grey-violet/pink, then black. Almost only with hornbeam (also hazel). Syn. Leccinellum pseudoscabrum.$p1$,$p1$Raw or insufficiently cooked: gastrointestinal complaints$p1$,null,$p1$Good edible mushroom when young. Like all rough-stemmed boletes, cook thoroughly; food value declines rapidly with age, so collect young. Flesh darkens during cooking.$p1$,null,true),
($p1$leccinum_versipelle$p1$,$p1$en$p1$,$p1$Cap bright yellow-orange to brick-red, finely felted, cap skin overhanging at the margin; stem whitish with black-brown (not red) scales; tubes grey; flesh on cut first grey-violet, then black, stem base blue-greenish. Only with birch.$p1$,$p1$Raw or insufficiently cooked: gastrointestinal complaints$p1$,null,$p1$Very good edible mushroom when young. RAW TOXIC - cook well for at least 15-20 min. Flesh turns black during cooking (does not reduce food value). Remove spongy old tubes.$p1$,null,true),
($p1$lepista_nuda$p1$,$p1$en$p1$,$p1$When young, a fleshy cap coloured blue-violet, later fading brown from the centre; gills and stem violet, crowded; pleasant perfume-like smell; pale-pink (not rust-brown) spore powder - an important distinction from the webcaps.$p1$,$p1$Toxic when raw (gastrointestinal complaints, haemolysins); must be thoroughly heated (>=15 min).$p1$,null,$p1$Never raw; cook well for at least 15 minutes; also suitable for pickling in vinegar.$p1$,$p1$Confusion/look-alike: Violet webcaps (Cortinarius spp.) - rust-brown spore powder, cobweb-like veil; some Cortinarius (e.g. the Fool's Webcap) are deadly.$p1$,true),
($p1$lycoperdon_perlatum$p1$,$p1$en$p1$,$p1$Flask-/pear-shaped with a distinct stem part, 3-10 cm tall; surface with coarse, easily detachable spines/warts that leave behind a net-like pattern. White when young, later yellow-grey-brown. Eat only as long as the inner flesh is pure white; always cut through.$p1$,null,$p1$Cut every spherical/white mushroom LENGTHWISE: (1) if there is a gill rudiment/cap outline inside, discard it (deadly death cap Amanita); (2) if the flesh is firm and violet-black marbled, discard it (poisonous common earthball Scleroderma). Eat only uniformly pure-white gleba.$p1$,$p1$Only when young with pure-white inner flesh; as a mixed mushroom. Becomes slightly tough when cooked; often only as an addition.$p1$,$p1$Confusion/look-alikes: young Amanita phalloides/virosa (spherical stage - gill insertion inside); common earthball (Scleroderma, violet-black flesh).$p1$,true),
($p1$marasmius_oreades$p1$,$p1$en$p1$,$p1$Small tough cap, light ochre to leather-brown, often flatly umbonate; gills white-cream-coloured and strikingly widely spaced; stem tough-elastic, can be twisted without breaking; characteristic spicy smell (bitter almond/clove); dried fruiting bodies revive after being moistened.$p1$,$p1$Raw in large quantities, intolerable due to slight traces of hydrocyanic acid; rendered harmless by cooking.$p1$,null,$p1$Cook thoroughly; remove only the tough stems or chop finely; excellent seasoning and drying mushroom.$p1$,$p1$Confusion/look-alikes: Fool's funnel (Clitocybe rivulosa/dealbata) – muscarine-containing, toxic; in the same grassland habitat (white, crowded gills).$p1$,true),
($p1$marone$p1$,$p1$en$p1$,$p1$Tubes turn blue when pressed, chestnut-brown cap$p1$,null,null,$p1$pan-fry fresh, dry$p1$,$p1$A common alternative to the porcini (cep)$p1$,true),
($p1$maronenroehrling$p1$,$p1$en$p1$,$p1$Chestnut-brown cap colouring, yellow pores, flecks at the stem base, turning blue when pressed$p1$,null,null,$p1$Remove the cap surface, whole or in pieces, pan-fry or boil$p1$,$p1$Popular and common edible mushroom, less prized than the porcini (cep) but reliable$p1$,true),
($p1$morchelchampignon$p1$,$p1$en$p1$,$p1$honeycomb-patterned cap surface, tall stem, characteristic shape$p1$,$p1$no toxins$p1$,$p1$not necessary$p1$,$p1$use only cooked or pan-fried$p1$,$p1$Delicacy, spring mushroom, toxic when raw$p1$,true),
($p1$morchella_elata$p1$,$p1$en$p1$,$p1$Cap conical-pointed, 4-15 cm tall, with distinctly honeycomb-shaped sunken chambers, longitudinally aligned dark ridges, olive-/grey-brown to blackish; stem whitish, cap AND stem completely hollow and smoothly attached at the base of the cap (difference from the false morel/Lorchel). TOXIC WHEN RAW - only well cooked/dried.$p1$,$p1$When consumed raw/insufficiently cooked: gastrointestinal complaints, Morchella syndrome with dizziness, balance/coordination disturbances, trembling, intoxication-like state.$p1$,$p1$In case of neurological symptoms/persistent vomiting Tox Info Suisse 145; never raw, always cook through for at least 15 min. Confusion with the highly toxic Lorchel (false morel) must be ruled out.$p1$,$p1$NEVER raw! Boil well for at least 15 min OR dry for several months; discard the cooking water. Raw/insufficiently cooked: gastrointestinal poisoning or Morchella syndrome. Even when cooked, do not combine with alcohol.$p1$,$p1$Confusion/look-alikes: spring false morel (Gyromitra esculenta) - brain-like convoluted instead of honeycombed, chambered (not hollow) stem, highly toxic/potentially fatal (gyromitrin/MMH).$p1$,true),
($p1$parasol$p1$,$p1$en$p1$,$p1$MOVABLE ring on the stem, white gills, scaly cap surface$p1$,null,null,$p1$breaded and pan-fried like a schnitzel$p1$,$p1$Known as the mushroom schnitzel$p1$,true),
($p1$paxillus_involutus$p1$,$p1$en$p1$,$p1$Cap 5-15 cm, ochre to rust-/olive-brown, when young an inrolled, felty ribbed margin (the source of its name). Gills decurrent, yellowish-ochre, easily detachable from the cap, spotting dark brown when pressed. The entire mushroom discolours brown when damaged.$p1$,$p1$Acute gastrointestinal (vomiting, diarrhea, abdominal/back pain). Dangerous: immunohemolytic Paxillus syndrome after repeated consumption – antibodies destroy erythrocytes (hemolysis), acute kidney failure, shock; rare, but then often severe and potentially FATAL.$p1$,$p1$Tox Info Suisse 145. In a hemolytic crisis emergency: clinic, monitoring of kidney/blood count, if necessary plasmapheresis/dialysis.$p1$,$p1$Do not consume. Toxic even when cooked; immune sensitisation cannot be averted by heating. Its former edible-mushroom status is considered obsolete.$p1$,$p1$Confusion/look-alikes: confusion with other brown gilled mushrooms; formerly mistakenly collected as an edible mushroom.$p1$,true),
($p1$roehrling_flockenstielig$p1$,$p1$en$p1$,$p1$Thick tubes, red pores, red flecks on the yellowish base of the stem, does not turn blue$p1$,$p1$Nausea, vomiting, diarrhea, stomach cramps$p1$,$p1$Contact the poison emergency line 145, symptomatic treatment$p1$,$p1$Not edible$p1$,$p1$Often confused with the edible Scarletina bolete (Flockenstieliger Hexen-Röhrling)$p1$,true),
($p1$roetling$p1$,$p1$en$p1$,$p1$Ring on the stem, reddish discolouration$p1$,$p1$no toxins$p1$,$p1$not necessary$p1$,$p1$pan-fry, braise, soup$p1$,$p1$has become rare, risk of confusion with toxic species$p1$,true),
($p1$rotfuss_hexen_roehrling$p1$,$p1$en$p1$,$p1$Red spores, red pores, characteristic red colouring at the stem base, red cap underside$p1$,$p1$Gastrointestinal complaints when prepared raw$p1$,$p1$Poison emergency line only in case of massive consumption$p1$,$p1$Prepare only after thorough blanching, not raw$p1$,$p1$Assessed controversially; in some countries regarded as an edible mushroom, safe only after blanching$p1$,true),
($p1$rotkappe_birken$p1$,$p1$en$p1$,$p1$Only under birch trees; dark-scaly stem$p1$,null,null,$p1$fry, soup$p1$,$p1$Obligatorily accompanies birch$p1$,true),
($p1$rubroboletus_satanas$p1$,$p1$en$p1$,$p1$Cap strikingly pale whitish-grey to cream-grey; pores bright BLOOD-RED/carmine-red; stem thick, bulbous, yellow with a red net; flesh whitish-yellowish, only faintly/slowly bluing; when old an unpleasant carrion-like odour. Warm calcareous deciduous forests (oak/beech).$p1$,$p1$Violent gastrointestinal symptoms (nausea, repeated vomiting, cramp-like abdominal pain, diarrhea), usually within 1-6 h after consumption; in large amounts affects circulation, rarely life-threatening. Bolesatin inhibits protein synthesis and acts as a hemagglutinin.$p1$,$p1$Call Tox Info Suisse immediately: 145 (24h). Keep mushroom remains/vomit. In case of vomiting/diarrhea, replace fluids, seek medical treatment; do not self-treat with emetics (vomiting-inducing agents).$p1$,$p1$DO NOT EAT - poisonous. Strongly poisonous raw; even cooked it is not safely tolerated. Never treat it as an edible mushroom.$p1$,$p1$Confusion/lookalikes: Lurid bolete (Suillellus luridus) and dotted-stemmed bolete (Neoboletus erythropus) - both edible when cooked, but confusion is dangerous; the Devil's bolete has a pale cap and only weak bluing.$p1$,true),
($p1$russula_cyanoxantha$p1$,$p1$en$p1$,$p1$Cap 5-15 cm, violet-green/lilac-green to blue-green, often mixed in several colours; cap skin peelable to about halfway. DECISIVE FEATURE: soft, flexible, greasy-glossy gills that do NOT splinter (feel like soft soap/bacon fat) - almost all other Russula species have brittle, breaking gills. Flesh white, mild, unchanging; violet-blue beneath the cap skin. Stem white, firm. FeSO4 reaction negative/very weak (difference from other Russula species).$p1$,null,$p1$If confusion with the death cap (Amanita / Knollenblätterpilz) is suspected (nausea/diarrhea 6-24 h after the meal), call Tox Info Suisse 145 IMMEDIATELY - the latency period is life-threatening.$p1$,$p1$Fry, steam young specimens or use in mixed-mushroom dishes; mild, nutty aroma. Older specimens often maggoty - sort out.$p1$,$p1$Confusion/lookalikes: Death cap (Amanita phalloides) - deadly poisonous: green-/violet-discoloured specimens can be confused with it under purely visual identification. RELIABLE distinction ONLY via the missing ring (skirt) and missing bulb/volva at the stem base, as well as via the flexible-elastic gills of the charcoal burner (Russula cyanoxantha). Within the genus: exclude acrid Russula species by taste test.$p1$,true),
($p1$russula_emetica$p1$,$p1$en$p1$,$p1$Cap 4-10 cm, brilliant vermilion to blood-red/cherry-red, fading in patches; cap skin glossy, sticky, easily and widely peelable. KEY: taste IMMEDIATELY BURNING ACRID (spit out the taste sample!). Flesh white, pink beneath the red cap skin, fruity-sweetish odour. Gills pure white, stem white, brittle. Typically in Sphagnum/peat moss of damp coniferous forests.$p1$,$p1$Gastrointestinal syndrome: nausea, violent vomiting, gastrointestinal cramps, diarrhea; onset 15 min to about 2-4 h. Self-limiting, rarely dangerous except in case of fluid loss.$p1$,$p1$In case of complaints, Tox Info Suisse 145 (24h). Replace fluids/electrolytes; keep mushroom remains.$p1$,$p1$Not edible - poisonous. Burning acrid taste = inedible/poisonous.$p1$,$p1$Confusion/lookalikes: Can be confused with edible red Russula species (e.g. apple-scented Russula, Russula paludosa) - reliable separation ONLY via taste test (acrid = poisonous).$p1$,true),
($p1$russula_vesca$p1$,$p1$en$p1$,$p1$Cap 4-12 (15) cm, flesh-red to wine-brown, hazelnut-/leather-brown, greyish-lilac, often blotchily fading; matt, only slightly sticky when young. KEY FEATURE: a too-short (shortened) cap skin that recedes at the margin and exposes the white gill edges like little teeth. Flesh white, mild, almost odourless. Stem white (never reddish), often tapering towards the base, staining yellow-brown when old. FeSO4 reaction distinctly flesh-/orange-pink (good identification feature).$p1$,null,null,$p1$Excellent, mild-nutty edible mushroom; fry, steam, for mixed dishes. Considered one of the best Russula species.$p1$,$p1$Confusion/lookalikes: Within the genus, confusion with other, partly acrid or inedible Russula species (taste test: acrid = do not eat); the bleached Russula (Russula exalbicans) can also show a shortened cap skin but tastes somewhat acrid. No directly deadly confusion, but beginners must reliably distinguish Russula species from brown-capped gilled mushrooms.$p1$,true),
($p1$russula_virescens$p1$,$p1$en$p1$,$p1$Cap 4-15 (20) cm, green/grass-green/verdigris-green on a pale-green-whitish ground (NEVER violet); KEY FEATURE: the cap skin cracks into fields/patches like a mosaic/toad skin, often with dirty-yellow cracks. Flesh white, firm, brittle, mild, pleasantly nutty. Gills white-cream-coloured, brittle. Stem white, brittle, WITHOUT ring and WITHOUT bulb. Note: when young the cap can be almost white and the field-cracked cap skin not yet pronounced.$p1$,null,$p1$If confusion with the death cap (Amanita / Knollenblätterpilz) is suspected (delayed nausea/diarrhea 6-24 h after the meal), call Tox Info Suisse 145 IMMEDIATELY - the latency period is life-threatening, early treatment is decisive.$p1$,$p1$Excellent, nutty edible mushroom, one of the few Russula species edible raw; fry, steam. Collect ONLY when identification is absolutely certain - NOT recommended for beginners.$p1$,$p1$Confusion/lookalikes: Death cap (Amanita phalloides) - DEADLY poisonous. Especially young specimens are easy to confuse (similar green colouring, same habitats). RELIABLE distinction ONLY by digging up the whole mushroom and checking: the green-cracking Russula LACKS a stem skirt (ring) AND a bulb/volva at the stem base; in addition, field-cracking cap skin + brittle gills.$p1$,true),
($p1$sarcodon_imbricatus$p1$,$p1$en$p1$,$p1$Cap 6-15 (30) cm, grey- to light-brown with coarse, roof-tile-like, raised dark-brown scales; underside with grey-brown, brittle spines (no pores/gills). Symbiotic mushroom in (spruce) coniferous forest. Mild when young, increasingly bitter when old.$p1$,$p1$Raw/insufficiently cooked, or in older/bitter specimens, gastrointestinal complaints (nausea, diarrhea).$p1$,null,$p1$Only young specimens; raw/insufficiently heated it is not tolerated, therefore cook through well or blanch. Well-known seasoning mushroom: dry and grind to mushroom powder. Avoid old/bitter specimens.$p1$,null,true),
($p1$schopftintling$p1$,$p1$en$p1$,$p1$Eat ONLY YOUNG; when old it dissolves into an inky mass$p1$,null,$p1$Use immediately: 1 h from harvest to preparation.$p1$,$p1$fry immediately, soup$p1$,$p1$CAUTION with alcohol; coprine - no alcohol for 24h$p1$,true),
($p1$semmelstoppelpilz$p1$,$p1$en$p1$,$p1$Spines instead of gills, pale ochre$p1$,null,null,$p1$fry fresh, season$p1$,$p1$Little risk of confusion for beginners$p1$,true),
($p1$shiitake$p1$,$p1$en$p1$,$p1$Imported/cultivated; CH-native only as cultivated$p1$,null,null,$p1$fry, season, soup$p1$,$p1$Asian classic; CH organic suppliers$p1$,true),
($p1$sparassis_crispa$p1$,$p1$en$p1$,$p1$Cauliflower-/bath-sponge-like fruiting body of curly, wavy, pale-yellow to ochreish lobes, 6-30 (50) cm wide, 2-5 kg heavy; grows at the trunk base/stumps of conifers (especially pine). Flesh white-light-yellow, spicy nutty odour. Do not eat the core/stalk (intolerance).$p1$,null,null,$p1$Clean thoroughly (curly lobes hold sand/needles); blanch briefly or fry in slices; as a creamed mushroom, with bacon/egg or as a pasta substitute. Discard the core/stalk.$p1$,null,true),
($p1$steinpilz$p1$,$p1$en$p1$,$p1$Stem with white netting, tubes greenish when mature$p1$,null,null,$p1$Pan-fry fresh, dry, freeze$p1$,$p1$A classic. Harvest quantities are often limited in Switzerland.$p1$,true),
($p1$suillus_granulatus$p1$,$p1$en$p1$,$p1$Cap yellowish-brown to ochre, slimy-slippery, cap skin peelable; stem WITHOUT a ring, with fine glandular granules at the top (the namesake, often milky droplets); pores pale yellow, fine, not turning blue. Always near pine.$p1$,$p1$In large quantities, mildly laxative.$p1$,null,$p1$A good edible mushroom; peel off the slimy cap skin, cook thoroughly. Larger quantities can have a mild laxative effect.$p1$,null,true),
($p1$suillus_grevillei$p1$,$p1$en$p1$,$p1$Cap bright golden-yellow to yellowish-brown, strongly slimy when moist, cap skin easily peeled off; stem with a membranous ring; pores bright yellow when young, browning when pressed; always near larch. A slippery bolete (Schmierröhrling).$p1$,$p1$In large quantities, mildly laxative (typical of slippery jacks / Suillus species).$p1$,null,$p1$A good edible mushroom, especially when young. Peel off the slimy cap skin before cooking; cook thoroughly. Larger quantities of pure slippery boletes can have a laxative effect.$p1$,null,true),
($p1$suillus_variegatus$p1$,$p1$en$p1$,$p1$Cap yellowish to yellow-olive-brown, finely felty-granular-scaly when young (only somewhat slimy when wet); tubes short, brownish-olive, weakly turning blue when pressed; stem weakly turning blue when cut. Always near pine on acidic sandy soils. Can be confused with the likewise edible cow bolete (Kuhröhrling) (coarser pores, barely turns blue).$p1$,$p1$In large quantities, mildly laxative.$p1$,null,$p1$A good, productive edible mushroom; cook thoroughly. Larger quantities of pure slippery boletes can have a laxative effect.$p1$,null,true),
($p1$tylopilus_felleus$p1$,$p1$en$p1$,$p1$Cap light to olive-brown, resembling a porcino when young; stem with a COARSE, dark-brown net (not fine-white as in the porcino); tubes/pores white when young, soon distinctly turning PINK to flesh-pink; flesh white, EXTREMELY BITTER. Turns pinkish-brown when pressed. The most important look-alike of the porcino – pink tubes + coarse dark net + bitterness give it away. (Latin name Tylopilus felleus.)$p1$,$p1$Mildly toxic: when larger quantities are consumed, gastrointestinal complaints are documented (abdominal colic, nausea, vomiting, diarrhea), in some cases with dizziness/sensation of heat. Main problem: extreme bitterness, which makes even the smallest amounts inedible.$p1$,$p1$If complaints occur after consumption, call Tox Info Suisse 145 (24h); replace fluids.$p1$,$p1$DO NOT EAT – inedible and mildly poisonous. Extremely bitter; even a single specimen spoils an entire dish. The bitterness does not disappear through cooking. A taste test (tiny amount, spit out) reveals it.$p1$,null,true),
($p1$verpa_bohemica$p1$,$p1$en$p1$,$p1$Bell- to thimble-shaped cap 2-4 (5) cm, longitudinally wrinkled-ribbed (brain-/labyrinth-like), light beige to dark brown, attached to the stem ONLY at the apex and hanging down freely like a bell (difference from the morel/Spitzmorchel, whose cap is fully attached); stem whitish, cottony-chambered, hollow. Contains gyromitrin/monomethylhydrazine - poisonous raw.$p1$,$p1$Gastrointestinal complaints, neurological symptoms (dizziness, loss of coordination, slurred speech); with Gyromitrin/MMH potentially liver damage as with the false morel (Lorchel/Gyromitra).$p1$,$p1$Do not consume. In case of accidental consumption / symptoms, immediately contact Tox Info Suisse 145, retain mushroom remnants.$p1$,$p1$Do NOT recommend for consumption. Contains gyromitrin (hydrazine-like, as the false-morel toxin). Poisonous raw like all morels; even when prepared, classified as poisonous/unsafe by many. Conservatively: avoid.$p1$,$p1$Confusion/look-alikes: false morel (Gyromitra esculenta, highly poisonous); edible true morel/Spitzmorchel (attached only at the cap apex vs. fully attached).$p1$,true),
($p1$xerocomus_subtomentosus$p1$,$p1$en$p1$,$p1$Cap olive-brown to yellowish-brown, velvety-felty (when dry); pores bright lemon-yellow, barely turning blue when young, somewhat blue when old; stem pale, faintly yellowish, often with fine longitudinal ribs, without netting; flesh whitish-yellow, barely turning blue, mild. A suede bolete (Filzröhrling).$p1$,null,null,$p1$Edible, of good quality when young; soft-fleshed and inferior when older. Cook thoroughly. Avoid specimens affected by the golden mould (Hypomyces).$p1$,null,true),
($p1$zigeunerpilz$p1$,$p1$en$p1$,$p1$Young cap with white frosted (REIF) coating, ring on the stem$p1$,null,null,$p1$Pan-fry, soup$p1$,$p1$A classic in Swiss mountain regions$p1$,true),
($p1$agaricus_augustus$p1$,$p1$es$p1$,$p1$Sombrero grande, al principio esférico, con escamas pardo-amarillentas sobre fondo claro; marcado olor a anís/almendra amarga; la carne amarillea ligeramente al corte; anillo membranoso; láminas libres, claras de jóvenes, marrón chocolate de viejas. ADVERTENCIA: a menudo acumula cadmio, por lo que solo ocasionalmente y con moderación.$p1$,$p1$Especie comestible; en caso de confusión con el champiñón amarilleante (Agaricus xanthodermus) provoca molestias gastrointestinales. Riesgo propio: acumulación de metales pesados (cadmio). Mortal en caso de confusión con la oronja verde (Amanita phalloides).$p1$,null,$p1$Cocinar bien; apreciada por su olor a anís; por el cadmio, solo con moderación.$p1$,$p1$Confusión/sosias: champiñón de carbol (A. xanthodermus) y champiñón de tinta (A. moelleri) – tóxicos (olor a carbol, base del pie amarillo cromo); de joven, confusión con la amanita blanca/verde del grupo phalloides (comprobar volva/esporada blanca) – mortal.$p1$,true),
($p1$agaricus_campestris$p1$,$p1$es$p1$,$p1$Hábitat de PRADERA, sombrero blanco, láminas rosadas que se vuelven marrones$p1$,null,null,$p1$como el champiñón cultivado$p1$,$p1$PRECAUCIÓN: confusión con el champiñón de carbol (Agaricus xanthodermus), tóxico$p1$,true),
($p1$agaricus_xanthodermus$p1$,$p1$es$p1$,$p1$Sombrero de 5-14 cm, blanco a blanquecino, con el centro a menudo amarronado. Carne blanca; en la base del pie, al presionar o cortar, se tiñe intensamente de AMARILLO CROMO. Olor desagradable a carbol/fenol/tinta (se intensifica al calentar). Láminas rosadas de jóvenes, luego marrón chocolate.$p1$,$p1$Síndrome gastrointestinal: de 15 min a 2 h tras la ingesta, náuseas, vómitos, diarrea, retortijones abdominales. En personas sensibles, de forma intensa. Tóxico tanto crudo como cocido.$p1$,$p1$En caso de molestias, Tox Info Suisse 145. Por lo general, tratamiento sintomático (líquidos/electrolitos).$p1$,$p1$No consumir. El olor a carbol se intensifica al calentar.$p1$,$p1$Confusión/sosias: amanitas mortales (Amanita phalloides/verna) con los champiñones blancos – comprobar bulbo/volva; los champiñones comestibles (champiñón de prado, de anís, ovino) no amarillean en amarillo cromo y no huelen a carbol.$p1$,true),
($p1$albatrellus_confluens$p1$,$p1$es$p1$,$p1$Sombrero de 3-20 cm, de color amarillo masa a pardo pan/dorado, lobulado-abollado, como modelado en masa; a menudo varios cuerpos fructíferos fusionados con pies ramificados; cara inferior con poros finos, redondos, de color blanco amarillento (sin láminas). Micorrízico con pino/coníferas en suelos ácidos. De joven suave, de viejo cada vez más amargo.$p1$,$p1$Crudo o insuficientemente cocido, intolerancia gastrointestinal; los ejemplares viejos resultan amargos y de difícil digestión.$p1$,null,$p1$Solo ejemplares jóvenes; cruda es indigesta, cocinar bien. Fresca es poco sabrosa; mejor conservada en vinagre/aceite. Los ejemplares viejos amargan. (En CH, respetar las normas locales de protección/recolección.)$p1$,null,true),
($p1$amanita_citrina$p1$,$p1$es$p1$,$p1$Sombrero de 4-10 cm, amarillo pálido limón/azufre (también forma blanca var. alba), con restos de velo blanco-amarronados adheridos. Láminas blancas, libres. Pie con anillo y base bulbosa con reborde. Olor a patata cruda/rábano.$p1$,$p1$No comestible a ligeramente tóxico. Se desaconseja encarecidamente su consumo, debido al olor y sabor a patata y, sobre todo, al alto riesgo de confusión con las oronjas blancas/verdes mortales (Amanita phalloides/verna).$p1$,$p1$En caso de ingestión e incertidumbre sobre la especie, Tox Info Suisse 145; descartar la confusión con las oronjas mortales (Amanita).$p1$,$p1$No consumir. Evitar en general por el extremo riesgo de confusión con especies mortales.$p1$,$p1$Confusión/sosias: Amanita phalloides (oronja verde mortal) y la amanita primaveral/blanca – la forma blanca var. alba es especialmente peligrosa por su confusión (¡mortal!).$p1$,true),
($p1$amanita_excelsa$p1$,$p1$es$p1$,$p1$Sombrero de 5-16 cm, gris pardo, con escamas de velo grises, adheridas y fácilmente desprendibles (no verrugosas como la Amanita pantherina). Pie blanco-grisáceo, con anillo ESTRIADO/acanalado (¡decisivo!), base bulbosa, sin reborde marcado. Olor a rábano. Sin. Amanita spissa.$p1$,$p1$Tóxica en crudo (como todas las Amanita del grupo). En Suiza NO está autorizada como seta comestible. El PELIGRO PRINCIPAL es la confusión con la Amanita pantherina, fuerte y potencialmente mortalmente tóxica: síndrome panterínico (pantherina-Syndrom): confusión, alucinaciones, convulsiones y, en casos graves, coma; en niños o con dosis altas se han documentado casos mortales.$p1$,$p1$Ante la sospecha de confusión con la Amanita pantherina, contactar de inmediato con Tox Info Suisse 145.$p1$,$p1$NO consumir. En Suiza no está autorizada como seta comestible; evitar encarecidamente por la confusión con la Amanita pantherina, que puede ser mortal. El anillo/bulbo no son una distinción segura para principiantes.$p1$,$p1$Confusión/sosias: Amanita pantherina – fuerte y potencialmente mortal; la Amanita pantherina tiene el anillo LISO y el bulbo con reborde, mientras que la Amanita excelsa tiene el anillo ESTRIADO y el bulbo sin reborde.$p1$,true),
($p1$amanita_muscaria$p1$,$p1$es$p1$,$p1$Sombrero ROJO con puntos blancos, pie blanco con anillo + bulbo$p1$,$p1$30 min-2 h: confusión, alucinaciones, náuseas.$p1$,$p1$Tox Info Suisse 145 / Emergencias 144. Hospital.$p1$,$p1$NO COMER NUNCA$p1$,$p1$Seta de los cuentos de hadas. Mortal en raras ocasiones, pero peligrosa$p1$,true),
($p1$amanita_pantherina$p1$,$p1$es$p1$,$p1$Sombrero MARRÓN con puntos blancos, bulbo con 2-3 rebordes en la base del pie$p1$,$p1$Más intenso que la Amanita muscaria: náuseas, confusión, convulsiones.$p1$,$p1$Tox Info Suisse 145 / Emergencias 144. Acudir urgentemente al hospital.$p1$,$p1$NUNCA COMER$p1$,$p1$Más tóxica que la Amanita muscaria, más frecuente que las amanitas del grupo phalloides$p1$,true),
($p1$amanita_phalloides$p1$,$p1$es$p1$,$p1$ANILLO en el pie + bulbo dentro de una VOLVA membranosa + láminas blancas + sombrero verde oliva$p1$,$p1$Tormenta gastrointestinal a las 8-24 h, luego aparente mejoría, después insuficiencia hepática en los días 3-5$p1$,$p1$INMEDIATAMENTE Tox Info Suisse 145 / Emergencias 144. Hospital, Silibinin, en su caso trasplante hepático.$p1$,$p1$NO COMER NUNCA$p1$,$p1$Más del 90% de las muertes por intoxicación con setas en Europa. APRENDER A RECONOCERLO SIN CONFUSIÓN POSIBLE$p1$,true),
($p1$amanita_rubescens$p1$,$p1$es$p1$,$p1$Sombrero pardo rojizo con escamas de velo grises (NO blanco puro); decisivo: la carne y las galerías de las larvas enrojecen/toman color vinoso (sobre todo en la base del pie); anillo estriado por arriba; láminas blancas, esporada blanca. NUNCA fiarse de un solo carácter – comprobar todos los caracteres en conjunto. Solo para recolectores experimentados.$p1$,$p1$Tóxica en crudo (las hemolisinas destruyen los glóbulos rojos); debe cocinarse bien. La confusión con Amanita pantherina (Pantherpilz) provoca intoxicaciones graves (síndrome pantherina), en parte mortales.$p1$,$p1$Ante sospecha de confusión con Amanita pantherina (Pantherpilz) (confusión mental, embriaguez, convulsiones) Tox Info Suisse 145 / Emergencias 144.$p1$,$p1$Nunca cruda; cocinar a fondo (destruye las hemolisinas); usar solo con identificación segura (prueba de enrojecimiento + todos los caracteres).$p1$,$p1$Confusión/sosias: Amanita pantherina – fuertemente tóxica, con muertes conocidas (escamas blanco puro, borde del sombrero estriado, base bulbosa con reborde, anillo liso, la carne NUNCA enrojece; los tóxicos son termoestables).$p1$,true),
($p1$amanita_verna$p1$,$p1$es$p1$,$p1$Amanita mortal COMPLETAMENTE BLANCA PURA: sombrero de 5-10 cm, blanco níveo, liso, sedoso-brillante. Láminas blancas, libres, densas. Pie blanco con anillo colgante y vaina membranosa (volva) en la base bulbosa. Aparece sobre todo en primavera/principios de verano. La prueba con KOH de la cutícula del sombrero vira a amarillo.$p1$,$p1$Síndrome faloidiano: latencia de 6-24 h, luego vómitos masivos, diarrea coleriforme, dolor abdominal, aparente mejoría, después insuficiencia hepática y renal. Un solo cuerpo fructífero puede ser mortal.$p1$,$p1$Inmediatamente Tox Info Suisse 145 / Emergencias 144. Conservar los restos de comida. Clínica: Silibinin/N-acetilcisteína, carbón activado – cada hora cuenta.$p1$,$p1$No consumir nunca. Las amatoxinas son termoestables y NO se destruyen al cocinar ni secar.$p1$,$p1$Confusión/sosias: champiñones (estos tienen láminas rosa-marrón, sin volva blanca); una seta blanca, de láminas libres y con volva es SIEMPRE sospechosa.$p1$,true),
($p1$auricularia_auricula_judae$p1$,$p1$es$p1$,$p1$Cuerpo fructífero en forma de oreja, gelatinoso-elástico, gomoso, de 2-10 cm, translúcido de color marrón rojizo a marrón negruzco; cara superior finamente aterciopelada y vellosa, cara inferior lisa-venosa. Crece sobre todo en saúco muerto, también en fresno/arce/haya. Se seca y endurece, se hincha al remojar. Sin sosias tóxicos.$p1$,null,null,$p1$Seta de relleno/mezcla de sabor neutro (Mu-Err de la cocina asiática); almacenable seca, remojar antes de usar; calentar bien. En sopas, wok, ensaladas.$p1$,null,true),
($p1$austernpilz$p1$,$p1$es$p1$,$p1$Crece LATERALMENTE en los árboles, en forma de abanico$p1$,null,null,$p1$Freír, sopa, cultivable$p1$,$p1$Seta de temporada invernal, cultivable en casa$p1$,true),
($p1$boletus_aereus$p1$,$p1$es$p1$,$p1$Sombrero de color marrón café, oscuro a bronce, a veces casi negro, finamente aterciopelado cuando joven; pie grueso y claviforme con retículo fino de color blanco a marrón claro; poros blancos, amarillentos con la edad; carne blanca, que NO azulea, suave. Termófilo (amante del calor).$p1$,null,null,$p1$Excelente seta comestible de carne firme; frita, rehogada, secada. Recolectar con moderación debido a su rareza.$p1$,null,true),
($p1$boletus_reticulatus$p1$,$p1$es$p1$,$p1$Sombrero de color ocre claro a marrón claro, seco y finamente afieltrado (a menudo agrietado en campos); pie con retículo blanquecino a marrón claro, claramente realzado, a lo largo de toda su longitud; tubos blanquecinos, de color amarillo oliva con la edad; carne blanca, que no azulea, suave. Especie temprana (a partir de junio). Importante: descartar el boleto de hiel (Tylopilus felleus) (tubos rosados, retículo grueso y oscuro, extremadamente amargo) mediante una prueba de sabor.$p1$,null,null,$p1$Excelente seta comestible; joven cruda en ensalada o frita, rehogada, secada. Usar joven, ya que se agusana pronto.$p1$,null,true),
($p1$butterpilz$p1$,$p1$es$p1$,$p1$Retirar la piel VISCOSA del sombrero; anillo en el pie$p1$,null,null,$p1$Pelar la piel del sombrero y luego freír$p1$,$p1$Pelar la piel del sombrero es obligatorio, de lo contrario provoca problemas digestivos$p1$,true),
($p1$caloboletus_calopus$p1$,$p1$es$p1$,$p1$Sombrero de color gris claro, arcilloso a gris marrón, finamente afieltrado-seco; poros de color amarillo claro, que azulean al presionar; pie bicolor: amarillo arriba, de color ROJO CARMÍN brillante abajo, con retículo fino (de ahí el nombre 'pie bonito'); carne amarillenta, que azulea al corte, muy AMARGA.$p1$,$p1$Tóxico en crudo; al consumirlo, molestias gastrointestinales (náuseas, vómitos, diarrea). Problema principal adicional: amargor extremo y persistente.$p1$,$p1$En caso de molestias, llamar a Tox Info Suisse 145 (24 h); reponer líquidos y, ante síntomas más intensos, acudir a evaluación médica.$p1$,$p1$NO CONSUMIR: tóxico crudo y extremadamente amargo; el amargor no desaparece con la cocción. Incluso pequeñas cantidades estropean un plato; en caso de ingestión, molestias gastrointestinales.$p1$,null,true),
($p1$calocybe_gambosa$p1$,$p1$es$p1$,$p1$Sombrero carnoso de color blanco crema; decisivo: láminas densamente dispuestas y blancas en CUALQUIER edad y esporada blanca; fuerte olor y sabor harinoso-a pepino; la carne NO vira al rojo; seta primaveral. El olor harinoso y las láminas blancas lo diferencian del mortal Inocybe (cortinario fibroso).$p1$,$p1$Especie comestible; PELIGRO DE MUERTE en caso de confusión con Inocybe erubescens (síndrome muscarínico: salivación/lagrimeo/sudoración intensos, contracción pupilar, vómitos, diarrea, dificultad respiratoria).$p1$,$p1$Ante sospecha de confusión con Inocybe (síntomas muscarínicos), llamar INMEDIATAMENTE a Tox Info Suisse 145 / emergencias 144 – atropina como antídoto.$p1$,$p1$Cocer bien; seta comestible apreciada; solo en caso de identificación inequívoca (láminas blancas, olor harinoso, sin enrojecimiento).$p1$,$p1$Confusión/sosias: Inocybe erubescens (rojo ladrillo): MORTALMENTE tóxico, alto contenido de muscarina; también primaveral; la carne enrojece, láminas gris marrón, esporada marrón. También el tóxico Entoloma sinuatum (Entoloma gigante).$p1$,true),
($p1$calvatia_gigantea$p1$,$p1$es$p1$,$p1$Bola blanca gigante sin pie, de 5-50 (hasta 150) cm de diámetro, de más de 20 kg; joven de color blanco níveo con piel lisa y coriácea, más tarde de color verde amarillento (entonces no comestible). En prados, parques, bordes de bosque. Comer SOLO si la carne interior es blanca como la nieve y sin esbozos de láminas; ¡cortar siempre!$p1$,null,$p1$Cortar siempre longitudinalmente: si presenta estructura interna de láminas/contorno de sombrero (en lugar de carne blanca uniforme), desechar - confusión mortal con el joven Knollenblätterpilz (Amanita).$p1$,$p1$Solo ejemplares jóvenes, blancos como la nieve por dentro; en rebanadas empanadas y fritas (a modo de escalope). Desechar si la carne interior está teñida de amarillo.$p1$,$p1$Confusión/sosias: Amanita phalloides/virosa (jóvenes amanitas como bola blanca, pero reconocibles por dentro por el esbozo de láminas y el contorno del sombrero).$p1$,true),
($p1$cantharellus_tubaeformis$p1$,$p1$es$p1$,$p1$Seta pequeña en forma de embudo/trompeta, sombrero de 1-7 (9) cm, de color amarillo marrón a gris oliva, con el centro surcado/perforado; cara inferior con pliegues bifurcados, decurrentes, de color gris amarillento (no láminas verdaderas); pie delgado, hueco, amarillo. No se conocen confusiones peligrosas.$p1$,null,null,$p1$Muy buena seta para mezclar y secar a pesar de su carne fina; cocer bien. Ideal en platos de setas, sopas, secada.$p1$,null,true),
($p1$champignon-de-paris$p1$,$p1$es$p1$,$p1$Anillo blanco fino en el pie, láminas rosadas en los ejemplares jóvenes, sombrero de color marrón en la forma de cultivo$p1$,null,null,$p1$Crudo en ensaladas o frito, calentar brevemente para conservar el sabor$p1$,$p1$La seta comestible más comprada en Suiza, principalmente de producción de cultivo$p1$,true),
($p1$chlorophyllum_brunneum$p1$,$p1$es$p1$,$p1$Sombrero marrón con escamas gruesas; la carne y las láminas viran al color rojo azafrán/naranja al ser dañadas (enrojecimiento); decisivo: bulbo del pie claramente marginado-tuberoso y diferenciado; anillo simple (a menudo desplazable); SIN dibujo serpenteado en el pie (diferencia respecto al parasol comestible Macrolepiota procera). Crece a menudo sobre/junto al compost.$p1$,$p1$Intoxicación gastrointestinal: náuseas, vómitos, diarrea, calambres abdominales; intensidad variable según la persona; no apto como seta comestible.$p1$,$p1$En caso de molestias tras el consumo, contactar con Tox Info Suisse 145.$p1$,null,$p1$Confusión/sosias: el parasol (Macrolepiota procera) y los apreciados Macrolepiota azafranados comestibles; la confusión provoca intoxicación (el parasol tiene el pie con dibujo serpenteado, sin bulbo marginado).$p1$,true),
($p1$clitocybe_dealbata$p1$,$p1$es$p1$,$p1$Seta pequeña y blanca, sombrero de 2-5 cm, blanco tiza a blanco crema, de joven convexo, después plano hasta deprimido. Láminas blanquecino-crema, apretadas, algo decurrentes. Crece en grupos en céspedes, prados y pastos, a menudo en corros de brujas, con frecuencia junto a Marasmius oreades.$p1$,$p1$Síndrome muscarínico: 15-30 min tras el consumo, salivación/lagrimeo/sudoración intensos, miosis, dolor abdominal, náuseas, diarrea, visión borrosa, dificultad respiratoria. Antídoto: atropina.$p1$,$p1$Tox Info Suisse 145. Antídoto atropina en la clínica.$p1$,$p1$Nunca consumir. La muscarina es estable al calor.$p1$,$p1$Confusión/sosias: Marasmius oreades (comestible) y el champiñón de prado joven, por el mismo hábitat de prado; también con Clitocybe rivulosa (igualmente tóxico).$p1$,true),
($p1$clitocybe_nebularis$p1$,$p1$es$p1$,$p1$Sombrero grande de color gris niebla, con aspecto escarchado y borde enrollado; láminas de color crema, juntas, ligeramente decurrentes; pie robusto y pálido; olor llamativamente dulzón-rancio.$p1$,$p1$Con frecuencia intolerancia individual: trastornos gastrointestinales (náuseas, vómitos, diarrea) incluso con las setas cocidas; la nebularina NO se elimina mediante la cocción.$p1$,null,$p1$La VAPKO de la Suiza alemana clasifica hoy su consumo como problemático (valor comestible cambiado a 'no es seta comestible'): se desaconseja su consumo; si acaso, solo bien cocida y en pequeñas cantidades.$p1$,$p1$Confusión/sosias: Entoloma sinuatum (Riesen-Rötling), altamente tóxico (láminas amarillentas, luego rosa, espaciadas); además el tóxico Tricholoma pardinum (Tiger-Ritterling).$p1$,true),
($p1$clitocybe_rivulosa$p1$,$p1$es$p1$,$p1$Seta pequeña y blanquecina, sombrero de 2-4 cm, de joven escarchado de blanco, a menudo con manchas/surcos escarchados concéntricos (la escarcha se resquebraja), de color rosa carne translúcido. Láminas de color crema-rosa pálido, apretadas, ligeramente decurrentes. Crece en grupos en prados, céspedes y bordes de caminos, a menudo en hileras/corros de brujas.$p1$,$p1$Síndrome muscarínico: 15-30 min tras el consumo, salivación/lagrimeo/sudoración intensos, miosis, dolor abdominal, náuseas, diarrea, visión borrosa. Antídoto: atropina.$p1$,$p1$Tox Info Suisse 145. Antídoto atropina en la clínica.$p1$,$p1$Nunca consumir. La muscarina incluso se libera de su precursor al cocinar: el calentamiento NO destoxifica.$p1$,$p1$Confusión/sosias: Marasmius oreades y el champiñón de prado (mismo hábitat); también con Clitocybe dealbata (igualmente tóxico).$p1$,true),
($p1$cortinarius_orellanus$p1$,$p1$es$p1$,$p1$Sombrero pardo-anaranjado, láminas anaranjadas, pie FIBROSO-anaranjado, TARDÍO sep-nov$p1$,$p1$TARDÍO: insuficiencia renal entre 3 y 14 días después.$p1$,$p1$Inmediatamente Tox Info Suisse 145 / urgencias 144. Hospital, preparación para diálisis (insuficiencia renal).$p1$,$p1$NUNCA COMER, a menudo confundido con el rebozuelo (Pfifferling)$p1$,$p1$Pérfido: la intoxicación aparece recién 1-2 semanas tras la ingesta$p1$,true),
($p1$cortinarius_rubellus$p1$,$p1$es$p1$,$p1$Sombrero de 3-8 cm, de pardo amarillento a pardo anaranjado/pardo herrumbre, cónico con mamelón puntiagudo, seco y finamente afieltrado. Láminas de color canela a pardo herrumbre, espaciadas. Cortina (velo). En bosques de coníferas ácidos y ricos en humus, sobre todo de abeto rojo. Olor a rábano.$p1$,$p1$Síndrome orellánico: latencia muy prolongada, de 2 días hasta 3 semanas. Primero sed, náuseas, dolor de cabeza, de extremidades y renal; después insuficiencia renal grave, a menudo irreversible. Aproximadamente el 50 % queda dependiente de diálisis.$p1$,$p1$De inmediato Tox Info Suisse, número de emergencia 145. Debido a la latencia extremadamente larga, acudir de inmediato a la clínica incluso ante una sospecha tardía; vigilar la función renal y, si es necesario, diálisis.$p1$,$p1$Nunca consumir. La orelanina es estable al calor y resistente a la desecación.$p1$,$p1$Confusión/sosias: Cortinarius orellanus (igualmente mortal); de joven confundible con Cortinarius caperatus y con el rebozuelo (Pfifferling).$p1$,true),
($p1$eierschwamm$p1$,$p1$es$p1$,$p1$Pliegues en lugar de láminas, completamente amarillo yema, olor a albaricoque$p1$,$p1$—$p1$,$p1$—$p1$,$p1$Saltear fresco, no lavar$p1$,$p1$Clásico por su sabor$p1$,true),
($p1$entoloma_sinuatum$p1$,$p1$es$p1$,$p1$Seta grande y carnosa, sombrero de 6-20 cm, de joven de color blanquecino-gris a amarillo arcilla/marfil, liso, ondulado al envejecer. Característica más importante: láminas de jóvenes blanquecinas/amarillentas, luego ROSA CARNE por las esporas (Entoloma/rosado). Olor harinoso/rancio. Pie blanco robusto sin anillo.$p1$,$p1$Síndrome gastrointestinal grave: aprox. 0,5-4 h después de la ingesta, molestias gastrointestinales intensas y cólicas, vómitos, diarrea, pérdida de electrolitos, problemas circulatorios. Para niños, personas mayores y debilitadas, potencialmente mortal.$p1$,$p1$Tox Info Suisse 145. Rehidratación agresiva/reposición de electrolitos; en personas de riesgo, hospitalización.$p1$,$p1$Nunca consumir. Las toxinas son estables a la cocción; es uno de los desencadenantes más frecuentes de intoxicaciones gastrointestinales graves en Europa.$p1$,$p1$Confusión/sosias: Calocybe gambosa (comestible, láminas blancas densas, más temprano en el año), Clitopilus prunulus (Mehlräsling), champiñones jóvenes, Entoloma clypeatum (Schildrötling).$p1$,true),
($p1$flaemmling$p1$,$p1$es$p1$,$p1$Sombrero de pequeño tamaño, fibroso-finamente escamoso, habita en la madera$p1$,$p1$sin toxinas$p1$,$p1$no es necesario$p1$,$p1$Solo joven y fresco, se recomienda cocinar$p1$,$p1$Tierno, pero con poca capacidad de conservación$p1$,true),
($p1$fliegenpilz-grosspilz$p1$,$p1$es$p1$,$p1$Sombrero plegado como un cerebro, con cavidades huecas, similar a la colmenilla (Morchel)$p1$,$p1$Dolor de cabeza, náuseas, diarrea, mareo, calambres$p1$,$p1$Número de emergencia toxicológica 145, protección gástrica$p1$,$p1$No comestible$p1$,$p1$A menudo confundido con la colmenilla comestible (Morchel)$p1$,true),
($p1$fliegenpilz-roetlich$p1$,$p1$es$p1$,$p1$Pardo con escamitas blancas, anillo y bulbo$p1$,$p1$Dolor de cabeza, mareo, confusión$p1$,$p1$Número de emergencia toxicológica 145, tratamiento$p1$,$p1$No comestible$p1$,$p1$Más raro que la amanita matamoscas (Fliegenpilz)$p1$,true),
($p1$fliegenpilz_var_alba$p1$,$p1$es$p1$,$p1$Sombrero blanco con escamitas blancas, anillo y volva blancos; puede confundirse con setas comestibles$p1$,$p1$Embriaguez, calambres musculares, confusión, alucinaciones$p1$,$p1$Número de emergencia toxicológica 145, considerar lavado gástrico$p1$,$p1$No comestible$p1$,$p1$Forma variante de la amanita matamoscas (Fliegenpilz), tóxica igual que la forma roja$p1$,true),
($p1$flockenstieliger-hexen-roehrling$p1$,$p1$es$p1$,$p1$Poros rojos, azulea al presionar, escamas/copos rojos en el pie, carne amarilla que se torna roja$p1$,$p1$Náuseas, vómitos, calambres estomacales en caso de cocción insuficiente$p1$,$p1$Consulta médica en caso de síntomas de intoxicación$p1$,$p1$Cocer/hervir bien durante al menos 20 minutos, no comer crudo, preparar a fondo$p1$,$p1$Comestible solo tras una preparación a fondo; se confunde a menudo con el venenoso Flockenstieliger Hexen-Röhrling (boleto de pie áspero)$p1$,true),
($p1$flockenstieliger_hexenpilz$p1$,$p1$es$p1$,$p1$Punteado RUDO/áspero en el pie, tubos rojos, azulea RÁPIDAMENTE al presionar$p1$,$p1$cocido sin problemas, crudo molestias leves$p1$,null,$p1$DEBE cocinarse durante 15+ min; crudo provoca una intoxicación leve$p1$,$p1$A pesar de su aspecto alarmante, muy apreciado$p1$,true),
($p1$fomitopsis_betulina$p1$,$p1$es$p1$,$p1$Poliporo anual, en forma de consola/pezuña, de 5-20 cm, exclusivamente sobre abedules; cara superior lisa, de color gris a pardo claro con el margen incurvado y sobresaliente, cara inferior con poros blancos finos. Carne blanca de joven, blanda-corchosa, después cada vez más amarga. Conocido hongo vital/medicinal (hongo de Ötzi).$p1$,null,null,$p1$No es hongo comestible (tenaz, amargo). Tradicionalmente como hongo medicinal/vital: cuerpos fructíferos jóvenes y blancos secados como té/extracto. No como plato.$p1$,null,true),
($p1$galerina_marginata$p1$,$p1$es$p1$,$p1$Sombrero pequeño de 1-7 cm, de color pardo amarillento a miel/pardo oscuro, a menudo con centro más oscuro, higrófano. Láminas pálidas de jóvenes, después pardo herrumbre, adheridas. Anillo fino y fugaz en el pie (a menudo desaparece pronto). En grupos/manojos o solitario sobre madera muerta de coníferas (también de frondosas), tocones podridos.$p1$,$p1$Síndrome faloidiano: 6-24 h de latencia, luego vómitos intensos, diarrea, dolores abdominales, recuperación aparente, después insuficiencia hepática y renal. 100-150 g pueden ser mortales.$p1$,$p1$Llamar de inmediato a Tox Info Suisse, número de emergencia 145 (o 144). Conservar los restos de los hongos. Clínica con sospecha de intoxicación por amatoxina. Terapia con Silibinin. Cada hora cuenta.$p1$,$p1$No consumir nunca. Las amatoxinas son termoestables, NO se destruyen al cocinar/secar.$p1$,$p1$Confusión/sosias: Stockschwämmchen (Kuehneromyces mutabilis) – comestible, pero la confusión más peligrosa; Galerina no tiene el pie escamoso por debajo del anillo.$p1$,true),
($p1$gemeiner-fliegenpilz-var-alba$p1$,$p1$es$p1$,$p1$Sombrero de color blanco a gris pardo sin escamas, velo blanco bajo el anillo, bulbo en la base del pie con volva$p1$,$p1$Inicio retardado tras 6-24 h, molestias estomacales intensas, insuficiencia hepática, mortal$p1$,$p1$Llamar de inmediato al médico de urgencias, se requiere tratamiento de emergencia$p1$,$p1$No comestible$p1$,$p1$Una de las especies de hongos más mortales de Europa, riesgo de confusión con el champiñón blanco$p1$,true),
($p1$hallimasch$p1$,$p1$es$p1$,$p1$ANILLO en el pie, de color amarillo miel, parásito en raíces de árboles, en grupos/manojos$p1$,$p1$crudo, molestias gastrointestinales$p1$,$p1$si hay malestar, acudir al hospital$p1$,$p1$DEBE COCINARSE durante 15+ min, nunca crudo$p1$,$p1$Aparición en masa. NUNCA crudo, muy bueno bien cocinado$p1$,true),
($p1$herbsttrompete$p1$,$p1$es$p1$,$p1$Trompeta hueca de color gris oscuro a negro$p1$,null,null,$p1$secar como condimento de invierno$p1$,$p1$Tesoro gourmet suizo$p1$,true),
($p1$hygrophoropsis_aurantiaca$p1$,$p1$es$p1$,$p1$De color naranja (amarillo) intenso, sombrero de 2-12 (15) cm, finamente afieltrado, margen mucho tiempo enrollado; cara inferior con verdaderas LÁMINAS naranja-amarillas, finas, muy bifurcadas y decurrentes, que se desprenden con facilidad (el rebozuelo verdadero tiene pliegues romos y firmemente unidos). Carne delgada, blanda, suave/algo mohosa.$p1$,$p1$Molestias gastrointestinales con dolores abdominales, diarrea, náuseas, vómitos en cantidades mayores o en personas sensibles.$p1$,$p1$En caso de molestias, beber mucho líquido, contactar a Tox Info Suisse 145; conservar los restos de los hongos.$p1$,$p1$No recomendado para el consumo; ligeramente tóxico, en cantidades mayores es tóxico gastrointestinal. Conservador: evitar.$p1$,$p1$Confusión/sosias: rebozuelo verdadero (Cantharellus cibarius) - el falso es el más tóxico; precaución además con el Ölbaumpilz (Omphalotus, seta del olivo) ante hallazgos de un naranja rojizo intenso.$p1$,true),
($p1$hypholoma_fasciculare$p1$,$p1$es$p1$,$p1$Sombrero de 2-6 cm, de amarillo azufre a amarillo verdoso, centro a menudo pardo anaranjado/rojizo. Característico: láminas amarillo azufre de jóvenes, luego verdosas y finalmente oliva-negruzcas. Pie amarillo, sin anillo verdadero (a lo sumo una zona cortiniforme fugaz). En manojos sobre tocones/madera muerta. Carne muy amarga.$p1$,$p1$Síndrome gastrointestinal: vómitos, diarrea, ataques de sudoración, en casos graves alteraciones de la visión y elevación de los valores hepáticos. El sabor fuertemente amargo advierte.$p1$,$p1$Tox Info Suisse 145. Por lo general sintomático; en casos graves controlar los valores hepáticos.$p1$,$p1$No consumir. Las sustancias amargas y las toxinas son estables a la cocción.$p1$,$p1$Confusión/sosias: Stockschwämmchen (Kuehneromyces mutabilis, comestible, pie escamoso/anillo) y el comestible Rauchblättriger Schwefelkopf (cabeza de azufre de láminas grises, suave).$p1$,true),
($p1$infundibulicybe_geotropa$p1$,$p1$es$p1$,$p1$Sombrero grande en forma de embudo con un característico mamelón central; de color pardo cuero pálido, finamente afieltrado de joven; láminas blancas, decurrentes y apretadas; pie tenaz y firme. Usar solo los sombreros jóvenes, los más viejos son tenaces. Crudo ligeramente tóxico – solo cocinado.$p1$,$p1$La especie en sí no es tóxica (cruda, ligeramente irritante para el estómago); el peligro existe solo por confusión con los embudos blancos venenosos (síndrome muscarínico).$p1$,null,$p1$Solo sombreros jóvenes, retirar los pies (tenaces); cocer bien; apreciado en sopas y platos mixtos.$p1$,$p1$Confusión/sosias: Bleiweisser Firnis-Trichterling (Clitocybe phyllophila) y los Trichterlinge (clitocibes) blancos venenosos – contienen muscarina, venenosos (más pequeños, de carne más delgada, sin mamelón).$p1$,true),
($p1$inocybe_erubescens$p1$,$p1$es$p1$,$p1$Sombrero de 3-9 cm, de joven blanquecino-crema, fibroso radial/agrietado, con la edad y al herirse se torna rojo ladrillo a rojo vino. Láminas pálidas de jóvenes, después de tono oliva/arcilloso pardo, a menudo enrojeciendo. Aparece en primavera/principios de verano (al mismo tiempo que el Maipilz/seta de San Jorge). Olor espermático.$p1$,$p1$Síndrome muscarínico (PSL): 15-30 min tras la ingesta, sudoración intensa, salivación/lagrimeo, miosis, dolor abdominal, vómitos, diarrea, caída de la presión arterial, bradicardia. 40-50 g en fresco pueden ser mortales. Antídoto: Atropina.$p1$,$p1$De inmediato Tox Info Suisse 145 / Emergencias 144. Antídoto Atropina en la clínica; vigilar la circulación.$p1$,$p1$No consumir nunca. La muscarina es termoestable.$p1$,$p1$Confusión/sosias: Maipilz (Calocybe gambosa, comestible) – misma temporada primaveral; también confundible con el Mehlräsling (Clitopilus prunulus) y con champiñones jóvenes.$p1$,true),
($p1$kuehneromyces_mutabilis$p1$,$p1$es$p1$,$p1$En grupos sobre tocones de madera de frondosas; sombrero higrófano de color pardo miel que se decolora desde el borde de forma bi- o multicolor; zona anular marcada en el pie, POR DEBAJO de la zona anular escamoso pardusco (sin fibrillas plateadas); olor agradable a hongo. Recolectar SOLO con el pie completo: es la única diferenciación segura frente al Galerina venenoso.$p1$,$p1$La especie en sí es comestible; PELIGRO DE MUERTE solo por confusión con Galerina marginata (síndrome amatoxínico: 6-24 h sin síntomas, luego insuficiencia hepática/renal).$p1$,$p1$Ante sospecha de confusión con Galerina, INMEDIATAMENTE Tox Info Suisse 145 (emergencia 144) – amatoxinas, cualquier demora es potencialmente mortal; actuar incluso si hay bienestar tras el período de latencia.$p1$,$p1$Cocinar bien; usar solo los sombreros (los pies son correosos); los principiantes deberían abstenerse por el peligro mortal de confusión.$p1$,$p1$Confusión/sosias: Galerina marginata (galera marginada) – MORTAL, contiene amatoxinas como la oronja verde (Amanita phalloides); crece mezclada en el mismo sustrato.$p1$,true),
($p1$lactarius_deliciosus$p1$,$p1$es$p1$,$p1$LECHE NARANJA al romperse, sin cambio de color.$p1$,null,null,$p1$Freír, encurtir, como cobertura de pizza.$p1$,$p1$Clásico italiano. La leche naranja es su sello distintivo.$p1$,true),
($p1$lactarius_deterrimus$p1$,$p1$es$p1$,$p1$Sombrero de 4-9 (12) cm, naranja/rojizo anaranjado carnoso, débilmente zonado, claramente CON MANCHAS VERDES, húmedo y viscoso, deprimido en el centro. CLAVE: la leche es al principio ROJO ZANAHORIA/ANARANJADA, y se vuelve en 15-20 min ROJO VINO/rojo oscuro. Pie naranja, SIN hoyuelos (¡diferencia con Lactarius deliciosus!). Carne naranja, a menudo verdeante. Sabor suave a ligeramente amargo. Estrictamente ligado al abeto rojo (Picea).$p1$,null,null,$p1$Comestible, pero menos apreciado que Lactarius deliciosus (a menudo ligeramente amargo, frecuentemente con gusanos). Freír/asar a la parrilla; no en crudo. Preferir ejemplares jóvenes y firmes.$p1$,$p1$Confusión/sosias: ninguna confusión mortal. Confundible con Lactarius deliciosus y Lactarius salmonicolor (todos comestibles). IMPORTANTE: solo los lactarios con leche ROJO ANARANJADA de este grupo de Lactarius son comestibles; evitar los lactarios con leche blanca o que vire a amarillo azufre (p. ej. Lactarius scrobiculatus, el lactario hoyoso).$p1$,true),
($p1$lactarius_piperatus$p1$,$p1$es$p1$,$p1$Grande, 6-16 cm, blanco a crema, de joven manchado de amarillo cremoso, sombrero embudado, superficie LISA/glabra (no afieltrada, diferencia con L. vellereus), no zonado. CLAVE: láminas muy APRETADAS y estrechas, a menudo bifurcadas y decurrentes; leche blanca abundante, de sabor ARDIENTE/PIMENTADO PICANTE, que seca en tono oliváceo/verdoso. Carne blanca, dura. Pie relativamente largo, blanco.$p1$,$p1$Si se consume fresco/crudo, por el sabor acre es posible una irritación gastrointestinal (náuseas, vómitos, diarrea); principalmente no comestible debido a su acritud ardiente.$p1$,$p1$En caso de molestias gastrointestinales, Tox Info Suisse 145, reponer líquidos.$p1$,$p1$No comestible: apenas comestible por su picor extremo y persistente; en crudo/fresco fuertemente irritante. No recomendado.$p1$,$p1$Confusión/sosias: ninguna confusión mortal; muy parecido al Lactarius vellereus (sombrero afieltrado, láminas ESPACIADAS), al Lactifluus glaucescens (lactario que verdea) y a las rúsulas blancas (Russula delica): todos picantes/no comestibles. Diferenciación por las láminas apretadas y el sombrero liso.$p1$,true),
($p1$lactarius_vellereus$p1$,$p1$es$p1$,$p1$Grande, 8-20 (25) cm, blanco tiza, sombrero embudado/acopado y deprimido, superficie finamente AFIELTRADA-LANUDA (aterciopelada), no zonado, de viejo con manchas ocres. CLAVE: láminas muy ESPACIADAS y gruesas; la leche blanca sale solo escasamente, sabe ARDIENTE PICANTE y seca en tono gris verdoso. Carne dura, blanca. A menudo levanta consigo tierra/hojarasca (empuja la tierra).$p1$,$p1$Si se consume crudo/fresco, por los terpenos puede causar irritación gastrointestinal hasta intoxicación moderada (náuseas, vómitos intensos, calambres; inicio a los 30-60 min); en grandes cantidades, alteraciones de la visión y de la coordinación. Principalmente no comestible (sabor acre, dureza).$p1$,$p1$En caso de molestias gastrointestinales, Tox Info Suisse 145, reponer líquidos.$p1$,$p1$No comestible (ardiente picante, duro): consumido crudo/fresco son posibles intoxicaciones gastrointestinales por los terpenos. No recomendado para la cocina.$p1$,$p1$Confusión/sosias: ninguna confusión mortal; parecido al Lactarius piperatus (sombrero liso, láminas apretadas) y a las rúsulas blancas (Russula delica). Diferenciación: vellereus tiene láminas ESPACIADAS y sombrero afieltrado.$p1$,true),
($p1$lactarius_volemus$p1$,$p1$es$p1$,$p1$Sombrero de 5-12 cm, pardo anaranjado/pardo canela a pardo amarillento aleonado, de joven aterciopelado, deprimido en el centro, seco. CLAVE: exuda leche blanca MUY ABUNDANTE, SUAVE (¡no picante!), que en los dedos/láminas se vuelve rápidamente PARDA; olor característico a pescado/arenque (desaparece al freír a fuego fuerte). Láminas color crema, apretadas, pardeantes. Carne firme, blanca.$p1$,null,null,$p1$Excelente para freír/asar a la parrilla (¡por su nombre!); los ejemplares jóvenes se consideran consumibles en crudo (por el riesgo de la tenia del zorro/Echinococcus en Suiza, NO se recomienda igualmente el consumo en crudo). El olor a pescado se disipa al freír a fuego fuerte. NO hervir/rehogar: se vuelve mucilaginoso.$p1$,$p1$Confusión/sosias: ninguna confusión peligrosa; similar solo al Lactifluus rugatus (lactario rugoso, no comestible). Otros lactarios de leche blanca son en su mayoría picantes (probar una pequeña muestra).$p1$,true),
($p1$laetiporus_sulphureus$p1$,$p1$es$p1$,$p1$Cuerpos fructíferos en forma de consola/imbricados, en abanico, de color amarillo azufre a amarillo anaranjado, consola individual de más de 30 cm; de joven blando y jugoso, de viejo correoso y pálido. Cara inferior con finos poros amarillos (sin láminas). Crece en grupos sobre troncos de frondosas. SOLO de joven y bien cocinado.$p1$,$p1$Trastornos gastrointestinales (diarrea, vómitos) por consumo crudo/insuficientemente cocido; en hallazgos sobre madera tóxica (sobre todo tejo / Eibe), adicionalmente mareo/aturdimiento, potencialmente una intoxicación más grave.$p1$,$p1$En caso de molestias, Tox Info Suisse 145; nunca comer crudo, no utilizar como sustrato tejo/robinia/roble (Eibe/Robinie/Eiche).$p1$,$p1$Solo los bordes jóvenes y jugosos; NUNCA en crudo: siempre bien cocinado (se recomienda blanquear), empanado como un escalope. Preferir hallazgos sobre árboles frutales/sauce. IMPORTANTE: EVITAR ejemplares sobre TEJO (¡taxina!), robinia, así como roble/haya: el veneno del sustrato puede pasar al hongo.$p1$,null,true),
($p1$leccinum_aurantiacum$p1$,$p1$es$p1$,$p1$Sombrero de naranja dorado a rojo anaranjado a pardo anaranjado, cutícula algo sobresaliente; pie blanquecino con escamillas predominantemente rojizo-parduscas (no negras); carne blanca, que al corte enrojece/vira a rojo vino, luego gris negruzco. Junto al álamo temblón/chopo (también roble).$p1$,$p1$Crudo o insuficientemente cocido: molestias gastrointestinales; en raras ocasiones, también intolerancia tras la cocción$p1$,null,$p1$Excelente comestible de carne firme. CRUDO MAL TOLERADO/VENENOSO: cocinar bien al menos 15-20 min. La carne oscurece durante la cocción. Solo cantidades pequeñas, ya que incluso cocinado se han notificado casos aislados de intolerancia gastrointestinal.$p1$,null,true),
($p1$leccinum_pseudoscabrum$p1$,$p1$es$p1$,$p1$Sombrero de pardo amarillento a pardo gris o pardo negruzco, característicamente rugoso-hoyoso/como golpeado a martillazos; pie robusto con escamillas pardo oscuras; tubos blanco crema, de viejo gris oliváceo; carne blanca, que al corte es primero gris violácea/rosa, luego negra. Casi exclusivamente junto al carpe (también avellano). Sin. Leccinellum pseudoscabrum.$p1$,$p1$Crudo o insuficientemente cocido: molestias gastrointestinales$p1$,null,$p1$Buen comestible de joven. Como todos los Leccinum, cocinar bien; el valor culinario decae rápidamente con la edad, por lo que conviene recolectarlo joven. La carne oscurece durante la cocción.$p1$,null,true),
($p1$leccinum_versipelle$p1$,$p1$es$p1$,$p1$Sombrero de amarillo anaranjado brillante a rojo ladrillo, finamente afieltrado, cutícula sobresaliente en el borde; pie blanquecino con escamillas pardo negruzcas (no rojas); tubos grises; carne al corte primero gris violácea, luego negra, base del pie azul verdosa. Solo junto al abedul.$p1$,$p1$Crudo o insuficientemente cocido: molestias gastrointestinales$p1$,null,$p1$Muy buen comestible de joven. CRUDO VENENOSO: cocinar bien al menos 15-20 min. La carne se vuelve negra al cocinarla (no merma el valor culinario). Retirar los tubos esponjosos viejos.$p1$,null,true),
($p1$lepista_nuda$p1$,$p1$es$p1$,$p1$Sombrero carnoso de color azul violáceo en la juventud, luego decolorándose a pardo desde el centro; láminas y pie violetas, apretadas; olor agradable, perfumado; esporada rosa pálido (no pardo herrumbre): diferenciación importante frente a los Cortinarius.$p1$,$p1$Crudo es tóxico (molestias gastrointestinales, hemolisinas); debe calentarse a fondo (>=15 min).$p1$,null,$p1$Nunca en crudo; cocinar bien al menos 15 minutos; también apto para encurtir en vinagre.$p1$,$p1$Confusión/sosias: Cortinarius violetas (Cortinarius spp.) – esporada pardo herrumbre, velo aracnoideo; algunos Cortinarius (p. ej. Cortinarius orellanus, el cortinario de montaña) son mortales.$p1$,true),
($p1$lycoperdon_perlatum$p1$,$p1$es$p1$,$p1$Con forma de botella/pera con una parte de pie bien marcada, 3-10 cm de altura; superficie con espinas/verrugas gruesas y que se desprenden fácilmente, dejando un patrón reticulado. De joven blanco, después pardo amarillo-grisáceo. Comer solo mientras la carne interior sea de un blanco puro; cortar siempre.$p1$,null,$p1$Cortar LONGITUDINALMENTE cualquier hongo esférico/blanco: (1) si en el interior hay esbozo de láminas/contorno del sombrero, desecharlo (Amanita, el mortal hongo de la oronja verde/cicuta verde); (2) si la carne es firme y veteada de color violeta-negruzco, desecharlo (el tóxico falso pedo de lobo/bovista de patata, Scleroderma). Comer únicamente gleba de color blanco puro y uniforme.$p1$,$p1$Solo de joven con la carne interior de un blanco puro; como seta de mezcla. Al cocerse se vuelve fácilmente correosa; a menudo solo como acompañamiento.$p1$,$p1$Confusión/sosias: Amanita phalloides/virosa jóvenes (en estado esférico - en el interior, inserción de láminas); escleroderma (Scleroderma, carne violeta-negra).$p1$,true),
($p1$marasmius_oreades$p1$,$p1$es$p1$,$p1$Sombrero pequeño y correoso, de color ocre claro a pardo cuero, a menudo con un mamelón plano; láminas de color blanco-cremoso y notablemente separadas entre sí; pie correoso-elástico, que se puede retorcer sin romperse; olor especiado característico (almendra amarga/clavo); los cuerpos fructíferos secos reviven tras humedecerse.$p1$,$p1$Crudo y en grandes cantidades, indigesto debido a leves trazas de ácido cianhídrico; se vuelve inocuo mediante la cocción.$p1$,null,$p1$Cocer bien; retirar solo los pies correosos o cortarlos finamente; excelente seta de condimento y para secar.$p1$,$p1$Confusión/sosias: el clitocibe blanco (Clitocybe rivulosa/dealbata) – contiene muscarina, tóxico; en el mismo hábitat de pradera (blanco, láminas apretadas).$p1$,true),
($p1$marone$p1$,$p1$es$p1$,$p1$Los tubos se vuelven azules al presionar, sombrero de color castaño$p1$,null,null,$p1$Freír fresco, secar$p1$,$p1$Alternativa frecuente al boletus comestible (Steinpilz)$p1$,true),
($p1$maronenroehrling$p1$,$p1$es$p1$,$p1$Sombrero de color castaño, poros amarillos, copos en la base del pie, se torna azul al presionar$p1$,null,null,$p1$Retirar la superficie del sombrero; entero o en trozos, freír o cocer$p1$,$p1$Seta comestible popular y frecuente, menos valiosa que el boletus comestible (Steinpilz) pero fiable$p1$,true),
($p1$morchelchampignon$p1$,$p1$es$p1$,$p1$Superficie del sombrero con aspecto de panal, pie alto, forma característica$p1$,$p1$sin toxinas$p1$,$p1$no es necesaria$p1$,$p1$Utilizar solo cocido o frito$p1$,$p1$Manjar, especie de primavera, tóxico en crudo$p1$,true),
($p1$morchella_elata$p1$,$p1$es$p1$,$p1$Sombrero cónico-puntiagudo, de 4-15 cm de altura, con cámaras claramente hundidas en forma de panal, costillas oscuras orientadas longitudinalmente, de color oliva/pardo grisáceo a negruzco; pie blanquecino, sombrero Y pie completamente huecos y unidos de forma lisa en la base del sombrero (diferencia respecto a la falsa colmenilla/Lorchel). TÓXICO EN CRUDO - solo bien cocido/secado.$p1$,$p1$En caso de consumo crudo o insuficientemente cocido: molestias gastrointestinales, síndrome de Morchella con mareos, trastornos del equilibrio y de la coordinación, temblores, estado de tipo embriaguez.$p1$,$p1$En caso de síntomas neurológicos o vómitos persistentes, Tox Info Suisse 145; nunca crudo, cocinar siempre completamente durante al menos 15 minutos. Es imprescindible descartar la confusión con la Lorchel (Gyromitra), altamente tóxica.$p1$,$p1$¡NUNCA en crudo! Cocer bien al menos 15 min O secar durante varios meses; desechar el agua de cocción. En crudo/insuficientemente cocido: intoxicación gastrointestinal o síndrome de Morchella. Tampoco combinar con alcohol estando cocida.$p1$,$p1$Confusión/sosias: la falsa colmenilla de primavera (Gyromitra esculenta) - retorcida como un cerebro en lugar de alveolada, pie cameroso (no hueco), altamente tóxica/potencialmente mortal (giromitrina/MMH).$p1$,true),
($p1$parasol$p1$,$p1$es$p1$,$p1$Anillo MÓVIL en el pie, láminas blancas, superficie del sombrero escamosa$p1$,null,null,$p1$Freír empanado como un escalope$p1$,$p1$Conocido como escalope de seta$p1$,true),
($p1$paxillus_involutus$p1$,$p1$es$p1$,$p1$Sombrero de 5-15 cm, de color ocre a pardo herrumbroso/oliváceo, de joven con el borde enrollado, afieltrado y acostillado (de ahí su nombre). Láminas decurrentes, de color amarillento-ocre, fáciles de desprender del sombrero, manchándose de pardo oscuro al presionar. Todo el hongo se torna pardo al sufrir heridas.$p1$,$p1$Agudo gastrointestinal (vómitos, diarrea, dolores abdominales y de espalda). Peligroso: síndrome inmunohemolítico por Paxillus tras el consumo repetido — los anticuerpos destruyen los eritrocitos (hemólisis), insuficiencia renal aguda, shock; raro, pero entonces a menudo grave y potencialmente MORTAL.$p1$,$p1$Tox Info Suisse 145. En caso de crisis hemolítica, emergencia: clínica, vigilancia del riñón y del hemograma, en su caso plasmaféresis/diálisis.$p1$,$p1$No consumir. Tóxico también cocido; la sensibilización inmunitaria no se puede evitar mediante el calentamiento. Su antiguo estatus de seta comestible se considera obsoleto.$p1$,$p1$Confusión/sosias: confusión con otros hongos laminados pardos; antiguamente recolectado erróneamente como seta comestible.$p1$,true),
($p1$roehrling_flockenstielig$p1$,$p1$es$p1$,$p1$Tubos gruesos, poros rojos, copos rojos sobre la base amarillenta del pie, no se vuelve azul$p1$,$p1$Náuseas, vómitos, diarrea, calambres estomacales.$p1$,$p1$Contactar al número de emergencias toxicológicas 145, tratamiento sintomático.$p1$,$p1$No comestible$p1$,$p1$A menudo confundido con el comestible boletus de Satanás de pie con copos (Flockenstieliger Hexen-Röhrling)$p1$,true),
($p1$roetling$p1$,$p1$es$p1$,$p1$Anillo en el pie, coloración rojiza$p1$,$p1$sin toxinas$p1$,$p1$no es necesaria$p1$,$p1$Freír, estofar, sopa$p1$,$p1$Se ha vuelto raro, riesgo de confusión con especies tóxicas$p1$,true),
($p1$rotfuss_hexen_roehrling$p1$,$p1$es$p1$,$p1$Esporas rojas, poros rojos, coloración roja característica en la base del pie, cara inferior del sombrero roja$p1$,$p1$Molestias gastrointestinales en caso de preparación cruda.$p1$,$p1$Llamar al número de emergencias toxicológicas solo en caso de consumo masivo.$p1$,$p1$Preparar únicamente tras un escaldado a fondo, nunca en crudo$p1$,$p1$Valorado de forma controvertida; en algunos países se considera seta comestible, seguro solo tras el escaldado$p1$,true),
($p1$rotkappe_birken$p1$,$p1$es$p1$,$p1$Solo bajo abedules; pie con escamas oscuras$p1$,null,null,$p1$freír; sopa$p1$,$p1$Acompaña al abedul de forma obligada$p1$,true),
($p1$rubroboletus_satanas$p1$,$p1$es$p1$,$p1$Sombrero llamativamente claro, de blanquecino-gris a gris crema; poros de un ROJO SANGRE/carmín intenso; pie grueso, bulboso, amarillo con retículo rojo; carne blanco-amarillenta, que azulea solo débil/tardíamente; de viejo, olor desagradable a carroña. Bosques caducifolios cálidos sobre suelo calcáreo (roble/haya).$p1$,$p1$Síntomas gastrointestinales intensos (náuseas, vómitos repetidos, dolores abdominales tipo cólico, diarrea), por lo general dentro de 1-6 h tras la ingesta; en grandes cantidades afecta a la circulación, rara vez es potencialmente mortal. La bolesatina inhibe la síntesis de proteínas y tiene acción hemaglutinante.$p1$,$p1$Llamar de inmediato a Tox Info Suisse: 145 (24h). Conservar los restos de setas/el vómito. En caso de vómitos/diarrea reponer líquidos, tratamiento médico; no automedicarse con inductores del vómito.$p1$,$p1$NO CONSUMIR – tóxico. Crudo es fuertemente tóxico; tampoco es seguro ni tolerable cocido. No convertir nunca en hongo comestible.$p1$,$p1$Confusión/sosias: el boleto de pie reticulado (Suillellus luridus) y el boleto de pie granuloso (Neoboletus erythropus) – ambos comestibles una vez cocidos, pero la confusión es peligrosa; el boleto de Satanás tiene el sombrero claro y azulea solo débilmente.$p1$,true),
($p1$russula_cyanoxantha$p1$,$p1$es$p1$,$p1$Sombrero de 5-15 cm, de verde violáceo/verde lila a verde azulado, a menudo con varios colores mezclados; cutícula separable hasta la mitad. CARÁCTER DECISIVO: láminas blandas, flexibles, de brillo graso, que NO se quiebran (al tacto son como jabón blando/tocino); casi todas las demás rúsulas tienen láminas frágiles y quebradizas. Carne blanca, suave, inalterable; bajo la cutícula, violeta-azulada. Pie blanco, firme. Reacción al FeSO4 negativa/muy débil (diferencia con otras rúsulas).$p1$,null,$p1$En caso de sospecha de confusión con la oronja verde (Knollenblätterpilz) (náuseas/diarrea 6-24h después de la comida) llamar INMEDIATAMENTE a Tox Info Suisse 145 - el periodo de latencia es potencialmente mortal.$p1$,$p1$Ejemplares jóvenes salteados, rehogados o en platos de hongos mixtos; aroma suave a nuez. Los ejemplares más viejos suelen estar agusanados: descartarlos.$p1$,$p1$Confusión/sosias: la oronja verde (Amanita phalloides) – mortalmente tóxica: los ejemplares de tonos verdes/violáceos pueden confundirse con ella en una determinación puramente visual. La distinción SEGURA SOLO es posible por la ausencia de anillo (manguito) y la ausencia de bulbo/volva en la base del pie, así como por las láminas flexibles y elásticas de la rúsula. Dentro del género: descartar las rúsulas de sabor picante mediante una cata de prueba.$p1$,true),
($p1$russula_emetica$p1$,$p1$es$p1$,$p1$Sombrero de 4-10 cm, de un rojo bermellón intenso a rojo sangre/rojo cereza, que se decolora a manchas; cutícula brillante, pegajosa, que se separa fácilmente y en gran extensión. CLAVE: sabor INMEDIATAMENTE ARDIENTE Y PICANTE (¡escupir la cata de prueba!). Carne blanca, rosada bajo la cutícula roja, olor afrutado-dulzón. Láminas blanco puro, pie blanco, frágil. Típico en esfagnos/musgos de turbera de bosques de coníferas húmedos.$p1$,$p1$Síndrome gastrointestinal: náuseas, vómitos intensos, calambres gastrointestinales, diarrea; inicio entre 15 min y aprox. 2-4 h. Autolimitado, rara vez peligroso salvo por pérdida de líquidos.$p1$,$p1$En caso de molestias, Tox Info Suisse 145 (24h). Reponer líquidos/electrolitos; conservar los restos de setas.$p1$,$p1$No consumible – tóxico. Sabor ardiente y picante = no comestible/tóxico.$p1$,$p1$Confusión/sosias: confundible con rúsulas rojas comestibles (p. ej. la rúsula de manzana Russula paludosa) – la distinción segura SOLO es posible mediante la cata de prueba (picante = tóxico).$p1$,true),
($p1$russula_vesca$p1$,$p1$es$p1$,$p1$Sombrero de 4-12 (15) cm, de rojo carne a pardo vinoso, pardo avellana/cuero, gris lila, a menudo decolorándose a manchas; mate, algo viscoso solo de joven. CARÁCTER CLAVE: cutícula demasiado corta (acortada), que se retira en el margen y deja al descubierto las puntas blancas de las láminas como pequeños dientecitos. Carne blanca, suave, casi inodora. Pie blanco (nunca rojizo), a menudo estrechado hacia la base, manchándose de pardo amarillento con la edad. Reacción al FeSO4 claramente rosa carne/rosa anaranjado (buen carácter de determinación).$p1$,null,null,$p1$Excelente hongo comestible, suave y con sabor a nuez; salteado, rehogado, para platos mixtos. Considerado una de las mejores rúsulas.$p1$,$p1$Confusión/sosias: dentro del género, confusión con otras rúsulas, en parte picantes o no comestibles (cata de prueba: picante = no comer); la rúsula decolorante (Russula exalbicans) también puede mostrar la cutícula acortada, pero su sabor es algo picante. No hay confusión directamente mortal, pero los principiantes deben distinguir con seguridad las rúsulas de los hongos laminados de sombrero pardo.$p1$,true),
($p1$russula_virescens$p1$,$p1$es$p1$,$p1$Sombrero de 4-15 (20) cm, verde/verde hierba/verde cardenillo sobre fondo verde pálido-blanquecino (NUNCA violeta); CARÁCTER CLAVE: la cutícula se agrieta en placas/areolada como un mosaico/piel de sapo, a menudo con grietas de un amarillo sucio. Carne blanca, firme, frágil, suave, agradablemente a nuez. Láminas blanco-cremosas, frágiles. Pie blanco, quebradizo, SIN anillo y SIN bulbo. Atención: de joven, el sombrero puede ser casi blanco y la cutícula areolada aún no estar marcada.$p1$,null,$p1$En caso de sospecha de confusión con la oronja verde (Knollenblätterpilz) (náuseas/diarrea retardadas 6-24h después de la comida) llamar INMEDIATAMENTE a Tox Info Suisse 145 - el periodo de latencia es potencialmente mortal, el tratamiento temprano es decisivo.$p1$,$p1$Excelente hongo comestible con sabor a nuez, una de las pocas rúsulas consumibles en crudo; salteada, rehogada. Recolectar SOLO con una determinación absolutamente segura – NO recomendada para principiantes.$p1$,$p1$Confusión/sosias: la oronja verde (Amanita phalloides) – MORTALMENTE tóxica. Especialmente los ejemplares jóvenes son fáciles de confundir (coloración verde similar, mismos hábitats). La distinción SEGURA SOLO es posible desenterrando el hongo entero y examinándolo: a la rúsula verdosa areolada le FALTAN el manguito del pie (anillo) Y el bulbo/volva en la base del pie; además, cutícula que se agrieta en placas + láminas frágiles.$p1$,true),
($p1$sarcodon_imbricatus$p1$,$p1$es$p1$,$p1$Sombrero de 6-15 (30) cm, de gris a pardo claro, con escamas pardo oscuras gruesas, erguidas y dispuestas como tejas; cara inferior con aguijones pardo grisáceos y quebradizos (sin poros/láminas). Hongo simbionte de bosques de coníferas (sobre todo de abetos rojos). De joven suave, de viejo cada vez más amargo.$p1$,$p1$Crudo/insuficientemente cocido o en ejemplares viejos/amargos, molestias gastrointestinales (náuseas, diarrea).$p1$,null,$p1$Solo ejemplares jóvenes; crudo/insuficientemente calentado es indigesto, por lo que hay que cocinarlo bien o blanquearlo. Conocido hongo condimentario: secar y moler hasta obtener polvo de hongo. Evitar los ejemplares viejos/amargos.$p1$,null,true),
($p1$schopftintling$p1$,$p1$es$p1$,$p1$Comer SOLO JOVEN; viejo se deshace en una masa tipo tinta$p1$,null,$p1$consumir de inmediato, 1h de la recolección a la preparación$p1$,$p1$freír de inmediato; sopa$p1$,$p1$PRECAUCIÓN con el alcohol; coprina: no consumir alcohol durante 24h$p1$,true),
($p1$semmelstoppelpilz$p1$,$p1$es$p1$,$p1$Aguijones en lugar de láminas, de color ocre claro$p1$,null,null,$p1$freír fresco; condimentar$p1$,$p1$Poco riesgo de confusión para principiantes$p1$,true),
($p1$shiitake$p1$,$p1$es$p1$,$p1$Importado/cultivado; en Suiza autóctono solo cultivado$p1$,null,null,$p1$freír; condimentar; sopa$p1$,$p1$Clásico asiático; proveedores ecológicos suizos$p1$,true),
($p1$sparassis_crispa$p1$,$p1$es$p1$,$p1$Cuerpo fructífero tipo coliflor/esponja de baño, formado por lóbulos rizados, ondulados, de amarillo pálido a ocráceo, de 6-30 (50) cm de ancho y de 2-5 kg de peso; crece en la base del tronco/los tocones de coníferas (sobre todo el pino). Carne de blanca a amarillo claro, con olor especiado a nuez. No comer el tronco/base (intolerancia).$p1$,null,null,$p1$Limpiar a fondo (los lóbulos rizados retienen arena/acículas); blanquear brevemente o freír en lonchas; como hongo a la crema, con tocino/huevo o como sustituto de la pasta. Desechar el tronco/base.$p1$,null,true),
($p1$steinpilz$p1$,$p1$es$p1$,$p1$Pie con retículo blanco; tubos verdosos al madurar$p1$,null,null,$p1$saltear fresco, secar, congelar$p1$,$p1$Un clásico. La cantidad de recolección suele estar limitada en Suiza.$p1$,true),
($p1$suillus_granulatus$p1$,$p1$es$p1$,$p1$Sombrero de color pardo amarillento a ocre, untuoso-viscoso, cutícula desprendible; pie SIN anillo, con finos granulitos glandulares en la parte superior (de ahí su nombre, a menudo con gotitas lechosas); poros amarillo pálido, finos, que no azulean. Siempre junto a pinos (Pinus).$p1$,$p1$En grandes cantidades, levemente laxante$p1$,null,$p1$Buen hongo comestible; retirar la cutícula viscosa del sombrero, cocinar bien. Grandes cantidades pueden tener un ligero efecto laxante.$p1$,null,true),
($p1$suillus_grevillei$p1$,$p1$es$p1$,$p1$Sombrero de color amarillo dorado intenso a pardo amarillento, muy viscoso con la humedad, cutícula que se desprende fácilmente; pie con anillo membranoso; poros jóvenes de amarillo intenso, que pardean al presionar; siempre junto a alerces (Larix). Boleto viscoso (Suillus).$p1$,$p1$En grandes cantidades, levemente laxante (típico de los boletos viscosos / Suillus)$p1$,null,$p1$Buen hongo comestible, sobre todo joven. Retirar la cutícula viscosa del sombrero antes de cocinar; cocinar bien. Grandes cantidades de boletos viscosos puros pueden tener efecto laxante.$p1$,null,true),
($p1$suillus_variegatus$p1$,$p1$es$p1$,$p1$Sombrero de color amarillento a pardo amarillo-oliváceo, de joven finamente afieltrado-granuloso-escamoso (solo algo viscoso con la humedad); tubos cortos, de color pardo-oliváceo, que azulean débilmente al presionar; pie que azulea débilmente al corte. Siempre junto a pinos (Pinus) en suelos arenosos ácidos. Posible confusión con el boleto de vaca (Suillus bovinus), también comestible (poros más gruesos, apenas azulea).$p1$,$p1$En grandes cantidades, levemente laxante$p1$,null,$p1$Buen hongo comestible y abundante; cocinar bien. Grandes cantidades de boletos viscosos puros pueden tener efecto laxante.$p1$,null,true),
($p1$tylopilus_felleus$p1$,$p1$es$p1$,$p1$Sombrero de color pardo claro a pardo oliváceo, de joven parecido al boleto comestible (Steinpilz); pie con un retículo GRUESO de color pardo oscuro (no fino y blanco como en el Steinpilz); tubos/poros de joven blancos, que pronto viran claramente a ROSA o rosa carne; carne blanca, EXTREMADAMENTE AMARGA. Vira a pardo rosado al presionar. Es el principal sosias del boleto comestible: los tubos rosados, el retículo grueso y oscuro y el amargor lo delatan.$p1$,$p1$Levemente tóxico: con el consumo de cantidades mayores se han documentado molestias gastrointestinales (cólicos abdominales, náuseas, vómitos, diarrea), en parte con mareos/sensación de calor. Problema principal: el amargor extremo, que vuelve incomibles incluso las cantidades más pequeñas.$p1$,$p1$En caso de molestias tras el consumo, llamar a Tox Info Suisse 145 (24 h); reponer líquidos.$p1$,$p1$NO CONSUMIR: incomible y débilmente tóxico. Extremadamente amargo; un solo ejemplar estropea todo un plato. El amargor no desaparece al cocinar. Una prueba de sabor (mínima, escupir) lo delata.$p1$,null,true),
($p1$verpa_bohemica$p1$,$p1$es$p1$,$p1$Caperuza acampanada en forma de dedal de 2-4 (5) cm, longitudinalmente arrugada-acostillada (de aspecto cerebriforme/laberíntico), de color beige claro a pardo oscuro, unida al pie SOLO por el ápice y colgando libremente como una campana (a diferencia de la colmenilla puntiaguda, cuyo sombrero está totalmente adherido); pie blanquecino, hueco con cámaras algodonosas. Contiene giromitrina/monometilhidrazina: tóxica en crudo.$p1$,$p1$Trastornos gastrointestinales, síntomas neurológicos (mareos, pérdida de coordinación, habla poco clara); en caso de Gyromitrin/MMH, posible daño hepático como en las falsas colmenillas (Lorchel/Gyromitra).$p1$,$p1$No consumir. En caso de ingestión accidental / síntomas, contactar de inmediato a Tox Info Suisse 145 y conservar los restos del hongo.$p1$,$p1$NO recomendar para el consumo. Contiene giromitrina (similar a la hidrazina, como el veneno de la giromitra/Lorchel). Tóxica en crudo, como todas las colmenillas; incluso preparada, muchos la clasifican como tóxica/insegura. De forma conservadora: evitar.$p1$,$p1$Confusión/sosias: giromitra de primavera (Gyromitra esculenta, muy tóxica); colmenilla puntiaguda comestible (adherida solo en el ápice de la caperuza, frente a totalmente adherida).$p1$,true),
($p1$xerocomus_subtomentosus$p1$,$p1$es$p1$,$p1$Sombrero de color pardo oliváceo a pardo amarillento, aterciopelado-afieltrado (en seco); poros de color amarillo limón intenso, que de joven apenas azulean y de viejo algo más; pie claro, de color amarillento pálido, a menudo con finas costillas longitudinales, sin retículo; carne de color blanquecino-amarillento, que apenas azulea, de sabor suave. Boleto afieltrado (Xerocomus).$p1$,null,null,$p1$Comestible, de buena calidad cuando es joven; de viejo tiene carne blanda y es de calidad inferior. Cocinar bien. Evitar los ejemplares atacados por el moho dorado (Hypomyces).$p1$,null,true),
($p1$zigeunerpilz$p1$,$p1$es$p1$,$p1$Sombrero joven con una capa de PRUINA blanca; anillo en el pie$p1$,null,null,$p1$saltear, sopa$p1$,$p1$Un clásico de las regiones de montaña suizas$p1$,true),
($p1$agaricus_augustus$p1$,$p1$fr$p1$,$p1$Grand chapeau, sphérique au début, avec des écailles brun jaunâtre sur fond clair ; nette odeur d'anis/d'amande amère ; chair jaunissant faiblement à la coupe ; anneau membraneux ; lamelles libres, claires au jeune âge, brun chocolat à maturité. AVERTISSEMENT : accumule souvent du cadmium, donc seulement occasionnellement et avec modération.$p1$,$p1$Espèce comestible ; en cas de confusion avec l'agaric jaunissant (Karbol-Champignon), troubles gastro-intestinaux. Risque propre : accumulation de métaux lourds (cadmium). Mortel en cas de confusion avec l'amanite (Knollenblätterpilz/Amanita).$p1$,null,$p1$Bien cuire à cœur ; apprécié pour son odeur d'anis ; en raison du cadmium, seulement avec modération.$p1$,$p1$Confusion/sosies : agaric jaunissant (A. xanthodermus) et agaric de Moeller (A. moelleri) – toxiques (odeur de carbol, base du pied jaune chrome) ; jeune, confusion possible avec l'amanite phalloïde blanche/verte (vérifier la volve/la sporée blanche) – mortel.$p1$,true),
($p1$agaricus_campestris$p1$,$p1$fr$p1$,$p1$Habitat de PRAIRIE, chapeau blanc, lamelles roses qui brunissent$p1$,null,null,$p1$comme le champignon de Paris cultivé$p1$,$p1$ATTENTION confusion possible avec l'agaric jaunissant (agaric carbolique), toxique$p1$,true),
($p1$agaricus_xanthodermus$p1$,$p1$fr$p1$,$p1$Chapeau 5-14 cm, blanc à blanchâtre, centre souvent un peu brunâtre. Chair blanche, virant fortement au JAUNE CHROME à la pression/à la coupe à la base du pied. Odeur désagréable de carbol/phénol/encre (accentuée à la chauffe). Lamelles roses au jeune âge, puis brun chocolat.$p1$,$p1$Syndrome gastro-intestinal : 15 min à 2 h après la consommation, nausées, vomissements, diarrhée, crampes abdominales. Violent chez les personnes sensibles. Toxique cru et cuit.$p1$,$p1$En cas de troubles, Tox Info Suisse 145. Le plus souvent symptomatique (liquides/électrolytes).$p1$,$p1$Ne pas consommer. L'odeur de carbol s'accentue à la chauffe.$p1$,$p1$Confusion/sosies : amanites mortelles (Amanita phalloides/verna) avec les agarics blancs – vérifier le bulbe/la volve ; les champignons comestibles (agaric champêtre, agaric anisé, agaric des moutons) ne jaunissent pas au jaune chrome et ne sentent pas le carbol.$p1$,true),
($p1$albatrellus_confluens$p1$,$p1$fr$p1$,$p1$Chapeau jaune pâteux à brun pain/brun doré, lobé-bosselé, 3-20 cm, comme façonné dans de la pâte ; souvent plusieurs carpophores aux pieds ramifiés et soudés ; face inférieure à pores fins, ronds, blanc jaunâtre (pas de lamelles). Mycorhize avec le pin/les conifères sur sols acides. Doux jeune, de plus en plus amer avec l'âge.$p1$,$p1$Cru/insuffisamment cuit, intolérance gastro-intestinale ; les vieux exemplaires sont amers/difficiles à digérer.$p1$,null,$p1$Seulement les jeunes exemplaires ; intolérable cru, bien cuire à cœur. Peu savoureux frais, de préférence mariné comme champignon au vinaigre/à l'huile. Les vieux deviennent amers. (En CH, respecter les prescriptions locales de protection/de cueillette.)$p1$,null,true),
($p1$amanita_citrina$p1$,$p1$fr$p1$,$p1$Chapeau 4-10 cm, jaune citron/soufre pâle (aussi forme blanche var. alba), avec des restes de voile blanc-brunâtre appliqués. Lamelles blanches, libres. Pied avec anneau et base bulbeuse marginée. Odeur de pomme de terre crue/de rave.$p1$,$p1$Immangeable à faiblement toxique. La consommation est fortement déconseillée – en raison de l'odeur/du goût de pomme de terre et surtout du risque élevé de confusion avec les amanites blanches/vertes mortelles (Amanita).$p1$,$p1$En cas de consommation et d'incertitude sur l'espèce, Tox Info Suisse 145 – exclure une confusion avec les amanites mortelles (Amanita).$p1$,$p1$Ne pas consommer. À éviter de manière générale en raison de l'extrême risque de confusion avec des espèces mortelles.$p1$,$p1$Confusion/sosies : amanite phalloïde (Amanita phalloides) et amanite printanière/amanite blanche – la forme blanche var. alba présente un risque de confusion particulièrement dangereux (mortelle !).$p1$,true),
($p1$amanita_excelsa$p1$,$p1$fr$p1$,$p1$Chapeau 5-16 cm, brun gris, avec des flocons de voile gris, appliqués, facilement détachables (non verruqueux comme l'amanite panthère). Pied blanc-gris, avec anneau STRIÉ/cannelé (déterminant !), base bulbeuse non nettement marginée. Odeur de rave. Syn. Amanita spissa.$p1$,$p1$Toxique cru (comme toutes les amanites à volve). En Suisse, NON autorisée comme champignon comestible. Le DANGER PRINCIPAL est la confusion avec l'amanite panthère (Amanita pantherina), fortement/potentiellement mortellement toxique : syndrome pantherinien – confusion, hallucinations, convulsions, dans les cas graves coma ; chez les enfants/à fortes doses, des décès sont documentés.$p1$,$p1$En cas de suspicion de confusion avec l'amanite panthère, appeler immédiatement Tox Info Suisse 145.$p1$,$p1$NE PAS consommer. En Suisse, non autorisée comme champignon comestible ; à éviter impérativement en raison de la confusion potentiellement mortelle avec l'amanite panthère. L'anneau/le bulbe ne constituent pas une distinction fiable pour les débutants.$p1$,$p1$Confusion/sosies : amanite panthère (Amanita pantherina) – fortement, potentiellement mortellement toxique ; l'amanite panthère a un anneau LISSE et un bulbe marginé, l'amanite épaisse un anneau STRIÉ et un bulbe non marginé.$p1$,true),
($p1$amanita_muscaria$p1$,$p1$fr$p1$,$p1$Chapeau ROUGE à pois blancs, pied blanc avec anneau + bulbe$p1$,$p1$30 min à 2 h : confusion, hallucinations, nausées.$p1$,$p1$Tox Info Suisse 145 / Urgences 144. Hôpital.$p1$,$p1$NE JAMAIS CONSOMMER$p1$,$p1$Champignon des contes de fées. Mortel rarement, mais dangereux$p1$,true),
($p1$amanita_pantherina$p1$,$p1$fr$p1$,$p1$Chapeau BRUN à pois blancs, bulbe avec 2-3 bourrelets à la base du pied$p1$,$p1$Plus violent que l'amanite tue-mouches : nausées, confusion, convulsions.$p1$,$p1$Tox Info Suisse 145 / Urgences 144. Urgent : aller à l'hôpital.$p1$,$p1$NE JAMAIS CONSOMMER$p1$,$p1$Plus toxique que l'amanite tue-mouches, plus fréquent que l'amanite phalloïde$p1$,true),
($p1$amanita_phalloides$p1$,$p1$fr$p1$,$p1$ANNEAU sur le pied + bulbe dans une VOLVE membraneuse + lamelles blanches + chapeau vert olive$p1$,$p1$Tempête gastro-intestinale 8-24 h, puis amélioration apparente, puis insuffisance hépatique aux jours 3-5$p1$,$p1$IMMÉDIATEMENT Tox Info Suisse 145 / urgence 144. Hôpital, Silibinin, le cas échéant transplantation hépatique.$p1$,$p1$NE JAMAIS CONSOMMER$p1$,$p1$Plus de 90 % des décès par intoxication aux champignons en Europe. À APPRENDRE À RECONNAÎTRE DE FAÇON INFAILLIBLE$p1$,true),
($p1$amanita_rubescens$p1$,$p1$fr$p1$,$p1$Chapeau brun rougeâtre avec des flocons de voile gris (PAS blanc pur) ; déterminant : la chair et les galeries de vers rougissent/virent au rouge vineux (surtout à la base du pied) ; anneau strié sur le dessus ; lamelles blanches, sporée blanche. NE JAMAIS se fier à un seul caractère – vérifier tous les caractères ensemble. Réservé aux cueilleurs expérimentés.$p1$,$p1$Toxique cru (les hémolysines détruisent les globules rouges); doit être bien cuit. La confusion avec Amanita pantherina entraîne des intoxications graves (syndrome pantherinien), parfois mortelles.$p1$,$p1$En cas de suspicion de confusion avec Amanita pantherina (confusion mentale, ivresse, convulsions) Tox Info Suisse 145 / urgence 144.$p1$,$p1$Jamais cru ; bien cuire à cœur (détruit les hémolysines) ; à utiliser uniquement en cas de détermination sûre (test de rougissement + tous les caractères).$p1$,$p1$Confusion/sosies : amanite panthère (Amanita pantherina) – fortement toxique, décès connus (flocons blanc pur, marge du chapeau striée, base bulbeuse marginée, anneau lisse, chair ne rougissant JAMAIS ; toxines thermostables).$p1$,true),
($p1$amanita_verna$p1$,$p1$fr$p1$,$p1$Amanite entièrement BLANC PUR : chapeau 5-10 cm, blanc neige, lisse et soyeux-brillant. Lamelles blanches, libres, serrées. Pied blanc avec anneau pendant et gaine membraneuse (volve) à la base bulbeuse. Apparaît surtout au printemps/début de l'été. Le test KOH de la cuticule du chapeau devient jaune.$p1$,$p1$Syndrome phalloïdien: latence de 6-24 h, puis vomissements massifs, diarrhée cholériforme, douleurs abdominales, amélioration apparente, ensuite insuffisance hépatique et rénale. Un seul carpophore peut déjà être mortel.$p1$,$p1$Immédiatement Tox Info Suisse 145 / appel d'urgence 144. Conserver les restes du repas. Clinique: Silibinin/N-acétylcystéine, charbon actif – chaque heure compte.$p1$,$p1$Ne jamais consommer. Les amatoxines sont thermostables, elles ne sont PAS détruites par la cuisson ou le séchage.$p1$,$p1$Confusion/sosies : agarics/champignons de couche (ceux-ci ont des lamelles rose-brun, pas de volve blanche) ; un champignon blanc à lamelles libres muni d'une volve est TOUJOURS suspect.$p1$,true),
($p1$auricularia_auricula_judae$p1$,$p1$fr$p1$,$p1$Carpophore en forme d'oreille, gélatineux-élastique, caoutchouteux, 2-10 cm, translucide, brun-rouge à brun-noir; face supérieure veloutée finement velue, face inférieure lisse-veinée. Pousse le plus souvent sur le sureau mort, aussi sur le frêne/l'érable/le hêtre. Sèche en durcissant, gonfle au trempage. Aucun sosie toxique.$p1$,null,null,$p1$Champignon de remplissage/de mélange au goût neutre (le Mu-Err de la cuisine asiatique); se conserve séché, faire tremper avant emploi; bien chauffer. Dans les soupes, au wok, en salade.$p1$,null,true),
($p1$austernpilz$p1$,$p1$fr$p1$,$p1$Pousse LATÉRALEMENT sur les arbres, en éventail$p1$,$p1$—$p1$,$p1$—$p1$,$p1$à la poêle, en soupe, cultivable$p1$,$p1$Champignon de saison hivernale, cultivable à la maison$p1$,true),
($p1$boletus_aereus$p1$,$p1$fr$p1$,$p1$Chapeau brun café, brun foncé à bronze, parfois presque noir, finement velouté lorsqu'il est jeune; pied épais et claviforme avec un fin réseau blanc à brun clair; pores blancs, jaunâtres avec l'âge; chair blanche, NE bleuissant PAS, douce. Thermophile.$p1$,null,null,$p1$Champignon comestible excellent, à chair ferme; poêlé, étuvé, séché. En raison de sa rareté, le cueillir avec ménagement.$p1$,null,true),
($p1$boletus_reticulatus$p1$,$p1$fr$p1$,$p1$Chapeau ocre clair à brun clair, sec et finement feutré (se craquelant souvent en aréoles), pied portant un réseau blanchâtre à brun clair, nettement saillant, sur toute sa longueur; tubes blanchâtres, jaune-olive avec l'âge; chair blanche, ne bleuissant pas, douce. Espèce précoce (dès juin). Important: exclure le bolet amer (Tylopilus felleus: tubes roses, réseau grossier et foncé, extrêmement amer) au moyen d'un test gustatif.$p1$,null,null,$p1$Excellent champignon comestible; jeune cru en salade ou poêlé, étuvé, séché. À utiliser jeune, car véreux précocement.$p1$,null,true),
($p1$butterpilz$p1$,$p1$fr$p1$,$p1$Retirer la peau VISQUEUSE du chapeau, anneau sur le pied$p1$,$p1$—$p1$,$p1$—$p1$,$p1$Peler la peau du chapeau puis faire revenir$p1$,$p1$Peler la peau du chapeau est obligatoire — sinon troubles digestifs$p1$,true),
($p1$caloboletus_calopus$p1$,$p1$fr$p1$,$p1$Chapeau gris clair, couleur argile à gris-brun, finement feutré-sec; pores jaune clair, bleuissant à la pression; pied bicolore – jaune en haut, ROUGE CARMIN éclatant en bas, avec un fin réseau (d'où le nom 'bolet à beau pied'); chair jaunâtre, bleuissant à la coupe, très AMÈRE.$p1$,$p1$Toxique cru; en cas de consommation, troubles gastro-intestinaux (nausées, vomissements, diarrhée). Problème principal supplémentaire: amertume extrême et persistante.$p1$,$p1$En cas de troubles, appeler Tox Info Suisse 145 (24h); compenser les pertes de liquide, en cas de symptômes plus sévères consulter un médecin.$p1$,$p1$NE PAS CONSOMMER – toxique cru et extrêmement amer; l'amertume ne disparaît pas à la cuisson. De petites quantités déjà gâchent un plat; en cas de consommation, troubles gastro-intestinaux.$p1$,null,true),
($p1$calocybe_gambosa$p1$,$p1$fr$p1$,$p1$Chapeau charnu, blanc crème; déterminant: lamelles serrées, blanches à TOUT âge, et sporée blanche; forte odeur et saveur farineuse-de concombre; la chair ne se colore PAS en rouge; champignon de printemps. L'odeur de farine + les lamelles blanches le distinguent de l'inocybe mortel.$p1$,$p1$Espèce comestible; DANGER DE MORT en cas de confusion avec Inocybe erubescens (syndrome muscarinien: forte hypersalivation/larmoiement/sudation, contraction des pupilles, vomissements, diarrhée, détresse respiratoire).$p1$,$p1$En cas de suspicion de confusion avec un inocybe (symptômes muscariniens), appeler IMMÉDIATEMENT Tox Info Suisse 145 / urgence 144 – atropine comme antidote.$p1$,$p1$Bien cuire à cœur; champignon comestible apprécié – uniquement en cas de détermination indubitable (lamelles blanches, odeur de farine, pas de rougissement).$p1$,$p1$Confusion/sosie: l'inocybe rougissant (Inocybe erubescens) – MORTELLEMENT toxique, forte teneur en muscarine; également printanier; la chair rougit, lamelles gris-brun, sporée brune. Également l'entolome livide toxique (Entoloma sinuatum).$p1$,true),
($p1$calvatia_gigantea$p1$,$p1$fr$p1$,$p1$Énorme boule blanche sans pied, 5-50 (jusqu'à 150) cm de diamètre, jusqu'à plus de 20 kg; jeune blanc neige avec une peau lisse, coriace, plus tard vert-jaune (alors immangeable). Sur les prairies, dans les parcs, en lisière de forêt. Ne consommer QUE si la chair interne est blanc neige et sans ébauches de lamelles - toujours couper en deux!$p1$,null,$p1$Toujours couper dans la longueur: en cas de structure interne lamellée/contour de chapeau (au lieu d'une chair blanche uniforme), jeter - confusion mortelle avec une jeune amanite phalloïde (Knollenblätterpilz).$p1$,$p1$Uniquement les jeunes exemplaires, blanc neige à l'intérieur; en tranches panées et poêlées (façon escalope). En cas de chair interne virant au jaune, jeter.$p1$,$p1$Confusion/sosie: Amanita phalloides/virosa (jeunes amanites se présentant comme une boule blanche - mais reconnaissables à l'intérieur à l'ébauche de lamelles et au contour du chapeau).$p1$,true),
($p1$cantharellus_tubaeformis$p1$,$p1$fr$p1$,$p1$Petit champignon en forme d'entonnoir/de trompette, chapeau 1-7 (9) cm, brun-jaune à gris-olive, centre creusé/perforé; face inférieure portant des plis fourchus, décurrents, gris-jaune (pas de véritables lamelles); pied mince, creux, jaune. Aucune confusion dangereuse connue.$p1$,null,null,$p1$Très bon champignon de mélange et de séchage malgré sa chair mince; bien cuire à cœur. Idéal dans les plats de champignons, les soupes, séché.$p1$,null,true),
($p1$champignon-de-paris$p1$,$p1$fr$p1$,$p1$Fin anneau blanc sur le pied, lamelles roses chez les jeunes exemplaires, chapeau brun chez la forme cultivée$p1$,null,null,$p1$Cru en salade ou poêlé, chauffer brièvement afin de préserver le goût$p1$,$p1$Champignon comestible le plus acheté en Suisse, principalement issu de la culture$p1$,true),
($p1$chlorophyllum_brunneum$p1$,$p1$fr$p1$,$p1$Chapeau brun à grosses écailles; la chair et les lamelles se colorent en rouge safran/orange à la blessure (rougissant); déterminant: bulbe basal nettement marginé-renflé et bien démarqué; anneau simple (souvent coulissant); AUCune zébrure (chinure) sur le pied (différence avec la coulemelle comestible Macrolepiota procera). Pousse souvent sur/près du compost.$p1$,$p1$Intoxication gastro-intestinale: nausées, vomissements, diarrhée, crampes abdominales; intensité variable selon les individus; ne convient pas comme champignon comestible.$p1$,$p1$En cas de troubles après consommation, contacter Tox Info Suisse 145.$p1$,null,$p1$Confusion/sosie: la coulemelle (Macrolepiota procera) et les lépiotes safranées comestibles – la confusion entraîne une intoxication (la coulemelle a un pied chiné, pas de bulbe marginé).$p1$,true),
($p1$clitocybe_dealbata$p1$,$p1$fr$p1$,$p1$Petit champignon blanc, chapeau 2-5 cm, blanc craie à blanc crème, jeune convexe, puis plat à creusé. Lamelles blanchâtres-crème, serrées, légèrement décurrentes. Pousse en groupe sur les pelouses, prés, pâturages – souvent en ronds de sorcière, volontiers à côté du marasme des Oréades.$p1$,$p1$Syndrome muscarinien: 15-30 min après la consommation, forte hypersalivation/larmoiement/sudation, myosis, douleurs abdominales, nausées, diarrhée, vision trouble, difficultés respiratoires. Antidote: atropine.$p1$,$p1$Tox Info Suisse 145. Antidote atropine à la clinique.$p1$,$p1$Ne jamais consommer. La muscarine est thermostable.$p1$,$p1$Confusion/sosies : Marasme des Oréades (Marasmius oreades, comestible) et jeune agaric des prés – même habitat de prairie ; aussi avec le Clitocybe à pied rainuré (également vénéneux).$p1$,true),
($p1$clitocybe_nebularis$p1$,$p1$fr$p1$,$p1$Grand chapeau gris nébuleux, paraissant givré, à marge enroulée ; lamelles couleur crème, serrées, légèrement décurrentes ; pied robuste et pâle ; odeur douceâtre-rance frappante.$p1$,$p1$Fréquemment intolérance individuelle: troubles gastro-intestinaux (nausées, vomissements, diarrhée) même avec des champignons cuits; la nébularine n'est PAS éliminée par la cuisson.$p1$,null,$p1$La VAPKO Suisse alémanique considère aujourd'hui sa consommation comme préoccupante (valeur culinaire modifiée en 'non comestible') – la consommation est déconseillée ; si tant est, uniquement bien cuit et en petites quantités.$p1$,$p1$Confusion/sosies : Entolome livide (Entoloma sinuatum) – hautement vénéneux (lamelles jaunâtres, puis roses, espacées) ; en outre le Tricholome tigré (Tricholoma pardinum), vénéneux.$p1$,true),
($p1$clitocybe_rivulosa$p1$,$p1$fr$p1$,$p1$Petit champignon blanchâtre, chapeau 2-4 cm, jeune givré de blanc, souvent taché/givré de manière concentrique et rainurée (le givre se craquelant), rose chair translucide. Lamelles crème-rose pâle, serrées, légèrement décurrentes. Pousse en groupe sur les prés, pelouses, bords de chemins, souvent en rangées/ronds de sorcière.$p1$,$p1$Syndrome muscarinien: 15-30 min après la consommation, forte hypersalivation/larmoiement/sudation, myosis, douleurs abdominales, nausées, diarrhée, vision trouble. Antidote: atropine.$p1$,$p1$Tox Info Suisse 145. Antidote atropine à la clinique.$p1$,$p1$Ne jamais consommer. La muscarine est même libérée de son précurseur lors de la cuisson – chauffer ne détoxifie PAS.$p1$,$p1$Confusion/sosies : Marasme des Oréades (Marasmius oreades) et agaric des prés (même habitat) ; aussi avec le Clitocybe des champs (également vénéneux).$p1$,true),
($p1$cortinarius_orellanus$p1$,$p1$fr$p1$,$p1$Chapeau orange-brun, lamelles orange, pied FIBREUX-orange, TARDIF sept.-nov.$p1$,$p1$TARDIF : insuffisance rénale 3-14 jours plus tard$p1$,$p1$Appeler immédiatement Tox Info Suisse 145 / urgences 144. Hôpital, préparation à la dialyse (insuffisance rénale).$p1$,$p1$NE JAMAIS MANGER, souvent confondu avec la chanterelle$p1$,$p1$Sournois, l'intoxication ne survient que 1-2 semaines après la consommation$p1$,true),
($p1$cortinarius_rubellus$p1$,$p1$fr$p1$,$p1$Chapeau 3-8 cm, brun jaune à brun orangé/rouille, conique avec un mamelon pointu, sec et finement feutré. Lamelles brun cannelle à brun rouille, espacées. Cortina (voile). Dans les forêts de conifères acides et riches en humus, surtout l'épicéa. Odeur de radis.$p1$,$p1$Syndrome orellanien : latence très longue, de 2 jours à 3 semaines. D'abord soif, nausées, douleurs à la tête/aux membres/aux reins, puis insuffisance rénale grave, souvent irréversible. ~50% restent dépendants de la dialyse.$p1$,$p1$Appeler immédiatement Tox Info Suisse, numéro d'urgence 145. En raison de la latence extrêmement longue, se rendre immédiatement à l'hôpital même en cas de suspicion tardive – surveiller la fonction rénale, dialyse si nécessaire.$p1$,$p1$Ne jamais consommer. L'orellanine est thermostable et résistante au séchage.$p1$,$p1$Confusion/sosies : Cortinaire des montagnes (Cortinarius orellanus, également mortel) ; jeune, confusion possible avec le Cortinaire ridé (Cortinarius caperatus) et la chanterelle.$p1$,true),
($p1$eierschwamm$p1$,$p1$fr$p1$,$p1$Plis au lieu de lamelles, entièrement jaune d'œuf, odeur d'abricot$p1$,$p1$—$p1$,$p1$—$p1$,$p1$À faire revenir frais, ne pas laver$p1$,$p1$Un classique gustatif$p1$,true),
($p1$entoloma_sinuatum$p1$,$p1$fr$p1$,$p1$Grand champignon charnu, chapeau 6-20 cm, jeune blanchâtre-gris à jaune argile/ivoire, lisse, ondulé avec l'âge. Caractère le plus important : lamelles jeunes blanchâtres/jaunâtres, puis ROSE CHAIR sous l'effet des spores (entolome). Odeur de farine/rance. Pied blanc robuste sans anneau.$p1$,$p1$Syndrome gastro-intestinal grave : env. 0,5-4 h après l'ingestion, troubles gastro-intestinaux violents et coliques, vomissements, diarrhée, perte d'électrolytes, problèmes circulatoires. Potentiellement mortel pour les enfants, les personnes âgées et affaiblies.$p1$,$p1$Tox Info Suisse 145. Réhydratation agressive / rééquilibrage électrolytique ; hospitalisation pour les personnes à risque.$p1$,$p1$Ne jamais consommer. Les toxines résistent à la cuisson ; l'un des déclencheurs les plus fréquents d'intoxications gastro-intestinales graves en Europe.$p1$,$p1$Confusion/sosies : Tricholome de la Saint-Georges (Calocybe gambosa, comestible – lamelles blanches denses, plus tôt dans l'année), Meunier (Clitopilus prunulus), jeunes agarics, Entolome écusson.$p1$,true),
($p1$flaemmling$p1$,$p1$fr$p1$,$p1$Chapeau de petite taille, fibreux-finement floconneux, lignicole (pousse sur le bois)$p1$,$p1$aucune toxine$p1$,$p1$pas nécessaire$p1$,$p1$Uniquement jeune et frais, cuisson recommandée$p1$,$p1$Tendre, mais courte conservation$p1$,true),
($p1$fliegenpilz-grosspilz$p1$,$p1$fr$p1$,$p1$Chapeau plissé en forme de cerveau, creux, ressemble à la morille$p1$,$p1$Maux de tête, nausées, diarrhée, vertiges, crampes$p1$,$p1$Numéro d'urgence toxicologique 145, ménagement gastrique$p1$,$p1$Non comestible$p1$,$p1$Souvent confondu avec la morille comestible$p1$,true),
($p1$fliegenpilz-roetlich$p1$,$p1$fr$p1$,$p1$Brun avec des flocons blancs, anneau et bulbe$p1$,$p1$Maux de tête, vertiges, confusion$p1$,$p1$Numéro d'urgence toxicologique 145, traitement$p1$,$p1$Non comestible$p1$,$p1$Plus rare que l'amanite tue-mouches$p1$,true),
($p1$fliegenpilz_var_alba$p1$,$p1$fr$p1$,$p1$Chapeau blanc avec des flocons blancs, anneau et volve blancs, peut être confondu avec des champignons comestibles$p1$,$p1$Ivresse, crampes musculaires, confusion, hallucinations$p1$,$p1$Numéro d'urgence toxicologique 145, envisager un lavage gastrique$p1$,$p1$Non comestible$p1$,$p1$Forme variante de l'amanite tue-mouches, vénéneuse comme la forme rouge$p1$,true),
($p1$flockenstieliger-hexen-roehrling$p1$,$p1$fr$p1$,$p1$Pores rouges, bleuissant à la pression, petits flocons rouges sur le pied, chair jaune qui vire au rouge$p1$,$p1$Nausées, vomissements, crampes d'estomac en cas de cuisson insuffisante$p1$,$p1$Consultation médicale en cas de symptômes d'intoxication$p1$,$p1$Cuire/bouillir à cœur au moins 20 minutes, ne pas consommer cru, préparer soigneusement$p1$,$p1$Comestible uniquement après préparation soignée; souvent confondu avec le bolet Satan toxique$p1$,true),
($p1$flockenstieliger_hexenpilz$p1$,$p1$fr$p1$,$p1$Mouchetures RUGUEUSES sur le pied, tubes rouges, bleuit RAPIDEMENT à la pression$p1$,$p1$cuit aucun problème, cru légers troubles$p1$,null,$p1$DOIT être cuit 15 min et plus; cru: légère intoxication$p1$,$p1$Malgré son aspect effrayant, très apprécié$p1$,true),
($p1$fomitopsis_betulina$p1$,$p1$fr$p1$,$p1$Polypore annuel, en forme de console/sabot, 5-20 cm, exclusivement sur les bouleaux; face supérieure lisse, gris à brun clair avec une marge saillante et incurvée, face inférieure à fins pores blancs. Chair blanche jeune, molle-liégeuse, devenant ensuite de plus en plus amère. Champignon vital/médicinal connu (champignon d'Ötzi).$p1$,null,null,$p1$Pas un champignon comestible (coriace, amer). Traditionnellement comme champignon médicinal/vital: jeunes carpophores blancs séchés en tisane/extrait. Pas comme plat.$p1$,null,true),
($p1$galerina_marginata$p1$,$p1$fr$p1$,$p1$Petit chapeau 1-7 cm, brun-jaune à couleur miel/brun foncé, souvent à centre plus sombre, hygrophane. Lamelles pâles jeunes, puis brun rouille, adnées. Anneau fin et fugace sur le pied (disparaît souvent rapidement). En touffes ou isolé sur bois mort de conifères (aussi de feuillus), sur souches pourries.$p1$,$p1$Syndrome phalloïdien: latence de 6-24 h, puis vomissements violents, diarrhée, douleurs abdominales, rémission apparente, ensuite insuffisance hépatique et rénale. 100-150 g peuvent être mortels.$p1$,$p1$Immédiatement Tox Info Suisse, numéro d'urgence 145 (ou 144). Conserver les restes de champignons. Clinique avec suspicion d'intoxication aux amatoxines. Thérapie à la silibinine. Chaque heure compte.$p1$,$p1$Ne jamais consommer. Les amatoxines sont thermostables, NON destructibles par la cuisson ou le séchage.$p1$,$p1$Confusion/sosie: la pholiote changeante (Kuehneromyces mutabilis) – comestible, mais la confusion la plus dangereuse; Galerina n'a pas de pied squameux sous l'anneau.$p1$,true),
($p1$gemeiner-fliegenpilz-var-alba$p1$,$p1$fr$p1$,$p1$Chapeau blanc à gris-brun sans flocons, voile blanc sous l'anneau, bulbe à la base du pied avec volve$p1$,$p1$Début retardé après 6-24 h, violents troubles gastriques, insuffisance hépatique, mortel$p1$,$p1$Appeler immédiatement les urgences médicales, traitement d'urgence nécessaire$p1$,$p1$Non comestible$p1$,$p1$L'une des espèces de champignons les plus mortelles d'Europe; risque de confusion avec le champignon de Paris blanc$p1$,true),
($p1$hallimasch$p1$,$p1$fr$p1$,$p1$ANNEAU sur le pied, jaune miel, parasite sur les racines d'arbres, en touffes$p1$,$p1$cru: troubles gastro-intestinaux$p1$,$p1$en cas de malaise, hôpital$p1$,$p1$DOIT être CUIT 15 min et plus, jamais cru$p1$,$p1$Apparition en masse. JAMAIS cru, très bon bien cuit$p1$,true),
($p1$herbsttrompete$p1$,$p1$fr$p1$,$p1$Trompette creuse gris foncé à noir$p1$,null,null,$p1$sécher comme épice d'hiver$p1$,$p1$Trésor gastronomique suisse$p1$,true),
($p1$hygrophoropsis_aurantiaca$p1$,$p1$fr$p1$,$p1$Orange (jaune) vif, chapeau 2-12 (15) cm, finement feutré, marge longtemps enroulée; face inférieure avec de véritables LAMELLES fines, fortement fourchues, décurrentes, jaune orangé, qui se détachent facilement (la vraie girolle a des plis obtus, solidement soudés). Chair mince, molle, douce/un peu moisie.$p1$,$p1$Troubles gastro-intestinaux avec douleurs abdominales, diarrhée, nausées, vomissements en cas de grandes quantités ou chez les personnes sensibles.$p1$,$p1$En cas de troubles, boire abondamment, contacter Tox Info Suisse 145; conserver les restes de champignons.$p1$,$p1$Non recommandé à la consommation; faiblement toxique, en grandes quantités toxique pour l'estomac et les intestins. Par précaution: éviter.$p1$,$p1$Confusion/sosie: la vraie girolle (Cantharellus cibarius) - la fausse est la plus toxique; attention en plus au clitocybe de l'olivier (Omphalotus) en cas de trouvailles d'un orange-rouge vif.$p1$,true),
($p1$hypholoma_fasciculare$p1$,$p1$fr$p1$,$p1$Chapeau 2-6 cm, jaune soufre à jaune verdâtre, centre souvent brun orangé/rougeâtre. Caractéristique: lamelles jeunes jaune soufre, puis verdâtres, finalement olive-noirâtres. Pied jaune, sans véritable anneau (tout au plus une zone cortinée fugace). En touffes sur souches/bois mort. Chair très amère.$p1$,$p1$Syndrome gastro-intestinal : vomissements, diarrhée, accès de sueur, dans les cas graves troubles de la vue et élévation des valeurs hépatiques. Le goût fortement amer met en garde.$p1$,$p1$Tox Info Suisse 145. Le plus souvent symptomatique ; dans les évolutions graves, contrôler les valeurs hépatiques.$p1$,$p1$Ne pas consommer. Les substances amères et les toxines sont stables à la cuisson.$p1$,$p1$Confusion/sosie: la pholiote changeante (Kuehneromyces mutabilis, comestible, pied squameux/anneau) et l'hypholome comestible à lames enfumées (lamelles grises, doux).$p1$,true),
($p1$infundibulicybe_geotropa$p1$,$p1$fr$p1$,$p1$Grand chapeau en forme d'entonnoir avec un mamelon central caractéristique; couleur fauve cuir pâle, jeune finement feutré; lamelles blanches décurrentes et serrées; pied coriace et ferme. N'utiliser que les jeunes chapeaux, les plus âgés sont coriaces. Cru légèrement toxique – seulement cuit.$p1$,$p1$L'espèce elle-même n'est pas toxique (légèrement irritante pour l'estomac à l'état cru) ; danger uniquement par confusion avec les clitocybes blancs toxiques (syndrome muscarinien).$p1$,null,$p1$Seulement les jeunes chapeaux, retirer les pieds (coriaces); bien cuire à cœur; apprécié dans les soupes et les plats mélangés.$p1$,$p1$Confusion/sosie: le clitocybe du cyprès (Clitocybe phyllophila) et les clitocybes blancs toxiques – muscariniens, toxiques (plus petits, à chair plus mince, sans mamelon).$p1$,true),
($p1$inocybe_erubescens$p1$,$p1$fr$p1$,$p1$Chapeau 3-9 cm, jeune blanchâtre-crème, à fibres radiales/craquelé, virant au rouge brique à rouge vineux avec l'âge et à la blessure. Lamelles pâles jeunes, puis brun olive/argileux, rougissant souvent. Apparaît au printemps/début d'été (en même temps que le mousseron de la Saint-Georges). Odeur spermatique.$p1$,$p1$Syndrome muscarinien (PSL) : 15-30 min après la consommation, transpiration importante, salivation/larmoiement, myosis, douleurs abdominales, vomissements, diarrhée, chute de la tension artérielle, bradycardie. 40-50 g frais peuvent être mortels. Antidote : atropine.$p1$,$p1$Immédiatement Tox Info Suisse 145 / numéro d'urgence 144. Antidote atropine en clinique ; surveiller la circulation.$p1$,$p1$Ne jamais consommer. La muscarine est thermostable.$p1$,$p1$Confusion/sosie: le mousseron de la Saint-Georges (Calocybe gambosa, comestible) – même saison printanière; aussi confondable avec le meunier et les jeunes champignons de Paris.$p1$,true),
($p1$kuehneromyces_mutabilis$p1$,$p1$fr$p1$,$p1$En touffes sur souches de feuillus ; chapeau hygrophane brun miel qui se décolore depuis le bord en deux ou plusieurs teintes ; zone annulaire nette sur le pied, EN DESSOUS de la zone annulaire brunâtre-écailleux (pas de fibrilles argentées) ; odeur agréablement fongique. Récolter UNIQUEMENT avec le pied complet – seule distinction sûre d'avec la galère marginée (Gifthäubling).$p1$,$p1$Espèce elle-même comestible ; DANGER DE MORT uniquement par confusion avec Galerina marginata (syndrome phalloïdien/amatoxines : 6-24 h sans symptômes, puis défaillance hépatique/rénale).$p1$,$p1$En cas de suspicion de confusion avec Galerina, IMMÉDIATEMENT Tox Info Suisse 145 (urgence 144) – amatoxines, tout retard met la vie en danger ; agir même en cas de bien-être après la période de latence.$p1$,$p1$Bien cuire à cœur ; n'utiliser que les chapeaux (pieds coriaces) ; les débutants devraient y renoncer en raison du risque de confusion mortelle.$p1$,$p1$Confusion/sosie : la galère marginée (Galerina marginata) – MORTELLE, amatoxines comme l'amanite phalloïde ; pousse mêlée sur le même substrat.$p1$,true),
($p1$lactarius_deliciosus$p1$,$p1$fr$p1$,$p1$LAIT ORANGE à la cassure, pas de changement de couleur$p1$,null,null,$p1$à poêler, à mariner, garniture de pizza$p1$,$p1$Classique italien ; le lait orange est sa marque de fabrique$p1$,true),
($p1$lactarius_deterrimus$p1$,$p1$fr$p1$,$p1$Chapeau 4-9 (12) cm, orange/rougeâtre-orangé chair, faiblement zoné, nettement TACHÉ DE VERT, visqueux à l'humidité, déprimé au centre. CLÉ : lait d'abord ROUGE CAROTTE/ORANGE, virant en 15-20 min au ROUGE VIN/rouge foncé. Pied orange, SANS scrobicules (différence avec le lactaire délicieux / Edelreizker !). Chair orange, verdissant souvent. Saveur douce à légèrement amère. Strictement lié à l'épicéa.$p1$,null,null,$p1$Comestible, mais moins estimé que le lactaire délicieux (Edelreizker) (souvent légèrement amer, fréquemment véreux). Poêler/griller ; pas cru. Préférer les jeunes exemplaires fermes.$p1$,$p1$Confusion/sosie : aucune confusion mortelle. Confusable avec le lactaire délicieux (Edelreizker) et le lactaire saumoné (Lachsreizker) (tous comestibles). IMPORTANT : seuls les lactaires de ce groupe (reizker) au lait ROUGE ORANGÉ sont comestibles ; éviter les lactaires au lait blanc ou virant au jaune soufre (p. ex. le lactaire scrobiculé, L. scrobiculatus).$p1$,true),
($p1$lactarius_piperatus$p1$,$p1$fr$p1$,$p1$Grand, 6-16 cm, blanc à crème, jeune taché de jaune crème, chapeau en entonnoir, surface LISSE/glabre (non feutrée – différence avec L. vellereus), non zoné. CLÉ : lames très SERRÉES et étroites, souvent fourchues, décurrentes ; lait blanc abondant, BRÛLANT/POIVRÉ ÂCRE, séchant en olive/verdâtre. Chair blanche, dure. Pied relativement long, blanc.$p1$,$p1$En cas de consommation fraîche/crue, irritation gastro-intestinale possible due à l'âcreté (nausées, vomissements, diarrhée) ; avant tout immangeable en raison de son âcreté brûlante.$p1$,$p1$En cas de troubles gastro-intestinaux, Tox Info Suisse 145, compenser les pertes liquidiennes.$p1$,$p1$Immangeable – à peine comestible en raison de l'âcreté extrême et persistante ; fortement irritant cru/frais. Non recommandé.$p1$,$p1$Confusion/sosie : aucune confusion mortelle ; très semblable au lactaire velouté (chapeau feutré, lames ESPACÉES), au Lactifluus glaucescens (lactaire poivré verdissant) et aux russules blanches – tous âcres/immangeables. Distinction par les lames serrées + le chapeau lisse.$p1$,true),
($p1$lactarius_vellereus$p1$,$p1$fr$p1$,$p1$Grand, 8-20 (25) cm, blanc craie, chapeau en entonnoir/déprimé en cuvette, surface finement FEUTRÉE-LAINEUSE (veloutée), non zoné, taché d'ocre avec l'âge. CLÉ : lames très ESPACÉES, épaisses ; lait blanc émis seulement parcimonieusement, de saveur BRÛLANTE ÂCRE, séchant en gris-verdâtre. Chair dure, blanche. Soulève souvent terre/feuilles en poussant (pousse-terre).$p1$,$p1$En cas de consommation crue/fraîche, irritation gastro-intestinale jusqu'à intoxication modérée due aux terpènes (nausées, vomissements violents, crampes ; début 30-60 min) ; en grandes quantités, troubles de la vue et de la coordination. Avant tout immangeable (âcreté, dureté).$p1$,$p1$En cas de troubles gastro-intestinaux, Tox Info Suisse 145, compenser les pertes liquidiennes.$p1$,$p1$Immangeable (brûlant âcre, dur) – consommé cru/frais, intoxications gastro-intestinales possibles dues aux terpènes. Non recommandé en cuisine.$p1$,$p1$Confusion/sosie : aucune confusion mortelle ; semblable au lactaire poivré (L. piperatus, chapeau lisse, lames serrées) et aux russules blanches (Russula delica). Distinction : vellereus a des lames ESPACÉES + un chapeau feutré.$p1$,true),
($p1$lactarius_volemus$p1$,$p1$fr$p1$,$p1$Chapeau 5-12 cm, brun orangé/brun cannelle à brun-jaune fauve, jeune velouté, déprimé au centre, sec. CLÉ : émet du lait blanc TRÈS ABONDAMMENT, DOUX (non âcre !), brunissant rapidement les doigts/les lames ; odeur caractéristique de poisson/de hareng (disparaît à la cuisson vive). Lames crème, serrées, brunissantes. Chair ferme, blanche.$p1$,null,null,$p1$Excellent champignon à poêler/griller (son nom !) ; les jeunes sont réputés consommables crus (mais en raison du risque d'échinocoque/Echinococcus en Suisse, la consommation crue n'est tout de même PAS recommandée). L'odeur de poisson s'évapore à la cuisson vive. NE PAS bouillir/étuver – devient gluant.$p1$,$p1$Confusion/sosie : aucune confusion dangereuse ; semblable seulement au Lactifluus rugatus (lactaire ridé, immangeable). Les autres lactaires à lait blanc sont le plus souvent âcres (goûter un échantillon).$p1$,true),
($p1$laetiporus_sulphureus$p1$,$p1$fr$p1$,$p1$Carpophores en consoles/imbriqués en éventail, jaune soufre à jaune orangé, console isolée jusqu'à plus de 30 cm ; jeune mou-juteux, vieux coriace et pâle. Face inférieure à fins pores jaunes (pas de lames). Pousse en touffes sur troncs de feuillus. UNIQUEMENT jeune, bien cuit à cœur.$p1$,$p1$Troubles gastro-intestinaux (diarrhée, vomissements) en cas de consommation crue/insuffisamment cuite; en cas de récolte sur du bois toxique (surtout l'if), en plus vertiges/somnolence, intoxication potentiellement plus grave.$p1$,$p1$En cas de troubles, Tox Info Suisse 145; ne jamais consommer cru, ne pas utiliser de substrat if/robinier/chêne.$p1$,$p1$Seulement les bords jeunes et juteux ; JAMAIS cru – toujours bien cuire à cœur (blanchiment recommandé), pané comme une escalope. Préférer les récoltes sur arbres fruitiers/saule. IMPORTANT : ÉVITER les exemplaires poussant sur l'IF (taxine !), le robinier ainsi que le chêne/le hêtre – le poison du substrat peut passer dans le champignon.$p1$,null,true),
($p1$leccinum_aurantiacum$p1$,$p1$fr$p1$,$p1$Chapeau orange doré à rouge orangé à brun orangé, cuticule un peu débordante ; pied blanchâtre avec des écailles majoritairement rougeâtres-brunâtres (non noires) ; chair blanche, rougissant/rouge vin à la coupe, puis gris-noir. Sous tremble/peuplier (aussi chêne).$p1$,$p1$Cru ou insuffisamment cuit: troubles gastro-intestinaux; rarement aussi une intolérance après cuisson$p1$,null,$p1$Excellent champignon comestible à chair ferme. INTOLÉRABLE/TOXIQUE CRU – cuire bien à cœur au moins 15-20 min. La chair fonce à la cuisson. Seulement en petites quantités, car même cuit une intolérance gastro-intestinale a été signalée isolément.$p1$,null,true),
($p1$leccinum_pseudoscabrum$p1$,$p1$fr$p1$,$p1$Chapeau brun jaune à gris- ou brun-noir, caractéristiquement ridé-creusé/martelé ; pied robuste avec des écailles brun foncé ; tubes blanc crème, gris olive avec l'âge ; chair blanche, à la coupe d'abord gris-violet/rose, puis noire. Presque exclusivement sous charme (aussi noisetier). Syn. Leccinellum pseudoscabrum.$p1$,$p1$Cru ou insuffisamment cuit: troubles gastro-intestinaux$p1$,null,$p1$Bon champignon comestible, jeune. Comme tous les bolets rugueux, bien cuire à cœur ; la valeur culinaire décline rapidement avec l'âge, donc récolter jeune. La chair fonce à la cuisson.$p1$,null,true),
($p1$leccinum_versipelle$p1$,$p1$fr$p1$,$p1$Chapeau jaune orangé vif à rouge brique, finement feutré, cuticule débordante au bord ; pied blanchâtre avec des écailles brun-noir (non rouges) ; tubes gris ; chair à la coupe d'abord gris-violet, puis noire, base du pied bleu-verdâtre. Uniquement sous bouleau.$p1$,$p1$Cru ou insuffisamment cuit: troubles gastro-intestinaux$p1$,null,$p1$Très bon champignon comestible, jeune. TOXIQUE CRU – cuire bien à cœur au moins 15-20 min. La chair devient noire à la cuisson (sans diminuer la valeur culinaire). Retirer les vieux tubes spongieux.$p1$,null,true),
($p1$lepista_nuda$p1$,$p1$fr$p1$,$p1$Chapeau charnu coloré en bleu-violet quand jeune, se décolorant ensuite en brun depuis le centre ; lames et pied violets, serrés ; odeur agréable parfumée ; sporée rose pâle (non brun rouille) – distinction importante d'avec les cortinaires.$p1$,$p1$Toxique cru (troubles gastro-intestinaux, hémolysines); doit être chauffé soigneusement (>=15 min).$p1$,null,$p1$Jamais cru ; bien cuire à cœur au moins 15 minutes ; convient aussi pour la conservation au vinaigre.$p1$,$p1$Confusion/sosie : les cortinaires violets (Cortinarius spp.) – sporée brun rouille, cortine arachnéenne ; certains Cortinarius (p. ex. le cortinaire couleur de rocou, Orangefuchsiger Raukopf) sont mortels.$p1$,true),
($p1$lycoperdon_perlatum$p1$,$p1$fr$p1$,$p1$En forme de bouteille/poire avec une partie pédonculée nette, 3-10 cm de haut ; surface couverte d'aiguillons/verrues grossiers et facilement caducs, qui laissent un motif réticulé. Blanc chez les jeunes, puis brun jaune-gris. Ne consommer que tant que la chair intérieure est d'un blanc pur ; toujours couper en deux.$p1$,null,$p1$Couper LONGITUDINALEMENT tout champignon globuleux/blanc: (1) en présence d'une ébauche de lamelles/d'un contour de chapeau à l'intérieur, jeter (amanite mortelle Amanita); (2) en présence d'une chair ferme marbrée de violet-noir, jeter (scléroderme toxique Scleroderma). Ne consommer que la gléba uniformément blanc pur.$p1$,$p1$Uniquement jeune avec une chair intérieure d'un blanc pur ; comme champignon de mélange. Devient facilement coriace à la cuisson ; souvent seulement en garniture.$p1$,$p1$Confusion/sosies : jeunes Amanita phalloides/virosa (stade sphérique - insertion de lamelles à l'intérieur) ; scléroderme (Scleroderma, chair violet-noir).$p1$,true),
($p1$marasmius_oreades$p1$,$p1$fr$p1$,$p1$Petit chapeau coriace ocre clair à brun cuir, souvent aplati avec un mamelon ; lamelles blanc-crème et remarquablement espacées ; pied coriace-élastique, qui se laisse tordre sans se rompre ; odeur épicée caractéristique (amande amère/clou de girofle) ; les fructifications desséchées reprennent vie après humidification.$p1$,$p1$Cru en grandes quantités, intolérable en raison de faibles traces d'acide cyanhydrique; rendu inoffensif par la cuisson.$p1$,null,$p1$Bien cuire à cœur ; retirer uniquement les pieds coriaces ou les couper finement ; excellent champignon condimentaire et à faire sécher.$p1$,$p1$Confusion/sosies : le clitocybe blanc (Clitocybe rivulosa/dealbata) – contenant de la muscarine, toxique ; sur le même habitat de prairie (blanc, lamelles serrées).$p1$,true),
($p1$marone$p1$,$p1$fr$p1$,$p1$Les tubes bleuissent à la pression, chapeau brun châtaigne$p1$,null,null,$p1$à faire revenir frais, à faire sécher$p1$,$p1$Alternative fréquente au cèpe$p1$,true),
($p1$maronenroehrling$p1$,$p1$fr$p1$,$p1$Coloration du chapeau brun châtaigne, pores jaunes, petits flocons à la base du pied, bleuit à la pression$p1$,null,null,$p1$Retirer la surface du chapeau, entier ou en morceaux, à poêler ou à cuire$p1$,$p1$Champignon comestible apprécié et fréquent, moins prisé que le cèpe mais fiable$p1$,true),
($p1$morchelchampignon$p1$,$p1$fr$p1$,$p1$surface du chapeau alvéolée, pied haut, forme caractéristique$p1$,$p1$aucune toxine$p1$,$p1$pas nécessaire$p1$,$p1$à n'utiliser que cuit ou poêlé$p1$,$p1$Mets délicat, printanier, toxique cru$p1$,true),
($p1$morchella_elata$p1$,$p1$fr$p1$,$p1$Chapeau conique-pointu, 4-15 cm de haut, avec des alvéoles nettement creusées en nid d'abeille, côtes sombres orientées longitudinalement, brun olive/gris à noirâtre ; pied blanchâtre, chapeau ET pied entièrement creux et soudés de façon lisse à la base du chapeau (différence avec la gyromitre). TOXIQUE CRU - uniquement bien cuit/séché.$p1$,$p1$En cas de consommation crue/insuffisamment cuite : troubles gastro-intestinaux, syndrome de Morchella avec vertiges, troubles de l'équilibre/de la coordination, tremblements, état ébrieux.$p1$,$p1$En cas de symptômes neurologiques/de vomissements persistants, Tox Info Suisse 145 ; jamais cru, toujours bien cuire au moins 15 min. L'éventuelle confusion avec la gyromitre hautement toxique (Lorchel) doit impérativement être exclue.$p1$,$p1$JAMAIS cru ! Bien cuire à cœur au moins 15 min OU faire sécher plusieurs mois ; jeter l'eau de cuisson. Cru/insuffisamment cuit : intoxication gastro-intestinale ou syndrome de Morchella. Même cuit, ne pas combiner avec de l'alcool.$p1$,$p1$Confusion/sosies : la gyromitre de printemps (Gyromitra esculenta) - circonvoluée comme un cerveau au lieu d'alvéolée, pied cloisonné (et non creux), hautement toxique/potentiellement mortelle (gyromitrine/MMH).$p1$,true),
($p1$parasol$p1$,$p1$fr$p1$,$p1$Anneau MOBILE sur le pied, lamelles blanches, surface du chapeau écailleuse$p1$,null,null,$p1$à faire revenir pané comme une escalope$p1$,$p1$Connu sous le nom d'escalope de champignon$p1$,true),
($p1$paxillus_involutus$p1$,$p1$fr$p1$,$p1$Chapeau 5-15 cm, ocre à brun rouille/olive, marge enroulée chez les jeunes, feutrée et côtelée (d'où le nom). Lamelles décurrentes, jaunâtre-ocre, se détachant facilement du chapeau, se tachant de brun foncé à la pression. Tout le champignon se colore en brun en cas de lésion.$p1$,$p1$Aigu gastro-intestinal (vomissements, diarrhée, douleurs abdominales/dorsales). Dangereux : syndrome immuno-hémolytique de Paxillus après consommation répétée – des anticorps détruisent les érythrocytes (hémolyse), insuffisance rénale aiguë, choc ; rare, mais alors souvent grave et potentiellement MORTEL.$p1$,$p1$Tox Info Suisse 145. En cas de crise hémolytique, urgence : hôpital, surveillance des reins/de la formule sanguine, le cas échéant plasmaphérèse/dialyse.$p1$,$p1$Ne pas consommer. Toxique même cuit ; la sensibilisation immunitaire ne peut être évitée par la cuisson. Son ancien statut de champignon comestible est considéré comme dépassé.$p1$,$p1$Confusion/sosies : confusion avec d'autres champignons bruns à lamelles ; autrefois récolté à tort comme champignon comestible.$p1$,true),
($p1$roehrling_flockenstielig$p1$,$p1$fr$p1$,$p1$Tubes épais, pores rouges, petits flocons rouges sur la base jaunâtre du pied, ne bleuit pas$p1$,$p1$Nausées, vomissements, diarrhée, crampes d'estomac$p1$,$p1$Contacter le centre antipoison 145, traitement symptomatique$p1$,$p1$Non comestible$p1$,$p1$Souvent confondu avec le bolet à pied rouge (Hexen-Röhrling) comestible à pied floconneux$p1$,true),
($p1$roetling$p1$,$p1$fr$p1$,$p1$Anneau sur le pied, coloration rougeâtre$p1$,$p1$aucune toxine$p1$,$p1$pas nécessaire$p1$,$p1$à poêler, à braiser, en soupe$p1$,$p1$devenu rare, risque de confusion avec des espèces toxiques$p1$,true),
($p1$rotfuss_hexen_roehrling$p1$,$p1$fr$p1$,$p1$Spores rouges, pores rouges, coloration rouge caractéristique à la base du pied, face inférieure du chapeau rouge$p1$,$p1$Troubles gastro-intestinaux en cas de préparation crue$p1$,$p1$Centre antipoison uniquement en cas de consommation massive$p1$,$p1$À ne préparer qu'après un blanchiment soigneux, pas cru$p1$,$p1$Évalué de manière controversée, considéré comme champignon comestible dans certains pays, sûr uniquement après blanchiment$p1$,true),
($p1$rotkappe_birken$p1$,$p1$fr$p1$,$p1$Uniquement sous les bouleaux, pied à écailles foncées$p1$,null,null,$p1$à la poêle, en soupe$p1$,$p1$Accompagne obligatoirement le bouleau$p1$,true),
($p1$rubroboletus_satanas$p1$,$p1$fr$p1$,$p1$Chapeau d'un blanc-gris à gris crème remarquablement clair ; pores d'un ROUGE SANG/rouge carmin éclatant ; pied épais, bulbeux, jaune avec un réseau rouge ; chair blanc-jaunâtre, bleuissant seulement faiblement/de façon retardée ; vieux, odeur désagréable de charogne. Forêts feuillues chaudes sur calcaire (chêne/hêtre).$p1$,$p1$Violents symptômes gastro-intestinaux (nausées, vomissements répétés, douleurs abdominales spasmodiques, diarrhée), le plus souvent dans les 1 à 6 h après l'ingestion ; en grandes quantités, effets circulatoires, rarement engageant le pronostic vital. La bolésatine inhibe la synthèse des protéines et a une action hémagglutinante.$p1$,$p1$Appeler immédiatement Tox Info Suisse : 145 (24 h). Conserver les restes de champignons/les vomissures. En cas de vomissements/diarrhée, compenser les pertes liquidiennes, traitement médical ; pas d'automédication avec des substances provoquant le vomissement.$p1$,$p1$NE PAS CONSOMMER – toxique. Cru, fortement toxique ; même cuit, sa consommation n'est pas sûre. Ne jamais en faire un champignon comestible.$p1$,$p1$Confusion/sosies : le bolet blafard (Suillellus luridus) et le bolet à pied rouge (Neoboletus erythropus) – tous deux comestibles une fois cuits, mais la confusion est dangereuse ; le bolet Satan a un chapeau clair et ne bleuit que faiblement.$p1$,true),
($p1$russula_cyanoxantha$p1$,$p1$fr$p1$,$p1$Chapeau de 5 à 15 cm, vert-violet/lilas-vert à bleu-vert, souvent multicolore mêlé ; cuticule pelable jusqu'à la moitié. CARACTÈRE DÉTERMINANT : lamelles molles, souples, d'un éclat gras/lardacé qui NE se brisent PAS (au toucher comme du savon mou/du lard) – presque tous les autres russules ont des lamelles cassantes et fragiles. Chair blanche, douce, inaltérable ; sous la cuticule, violet-bleu. Pied blanc, ferme. Réaction au FeSO4 négative/très faible (différence avec les autres russules).$p1$,null,$p1$En cas de suspicion de confusion avec l'amanite phalloïde (nausées/diarrhée 6-24 h après le repas), appeler IMMÉDIATEMENT Tox Info Suisse 145 - le temps de latence engage le pronostic vital.$p1$,$p1$Jeunes exemplaires à la poêle, à l'étuvée ou dans des plats de champignons mélangés ; arôme doux et noisette. Les exemplaires plus âgés sont souvent véreux – à trier.$p1$,$p1$Confusion/sosies : l'amanite phalloïde (Amanita phalloides) – mortellement toxique : les exemplaires teintés de vert/violet peuvent être confondus avec elle lors d'une détermination purement visuelle. Distinction SÛRE UNIQUEMENT par l'absence d'anneau (manchette) et l'absence de bulbe/volve à la base du pied, ainsi que par les lamelles souples et élastiques de la russule charbonnière. Au sein du genre : exclure les russules âcres par dégustation.$p1$,true),
($p1$russula_emetica$p1$,$p1$fr$p1$,$p1$Chapeau de 4 à 10 cm, rouge vermillon éclatant à rouge sang/rouge cerise, se décolorant par taches ; cuticule brillante, gluante, se pelant facilement et largement. CLÉ : goût IMMÉDIATEMENT BRÛLANT ET ÂCRE (recracher la dégustation !). Chair blanche, rose sous la cuticule rouge, odeur fruitée et légèrement sucrée. Lamelles d'un blanc pur, pied blanc, cassant. Typique dans les sphaignes/mousses de tourbe des forêts de conifères humides.$p1$,$p1$Syndrome gastro-intestinal : nausées, vomissements violents, crampes gastro-intestinales, diarrhée ; début de 15 min à env. 2-4 h. Spontanément résolutif, rarement dangereux sauf en cas de perte liquidienne.$p1$,$p1$En cas de troubles, Tox Info Suisse 145 (24 h). Compenser les pertes de liquide/d'électrolytes ; conserver les restes de champignons.$p1$,$p1$Non consommable – toxique. Goût brûlant et âcre = non comestible/toxique.$p1$,$p1$Confusion/sosies : confusable avec des russules rouges comestibles (p. ex. la russule des marais, Russula paludosa) – séparation sûre UNIQUEMENT par la dégustation (âcre = toxique).$p1$,true),
($p1$russula_vesca$p1$,$p1$fr$p1$,$p1$Chapeau de 4 à 12 (15) cm, rouge chair à brun-vineux, brun noisette/cuir, gris-lilas, souvent se décolorant par taches ; mat, un peu visqueux seulement jeune. CARACTÈRE CLÉ : cuticule trop courte (raccourcie) qui se retire au bord et dégage les arêtes blanches des lamelles comme de petites dents. Chair blanche, douce, presque inodore. Pied blanc (jamais rougeâtre), souvent aminci vers la base, se tachant de brun-jaune avec l'âge. Réaction au FeSO4 nettement rose chair/orange-rosé (bon caractère de détermination).$p1$,null,null,$p1$Excellent champignon comestible, doux et de saveur de noisette ; à la poêle, à l'étuvée, pour plats mélangés. Considéré comme l'un des meilleurs russules.$p1$,$p1$Confusion/sosies : au sein du genre, confusion avec d'autres russules, en partie âcres ou non comestibles (dégustation : âcre = ne pas manger) ; la russule décolorée (Russula exalbicans) peut également présenter une cuticule raccourcie, mais a un goût un peu âcre. Pas de confusion directement mortelle, mais les débutants doivent savoir distinguer sûrement les russules des champignons à lamelles et à chapeau brun.$p1$,true),
($p1$russula_virescens$p1$,$p1$fr$p1$,$p1$Chapeau de 4 à 15 (20) cm, vert/vert herbe/vert-de-gris sur fond blanc-verdâtre pâle (JAMAIS violet) ; CARACTÈRE CLÉ : la cuticule se craquelle en aréoles/plaques comme une mosaïque/une peau de crapaud, souvent avec des fissures d'un jaune sale. Chair blanche, ferme, cassante, douce, agréablement de noisette. Lamelles blanc-crème, cassantes. Pied blanc, fragile, SANS anneau et SANS bulbe. Attention : jeune, le chapeau peut être presque blanc et la cuticule aréolée pas encore marquée.$p1$,null,$p1$En cas de suspicion de confusion avec l'amanite phalloïde (nausées/diarrhée retardées 6-24 h après le repas), appeler IMMÉDIATEMENT Tox Info Suisse 145 - le temps de latence engage le pronostic vital, une prise en charge précoce est déterminante.$p1$,$p1$Excellent champignon comestible, de saveur de noisette, l'un des rares russules consommables crus ; à la poêle, à l'étuvée. À ne récolter QUE si la détermination est absolument sûre – DÉCONSEILLÉ aux débutants.$p1$,$p1$Confusion/sosies : l'amanite phalloïde (Amanita phalloides) – MORTELLEMENT toxique. Les jeunes exemplaires en particulier sont faciles à confondre (coloration verte similaire, mêmes stations). Distinction SÛRE UNIQUEMENT en déterrant le champignon entier et en l'examinant : à la russule verdoyante MANQUENT la manchette du pied (anneau) ET le bulbe/la volve à la base du pied ; en outre, cuticule se craquelant en aréoles + lamelles cassantes.$p1$,true),
($p1$sarcodon_imbricatus$p1$,$p1$fr$p1$,$p1$Chapeau de 6 à 15 (30) cm, gris à brun clair avec de grosses écailles brun foncé dressées en tuiles ; face inférieure avec des aiguillons gris-brun, friables (pas de pores/lamelles). Champignon symbiotique des forêts de conifères (épicéa). Jeune, doux ; vieux, de plus en plus amer.$p1$,$p1$Cru/insuffisamment cuit ou chez les spécimens âgés/amers : troubles gastro-intestinaux (nausées, diarrhée)$p1$,null,$p1$Uniquement les jeunes exemplaires ; cru/insuffisamment chauffé, indigeste, donc bien cuire à cœur ou blanchir. Champignon condimentaire connu : sécher et moudre en poudre de champignon. Éviter les exemplaires âgés/amers.$p1$,null,true),
($p1$schopftintling$p1$,$p1$fr$p1$,$p1$À manger UNIQUEMENT JEUNE ; vieux, se liquéfie en une masse d'encre.$p1$,null,$p1$À valoriser immédiatement : 1 h entre la récolte et la préparation$p1$,$p1$À la poêle immédiatement, en soupe.$p1$,$p1$PRUDENCE avec l'alcool, coprine – pas d'alcool pendant 24h.$p1$,true),
($p1$semmelstoppelpilz$p1$,$p1$fr$p1$,$p1$Aiguillons au lieu de lamelles, ocre clair.$p1$,null,null,$p1$À la poêle frais, assaisonner.$p1$,$p1$Peu de risque de confusion pour les débutants.$p1$,true),
($p1$shiitake$p1$,$p1$fr$p1$,$p1$Importé/cultivé ; en Suisse, uniquement cultivé.$p1$,null,null,$p1$À la poêle, assaisonner, en soupe.$p1$,$p1$Classique asiatique, producteurs bio suisses.$p1$,true),
($p1$sparassis_crispa$p1$,$p1$fr$p1$,$p1$Carpophore en forme de chou-fleur/d'éponge de bain, formé de lobes crépus, ondulés, jaune pâle à ocre, large de 6 à 30 (50) cm, pesant 2 à 5 kg ; pousse à la base du tronc/sur les souches de conifères (surtout le pin). Chair blanc-jaune clair, odeur épicée et de noisette. Ne pas manger le trognon (intolérance).$p1$,null,null,$p1$Nettoyer soigneusement (les lobes crépus retiennent sable/aiguilles) ; blanchir brièvement ou faire revenir en tranches ; comme champignon à la crème, avec lard/œuf ou comme substitut de pâtes. Jeter le trognon.$p1$,null,true),
($p1$steinpilz$p1$,$p1$fr$p1$,$p1$Pied à réseau blanc, tubes verdâtres à maturité$p1$,null,null,$p1$à poêler frais, à sécher, à congeler$p1$,$p1$Un classique. Quantité de cueillette souvent limitée en Suisse.$p1$,true),
($p1$suillus_granulatus$p1$,$p1$fr$p1$,$p1$Chapeau brun jaunâtre à ocre, gras-visqueux, cuticule du chapeau pelable ; pied SANS anneau, pourvu au sommet de fines granulations glanduleuses (à l'origine du nom, souvent des gouttelettes laiteuses) ; pores jaune pâle, fins, ne bleuissant pas. Toujours sous le pin.$p1$,$p1$En grandes quantités, légèrement laxatif$p1$,null,$p1$Bon comestible ; peler la cuticule visqueuse du chapeau, bien cuire à cœur. De grandes quantités peuvent avoir un léger effet laxatif.$p1$,null,true),
($p1$suillus_grevillei$p1$,$p1$fr$p1$,$p1$Chapeau jaune doré vif à brun jaunâtre, fortement visqueux par temps humide, cuticule du chapeau facile à peler ; pied avec anneau membraneux ; pores jeunes d'un jaune vif, brunissant à la pression ; toujours sous le mélèze. Bolet visqueux (Schmierröhrling).$p1$,$p1$En grandes quantités, légèrement laxatif (typique des bolets visqueux / Schmierröhrlinge)$p1$,null,$p1$Bon comestible, surtout jeune. Peler la cuticule visqueuse du chapeau avant la cuisson ; bien cuire à cœur. De grandes quantités de bolets visqueux purs peuvent avoir un effet laxatif.$p1$,null,true),
($p1$suillus_variegatus$p1$,$p1$fr$p1$,$p1$Chapeau jaunâtre à brun jaune-olive, jeune finement feutré-granuleux-écailleux (un peu visqueux seulement par temps humide) ; tubes courts, brun-olive, bleuissant faiblement à la pression ; pied bleuissant faiblement à la coupe. Toujours sous le pin, sur sols sableux acides. Confusion possible avec le bolet des bouviers (Kuhröhrling), également comestible (pores plus grossiers, ne bleuissant guère).$p1$,$p1$En grandes quantités, légèrement laxatif$p1$,null,$p1$Bon comestible, abondant ; bien cuire à cœur. De grandes quantités de bolets visqueux purs peuvent avoir un effet laxatif.$p1$,null,true),
($p1$tylopilus_felleus$p1$,$p1$fr$p1$,$p1$Chapeau brun clair à brun olive, jeune ressemblant au cèpe ; pied avec un réseau GROSSIER, brun foncé (et non fin et blanc comme le cèpe) ; tubes/pores jeunes blancs, virant rapidement nettement au ROSE à rose chair ; chair blanche, EXTRÊMEMENT AMÈRE. Vire au rose brunâtre à la pression. Principal sosie du cèpe – les tubes roses, le réseau grossier et foncé et l'amertume le démasquent.$p1$,$p1$Légèrement toxique : en cas de consommation de grandes quantités, troubles gastro-intestinaux documentés (coliques abdominales, nausées, vomissements, diarrhée), en partie accompagnés de vertiges/sensation de chaleur. Problème principal : amertume extrême qui rend déjà les plus petites quantités immangeables.$p1$,$p1$En cas de troubles après consommation, appeler Tox Info Suisse 145 (24h) ; compenser les pertes liquidiennes.$p1$,$p1$NE PAS CONSOMMER – immangeable et faiblement toxique. Extrêmement amer ; un seul exemplaire gâche tout un plat. L'amertume ne disparaît pas à la cuisson. Un test gustatif (une minuscule quantité, à recracher) le démasque.$p1$,null,true),
($p1$verpa_bohemica$p1$,$p1$fr$p1$,$p1$Chapeau en forme de cloche / de dé à coudre de 2-4 (5) cm, ridé-côtelé longitudinalement (aspect cérébriforme/labyrinthique), beige clair à brun foncé, relié au pied UNIQUEMENT au sommet et retombant librement en cloche (différence avec la morille conique, dont le chapeau est entièrement soudé) ; pied blanchâtre, creux, ouaté et alvéolé. Contient de la gyromitrine/monométhylhydrazine – toxique cru.$p1$,$p1$Troubles gastro-intestinaux, symptômes neurologiques (vertiges, perte de coordination, troubles de l'élocution); en présence de Gyromitrin/MMH, atteinte hépatique potentielle comme avec le gyromitre (Lorchel).$p1$,$p1$Ne pas consommer. En cas d'ingestion accidentelle / de symptômes, contacter immédiatement Tox Info Suisse 145, conserver un reste du champignon.$p1$,$p1$NE PAS recommander à la consommation. Contient de la gyromitrine (toxine de type hydrazine comme le poison de la gyromitre). Toxique cru comme toutes les morilles ; même préparé, classé par beaucoup comme toxique/incertain. Par prudence : à éviter.$p1$,$p1$Confusion/sosies : gyromitre / fausse morille (Gyromitra esculenta, très toxique) ; morille conique comestible (soudée uniquement au sommet du chapeau, contre entièrement soudée).$p1$,true),
($p1$xerocomus_subtomentosus$p1$,$p1$fr$p1$,$p1$Chapeau brun olive à brun jaunâtre, velouté-feutré (à sec) ; pores jaune citron vif, bleuissant à peine jeunes, un peu plus vieux ; pied clair, jaunâtre pâle, souvent avec de fines côtes longitudinales, sans réseau ; chair blanchâtre-jaune, bleuissant à peine, douce. Bolet subtomenteux (Filzröhrling).$p1$,null,null,$p1$Comestible, de bonne qualité jeune ; plus vieux, la chair devient molle et de moindre qualité. Bien cuire à cœur. Éviter les exemplaires atteints par la moisissure dorée (Hypomyces).$p1$,null,true),
($p1$zigeunerpilz$p1$,$p1$fr$p1$,$p1$Jeune chapeau avec un voile pruineux blanc (REIF), anneau sur le pied$p1$,null,null,$p1$à poêler, en soupe$p1$,$p1$Un classique des régions de montagne suisses$p1$,true),
($p1$agaricus_augustus$p1$,$p1$it$p1$,$p1$Cappello grande, dapprima sferico, con squame giallo-marroni su fondo chiaro; netto odore di anice/mandorla amara; carne al taglio debolmente ingiallente; anello membranoso; lamelle libere, da giovani chiare, da vecchie marrone cioccolato. AVVERTENZA: accumula spesso cadmio, quindi solo occasionalmente e con moderazione.$p1$,$p1$Specie commestibile; in caso di confusione con l'agarico giallo (Agaricus xanthodermus, prataiolo carbolico) disturbi gastrointestinali. Rischio proprio: accumulo di metalli pesanti (cadmio). Mortale in caso di confusione con l'amanita (Knollenblätterpilz / Amanita).$p1$,null,$p1$Cuocere bene a fondo; apprezzato per l'odore di anice; a causa del cadmio solo con moderazione.$p1$,$p1$Confusione/sosia: agarico fenolico/carbolico (A. xanthodermus) e agarico di Moeller (A. moelleri) – velenosi (odore di carbolo, base del gambo giallo cromo); da giovane confusione con l'amanita falloide bianca/verde (controllare volva/sporata bianca) – mortale.$p1$,true),
($p1$agaricus_campestris$p1$,$p1$it$p1$,$p1$Habitat di PRATO, cappello bianco, lamelle rosa che diventano marroni$p1$,$p1$—$p1$,$p1$—$p1$,$p1$come gli champignon coltivati$p1$,$p1$ATTENZIONE alla confusione con l'agarico fenolico (carbolico), velenoso$p1$,true),
($p1$agaricus_xanthodermus$p1$,$p1$it$p1$,$p1$Cappello 5-14 cm, bianco fino a biancastro, centro spesso brunastro. Carne bianca, alla base del gambo sotto pressione/al taglio vira intensamente al GIALLO CROMO. Odore sgradevole di carbolo/fenolo/inchiostro (si accentua al riscaldamento). Lamelle da giovani rosa, poi marrone cioccolato.$p1$,$p1$Sindrome gastrointestinale: da 15 min fino a 2 h dopo il consumo nausea, vomito, diarrea, crampi addominali. Nei soggetti sensibili violenti. Tossico sia crudo sia cotto.$p1$,$p1$In caso di disturbi Tox Info Suisse 145. Per lo più sintomatico (liquidi/elettroliti).$p1$,$p1$Non consumare. L'odore di carbolo si accentua al riscaldamento.$p1$,$p1$Confusione/sosia: amanite mortali (Amanita phalloides/verna) con gli agarici bianchi – controllare bulbo/volva; gli champignon commestibili (prataiolo, agarico anisato, agarico delle pecore) non virano al giallo cromo e non odorano di carbolo.$p1$,true),
($p1$albatrellus_confluens$p1$,$p1$it$p1$,$p1$Cappello giallo pasta fino a marrone pane/dorato, lobato-gibboso, 3-20 cm, sembra modellato nella pasta; spesso più corpi fruttiferi concresciuti con gambi ramificati; faccia inferiore con pori fini, rotondi, bianco-giallastri (non lamelle). Micorrizico con pino/conifere su suoli acidi. Da giovane mite, da vecchio sempre più amaro.$p1$,$p1$Crudo/poco cotto intolleranza gastrointestinale; gli esemplari vecchi sono amari/difficili da digerire$p1$,null,$p1$Solo esemplari giovani; crudo indigesto, cuocere bene a fondo. Fresco poco saporito, meglio conservato sott'aceto/sott'olio. I vecchi diventano amari. (In CH rispettare le norme locali di protezione/raccolta.)$p1$,null,true),
($p1$amanita_citrina$p1$,$p1$it$p1$,$p1$Cappello 4-10 cm, giallo limone/zolfo pallido (anche forma bianca var. alba), con residui di velo bianco-brunastri appoggiati. Lamelle bianche, libere. Gambo con anello e base bulbosa marginata. Odore di patata cruda/rafano.$p1$,$p1$Immangiabile fino a leggermente tossico. Si sconsiglia vivamente il consumo – a causa dell'odore/sapore di patata e soprattutto dell'elevato rischio di confusione con le amanite bianche/verdi mortali (Knollenblätterpilze).$p1$,$p1$In caso di consumo e incertezza sulla specie Tox Info Suisse 145 – escludere la confusione con le amanite mortali (Knollenblätterpilze).$p1$,$p1$Non consumare. A causa dell'estremo rischio di confusione con specie mortali, evitare in generale.$p1$,$p1$Confusione/sosia: Amanita falloide (Amanita phalloides) e amanita primaverile/bianca – la forma bianca var. alba è particolarmente pericolosa per la confusione (mortale!).$p1$,true),
($p1$amanita_excelsa$p1$,$p1$it$p1$,$p1$Cappello 5-16 cm, grigio-marrone, con fiocchi di velo grigi, appoggiati, facilmente asportabili (non verrucosi come nell'amanita pantherina). Gambo bianco-grigio, con anello STRIATO/scanalato (decisivo!), base bulbosa, non nettamente marginata. Odore di rafano. Sin. Amanita spissa.$p1$,$p1$Tossico da crudo (come tutte le amanite del gruppo dei Wulstlinge). In Svizzera NON ammesso come fungo commestibile. Il PERICOLO PRINCIPALE è la confusione con il fortemente/potenzialmente mortale tignosa bigia, ossia l'agarico panterino (Amanita pantherina): sindrome pantherina – confusione, allucinazioni, crampi/convulsioni, nei casi gravi coma; nei bambini/a dosi elevate sono documentati casi mortali.$p1$,$p1$In caso di sospetta confusione con l'agarico panterino (Amanita pantherina) contattare subito Tox Info Suisse 145.$p1$,$p1$NON consumare. In Svizzera non ammessa come fungo commestibile; a causa della confusione mortale con l'amanita pantherina evitare assolutamente. Anello/bulbo non sono una distinzione sicura per principianti.$p1$,$p1$Confusione/sosia: amanita pantherina (Amanita pantherina) – fortemente, potenzialmente mortale; l'amanita pantherina ha anello LISCIO e bulbo marginato, mentre la tignosa grigia ha anello STRIATO e bulbo non marginato.$p1$,true),
($p1$amanita_muscaria$p1$,$p1$it$p1$,$p1$Cappello ROSSO con punti bianchi, gambo bianco con anello + bulbo$p1$,$p1$30 min-2 h confusione, allucinazioni, nausea$p1$,$p1$Tox Info Suisse 145 / emergenza 144. Ospedale.$p1$,$p1$NON MANGIARE MAI$p1$,$p1$Fungo delle fiabe. Mortale raramente ma pericoloso$p1$,true),
($p1$amanita_pantherina$p1$,$p1$it$p1$,$p1$Cappello MARRONE con punti bianchi, bulbo con 2-3 cercini alla base del gambo$p1$,$p1$Più violento dell'ovolo malefico (Fliegenpilz / Amanita muscaria): nausea, confusione, crampi/convulsioni$p1$,$p1$Tox Info Suisse 145 / emergenza 144. Urgentemente in ospedale.$p1$,$p1$NON MANGIARE MAI$p1$,$p1$Più tossico dell'ovolo malefico, più frequente delle amanite mortali$p1$,true),
($p1$amanita_phalloides$p1$,$p1$it$p1$,$p1$ANELLO sul gambo + bulbo in una VOLVA membranosa + lamelle bianche + cappello verde oliva$p1$,$p1$8-24 h di tempesta gastrointestinale, poi un'apparente guarigione, poi insufficienza epatica al giorno 3-5$p1$,$p1$SUBITO Tox Info Suisse 145 / emergenza 144. Clinica, Silibinin, eventualmente trapianto di fegato.$p1$,$p1$NON MANGIARE MAI$p1$,$p1$Oltre il 90% dei decessi per avvelenamento da funghi in Europa. IMPARARLO IN MODO INCONFONDIBILE$p1$,true),
($p1$amanita_rubescens$p1$,$p1$it$p1$,$p1$Cappello rosso-brunastro con fiocchi di velo grigi (NON bianco puro); decisivo: la carne e le gallerie delle larve arrossano/diventano rosso vinoso (soprattutto alla base del gambo); anello striato nella parte superiore; lamelle bianche, sporata bianca. NON affidarsi MAI a un singolo carattere – verificare tutti i caratteri insieme. Solo per raccoglitori esperti.$p1$,$p1$Tossico da crudo (le emolisine distruggono i globuli rossi); deve essere cotto bene. La confusione con la Tignosa bruna (Amanita pantherina) provoca avvelenamenti gravi (sindrome pantherina), in parte mortali.$p1$,$p1$In caso di sospetta confusione con la Tignosa bruna (Amanita pantherina) (confusione mentale, ebbrezza, convulsioni) Tox Info Suisse 145 / emergenza 144.$p1$,$p1$Mai cruda; cuocere a fondo accuratamente (distrugge le emolisine); usare solo in caso di determinazione sicura (prova dell'arrossamento + tutti i caratteri).$p1$,$p1$Confusione/sosia: amanita pantherina (Amanita pantherina) – fortemente velenosa, casi mortali noti (fiocchi bianco puro, margine del cappello striato, base bulbosa marginata, anello liscio, la carne NON arrossa MAI; tossine termostabili).$p1$,true),
($p1$amanita_verna$p1$,$p1$it$p1$,$p1$Amanita mortale completamente BIANCO PURO: cappello 5-10 cm, bianco neve, liscio, serico-lucente. Lamelle bianche, libere, fitte. Gambo bianco con anello pendente e volva membranosa alla base bulbosa. Compare soprattutto in primavera/inizio estate. Il test KOH sulla cuticola del cappello diventa giallo.$p1$,$p1$Sindrome falloidea: 6-24 h di latenza, poi vomito massiccio, diarrea coleriforme, dolori addominali, apparente miglioramento, in seguito insufficienza epatica e renale. Già un solo corpo fruttifero può essere mortale.$p1$,$p1$Chiamare subito Tox Info Suisse 145 / numero d'emergenza 144. Conservare i resti del pasto. Clinica: Silibinin/N-acetilcisteina, carbone attivo – ogni ora conta.$p1$,$p1$Non consumare mai. Le amatossine sono termostabili, NON distruttibili con cottura/essiccazione.$p1$,$p1$Confusione/sosia: champignon/prataioli (questi hanno lamelle rosa-marroni, nessuna volva bianca); un fungo bianco con lamelle libere e volva è SEMPRE sospetto.$p1$,true),
($p1$auricularia_auricula_judae$p1$,$p1$it$p1$,$p1$Corpo fruttifero a forma di orecchio, gelatinoso-elastico, gommoso, 2-10 cm, traslucido da bruno-rossastro a bruno-nerastro; superficie superiore vellutata e finemente pelosa, superficie inferiore liscia-venata. Cresce per lo più su sambuco morto, anche su frassino/acero/faggio. Essiccandosi diventa duro, si rigonfia con l'ammollo. Nessun sosia velenoso.$p1$,null,null,$p1$Fungo da ripieno/da mescolare dal sapore neutro (il Mu-Err della cucina asiatica); conservabile essiccato, da ammollare prima dell'uso; cuocere bene. In zuppe, wok, insalate.$p1$,null,true),
($p1$austernpilz$p1$,$p1$it$p1$,$p1$Cresce LATERALMENTE sugli alberi, a forma di ventaglio$p1$,null,null,$p1$arrostito, in zuppa, coltivabile$p1$,$p1$Fungo della stagione invernale, coltivabile in casa$p1$,true),
($p1$boletus_aereus$p1$,$p1$it$p1$,$p1$Cappello da bruno-caffè, bruno scuro a bruno-bronzo, talvolta quasi nero, da giovane finemente vellutato; gambo spesso e claviforme con un reticolo fine da bianco a bruno-chiaro; pori bianchi, da vecchi giallastri; carne bianca, NON virante al blu, dolce. Termofilo.$p1$,null,null,$p1$Eccellente fungo commestibile a carne soda; arrostito, stufato, essiccato. Data la rarità, raccogliere con cautela.$p1$,null,true),
($p1$boletus_reticulatus$p1$,$p1$it$p1$,$p1$Cappello da ocra chiaro a bruno chiaro, asciutto e finemente feltrato (spesso screpolato a placche), gambo con reticolo da biancastro a bruno chiaro, nettamente in rilievo su tutta la lunghezza; tubuli biancastri, da vecchi giallo-olivastri; carne bianca, non virante al blu, dolce. Specie precoce (da giugno). Importante: escludere il Boleto amaro / fiele (tubuli rosa, reticolo grossolano scuro, estremamente amaro) tramite assaggio del sapore.$p1$,null,null,$p1$Ottimo fungo commestibile; da giovane crudo in insalata o arrostito, stufato, essiccato. Utilizzare da giovane, poiché presto bacato.$p1$,null,true),
($p1$butterpilz$p1$,$p1$it$p1$,$p1$Pellicola del cappello VISCIDA da rimuovere, anello sul gambo$p1$,null,null,$p1$Togliere la pellicola del cappello, poi arrostire$p1$,$p1$Togliere la pellicola del cappello è obbligatorio — altrimenti problemi digestivi$p1$,true),
($p1$caloboletus_calopus$p1$,$p1$it$p1$,$p1$Cappello da grigio chiaro, color argilla a bruno-grigiastro, finemente feltrato-asciutto; pori giallo chiaro, viranti al blu alla pressione; gambo bicolore – giallo in alto, ROSSO CARMINIO brillante in basso, con reticolo fine (da cui il nome 'Bel piede'); carne giallastra, virante al blu al taglio, molto AMARA.$p1$,$p1$Tossico da crudo; in caso di consumo disturbi gastrointestinali (nausea, vomito, diarrea). Problema principale aggiuntivo: persistente amaro estremo.$p1$,$p1$In caso di disturbi chiamare Tox Info Suisse 145 (24h); reintegrare i liquidi, in caso di sintomi più gravi rivolgersi al medico.$p1$,$p1$NON CONSUMARE – velenoso da crudo ed estremamente amaro; l'amarezza non scompare con la cottura. Già piccole quantità rovinano un piatto; in caso di ingestione disturbi gastrointestinali.$p1$,null,true),
($p1$calocybe_gambosa$p1$,$p1$it$p1$,$p1$Cappello carnoso bianco-crema; elemento decisivo: lamelle fitte, bianche a OGNI età e sporata bianca; forte odore e sapore farinoso-cetriolo; la carne NON vira al rosso; fungo primaverile. L'odore farinoso e le lamelle bianche lo distinguono dall'Inocibe mortale.$p1$,$p1$Specie commestibile; PERICOLO DI MORTE in caso di confusione con Inocybe erubescens (sindrome muscarinica: forte salivazione/lacrimazione/sudorazione, restringimento delle pupille, vomito, diarrea, difficoltà respiratoria).$p1$,$p1$In caso di sospetto di confusione con un Inocybe (sintomi muscarinici) chiamare SUBITO Tox Info Suisse 145 / emergenza 144 – Atropina come antidoto.$p1$,$p1$Cuocere bene; fungo commestibile apprezzato – solo con determinazione inequivocabile (lamelle bianche, odore farinoso, nessun arrossamento).$p1$,$p1$Confusione/sosia: Inocibe rosso mattone (Inocybe erubescens) – MORTALMENTE velenoso, alto contenuto di muscarina; anch'esso primaverile; la carne arrossa, lamelle bruno-grigiastre, sporata bruna. Anche il velenoso Entoloma livido (Entoloma sinuatum).$p1$,true),
($p1$calvatia_gigantea$p1$,$p1$it$p1$,$p1$Enorme sfera bianca senza gambo, 5-50 (fino a 150) cm di diametro, fino a oltre 20 kg; da giovane bianca come la neve con pelle liscia coriacea, poi giallo-verdastra (allora immangiabile). Su prati, parchi, margini dei boschi. Mangiare SOLO se la carne interna è bianca come la neve e senza accenni di lamelle - tagliare sempre!$p1$,null,$p1$Tagliare sempre longitudinalmente: in presenza di struttura lamellare interna/contorno del cappello (anziché carne bianca uniforme) gettare via - confusione mortale con un giovane Amanita phalloides (tignosa verdognola).$p1$,$p1$Solo esemplari giovani, internamente bianchi come la neve; a fette impanate e arrostite (a mo' di cotoletta, simile a scaloppina). Scartare se la carne interna è ingiallita.$p1$,$p1$Confusione/sosia: Amanita phalloides/virosa (giovani amanite a forma di sfera bianca - ma riconoscibili internamente per l'accenno di lamelle e il profilo del cappello).$p1$,true),
($p1$cantharellus_tubaeformis$p1$,$p1$it$p1$,$p1$Piccolo fungo a forma di imbuto/tromba, cappello 1-7 (9) cm, da giallo-bruno a grigio-olivastro, centro solcato/perforato; superficie inferiore con pliche biforcate, decorrenti, grigio-gialle (non vere lamelle); gambo sottile, cavo, giallo. Nessuna confusione pericolosa nota.$p1$,null,null,$p1$Ottimo fungo da misto e da essiccare nonostante la carne sottile; cuocere bene. Ideale in piatti di funghi, zuppe, essiccato.$p1$,null,true),
($p1$champignon-de-paris$p1$,$p1$it$p1$,$p1$Anello bianco sottile sul gambo, lamelle rosa negli esemplari giovani, colorazione bruna del cappello nella forma coltivata$p1$,null,null,$p1$Crudo in insalata o arrostito, riscaldare brevemente per preservarne il sapore$p1$,$p1$Il fungo commestibile più acquistato in Svizzera, principalmente da coltivazione$p1$,true),
($p1$chlorophyllum_brunneum$p1$,$p1$it$p1$,$p1$Cappello bruno a squame grossolane; carne e lamelle virano al rosso-zafferano/arancio se lesionate (arrossanti); elemento decisivo: bulbo del gambo nettamente marginato e distinto; anello semplice (spesso scorrevole); NESSUNA decorazione a zigzag (natterung) sul gambo (differenza rispetto alla commestibile Mazza di tamburo Macrolepiota procera). Cresce spesso su/accanto al compost.$p1$,$p1$Intossicazione gastrointestinale: nausea, vomito, diarrea, crampi addominali; di intensità variabile da individuo a individuo; non adatto come fungo commestibile.$p1$,$p1$In caso di disturbi dopo il consumo contattare Tox Info Suisse 145.$p1$,null,$p1$Confusione/sosia: Mazza di tamburo (Macrolepiota procera) e le commestibili lepiote zafferano – la confusione porta a intossicazione (la Mazza di tamburo ha il gambo decorato a zigzag, nessun bulbo marginato).$p1$,true),
($p1$clitocybe_dealbata$p1$,$p1$it$p1$,$p1$Piccolo fungo bianco, cappello 2-5 cm, da bianco gesso a bianco crema, da giovane convesso, poi piano fino a depresso. Lamelle bianco-crema, fitte, leggermente decorrenti. Cresce in gruppi su prati, pascoli – spesso in cerchi delle streghe, volentieri accanto al gambesecche.$p1$,$p1$Sindrome muscarinica: 15-30 min dopo il consumo forte salivazione/lacrimazione/sudorazione, miosi, dolori addominali, nausea, diarrea, vista offuscata, difficoltà respiratoria. Antidoto: Atropina.$p1$,$p1$Tox Info Suisse 145. Antidoto Atropina in clinica.$p1$,$p1$Non consumare mai. La muscarina è termostabile.$p1$,$p1$Confusione/sosia: gambesecche (Marasmius oreades, commestibile) e giovane prataiolo dei prati – stesso habitat prativo; anche con il Clitocybe rivuloso (anch'esso velenoso).$p1$,true),
($p1$clitocybe_nebularis$p1$,$p1$it$p1$,$p1$Grande cappello grigio nebbia, dall'aspetto come pruinoso, con margine arrotolato; lamelle color crema fitte, leggermente decorrenti; gambo robusto e pallido; odore dolciastro-rancido marcato.$p1$,$p1$Frequente intolleranza individuale: disturbi gastrointestinali (nausea, vomito, diarrea) anche con funghi cotti; la nebularina NON viene eliminata con la cottura.$p1$,null,$p1$La VAPKO Svizzera tedesca classifica oggi il consumo come problematico (valore alimentare modificato in 'non fungo commestibile') – se ne sconsiglia il consumo; se proprio, solo ben cotto e in piccole quantità.$p1$,$p1$Confusione/sosia: Entoloma gigante (Entoloma sinuatum) – altamente velenoso (lamelle giallastre, poi rosa, spaziate); inoltre il velenoso tricoloma tigrato (Tricholoma pardinum).$p1$,true),
($p1$clitocybe_rivulosa$p1$,$p1$it$p1$,$p1$Piccolo fungo biancastro, cappello 2-4 cm, da giovane bianco-pruinoso, spesso macchiato/solcato concentricamente dalla pruina (la pruina si fende), traslucido rosa carne. Lamelle crema-rosa pallido, fitte, leggermente decorrenti. Cresce in gruppi su prati, tappeti erbosi, bordi dei sentieri, spesso in file/cerchi delle streghe.$p1$,$p1$Sindrome muscarinica: 15-30 min dopo il consumo forte salivazione/lacrimazione/sudorazione, miosi, dolori addominali, nausea, diarrea, vista offuscata. Antidoto: Atropina.$p1$,$p1$Tox Info Suisse 145. Antidoto Atropina in clinica.$p1$,$p1$Non consumare mai. Con la cottura la muscarina viene anzi liberata dal suo precursore – il riscaldamento NON detossifica.$p1$,$p1$Confusione/sosia: gambesecche (Marasmius oreades) e prataiolo dei prati (stesso habitat); anche con il Clitocybe dei campi (anch'esso velenoso).$p1$,true),
($p1$cortinarius_orellanus$p1$,$p1$it$p1$,$p1$Cappello arancio-bruno, lamelle arancioni, gambo FIBROSO-arancione, TARDIVO da set-nov$p1$,$p1$TARDIVO insufficienza renale dopo 3-14 GIORNI$p1$,$p1$Subito Tox Info Suisse 145 / Emergenza 144. Clinica, preparazione alla dialisi (insufficienza renale).$p1$,$p1$NON MANGIARE MAI, spesso confuso con il finferlo$p1$,$p1$Subdolo, l'avvelenamento si manifesta solo 1-2 settimane dopo il consumo$p1$,true),
($p1$cortinarius_rubellus$p1$,$p1$it$p1$,$p1$Cappello 3-8 cm, da giallo a bruno-arancio/ruggine, conico con umbone appuntito, asciutto e finemente feltrato. Lamelle da color cannella a bruno-ruggine, spaziate. Cortina (velo). In boschi di conifere acidi e ricchi di humus, soprattutto abete rosso. Odore di rafano.$p1$,$p1$Sindrome da orellanina: latenza molto lunga, da 2 giorni a 3 settimane. Dapprima sete, nausea, dolori a testa/arti/reni, poi grave insufficienza renale, spesso irreversibile. Circa il 50% rimane dipendente dalla dialisi.$p1$,$p1$Chiamare subito il numero d'emergenza di Tox Info Suisse 145. A causa della latenza estremamente lunga, recarsi immediatamente in clinica anche in caso di sospetto tardivo – monitorare la funzionalità renale, se necessario dialisi.$p1$,$p1$Non consumare mai. L'orellanina è termostabile e resistente all'essiccazione.$p1$,$p1$Confusione/sosia: Cortinario rosso-arancio (Cortinarius orellanus, anch'esso mortale); da giovane confondibile con la rossola (Cortinarius caperatus) e con il finferlo.$p1$,true),
($p1$eierschwamm$p1$,$p1$it$p1$,$p1$Pseudolamelle (creste) al posto delle lamelle, completamente giallo tuorlo, odore di albicocca$p1$,$p1$—$p1$,$p1$—$p1$,$p1$friggere fresco, non lavare$p1$,$p1$Classico per il sapore$p1$,true),
($p1$entoloma_sinuatum$p1$,$p1$it$p1$,$p1$Fungo grande e carnoso, cappello 6-20 cm, da giovane da biancastro-grigio a giallo argilla/avorio, liscio, ondulato con l'età. Carattere più importante: lamelle da giovani biancastre/giallastre, poi ROSA CARNE per via delle spore (Entoloma). Odore farinoso/rancido. Gambo robusto bianco senza anello.$p1$,$p1$Grave sindrome gastrointestinale: circa 0,5-4 h dopo il consumo violenti disturbi gastrointestinali di tipo colico, vomito, diarrea, perdita di elettroliti, problemi circolatori. Potenzialmente letale per bambini, anziani e persone debilitate.$p1$,$p1$Tox Info Suisse 145. Reidratazione aggressiva/riequilibrio degli elettroliti; ricovero ospedaliero per le persone a rischio.$p1$,$p1$Non consumare mai. Le tossine sono stabili alla cottura; è una delle cause più frequenti di gravi avvelenamenti gastrointestinali in Europa.$p1$,$p1$Confusione/sosia: prugnolo (Calocybe gambosa, commestibile – lamelle bianche fitte, più precoce nella stagione), Clitopilus prunulus (Mehlräsling), giovani prataioli, Entoloma clypeatum (Schildrötling).$p1$,true),
($p1$flaemmling$p1$,$p1$it$p1$,$p1$cappello di piccole dimensioni, fibroso-finemente fioccoso, lignicolo (cresce sul legno)$p1$,$p1$nessuna tossina$p1$,$p1$non necessario$p1$,$p1$solo giovane e fresco, cottura consigliata$p1$,$p1$tenero, ma di breve conservabilità$p1$,true),
($p1$fliegenpilz-grosspilz$p1$,$p1$it$p1$,$p1$Cappello ripiegato a forma di cervello, cavo, simile alla spugnola$p1$,$p1$Mal di testa, nausea, diarrea, vertigini, crampi$p1$,$p1$Centro antiveleni 145, protezione gastrica$p1$,$p1$non commestibile$p1$,$p1$spesso confuso con la spugnola commestibile$p1$,true),
($p1$fliegenpilz-roetlich$p1$,$p1$it$p1$,$p1$bruno con fioccosità bianche, anello e bulbo$p1$,$p1$Mal di testa, vertigini, confusione$p1$,$p1$Centro antiveleni 145, trattamento$p1$,$p1$non commestibile$p1$,$p1$più raro dell'ovolo malefico$p1$,true),
($p1$fliegenpilz_var_alba$p1$,$p1$it$p1$,$p1$Cappello bianco con fioccosità bianche, anello bianco e volva, può essere confuso con funghi commestibili$p1$,$p1$Ebbrezza, crampi muscolari, confusione, allucinazioni$p1$,$p1$Centro antiveleni 145, valutare la lavanda gastrica$p1$,$p1$Non commestibile$p1$,$p1$Forma variante dell'ovolo malefico, velenoso come la forma rossa$p1$,true),
($p1$flockenstieliger-hexen-roehrling$p1$,$p1$it$p1$,$p1$Pori rossi, vira al blu alla pressione, fioccosità rosse sul gambo, carne gialla che vira al rosso$p1$,$p1$Nausea, vomito, crampi allo stomaco in caso di riscaldamento insufficiente$p1$,$p1$Consulto medico in caso di sintomi da avvelenamento$p1$,$p1$Cuocere/bollire completamente per almeno 20 minuti, non mangiare crudo, preparare accuratamente$p1$,$p1$Commestibile solo dopo accurata preparazione, viene spesso confuso con il velenoso Flockenstieliger Hexen-Röhrling$p1$,true),
($p1$flockenstieliger_hexenpilz$p1$,$p1$it$p1$,$p1$Puntini RUVIDI sul gambo, tubuli rossi, vira RAPIDAMENTE al blu alla pressione$p1$,$p1$Cotto nessun problema, crudo lievi disturbi$p1$,null,$p1$DEVE essere cotto 15+ min, crudo provoca lieve avvelenamento$p1$,$p1$Nonostante l'aspetto spaventoso, molto apprezzato$p1$,true),
($p1$fomitopsis_betulina$p1$,$p1$it$p1$,$p1$Poliporo annuale, a forma di mensola/zoccolo, 5-20 cm, esclusivamente sulle betulle; superficie superiore liscia, da grigio a bruno chiaro con margine sporgente ripiegato verso l'interno, faccia inferiore con fini pori bianchi. Carne bianca e molle-sugherosa da giovane, in seguito sempre più amara. Noto fungo vitale/medicinale (fungo di Ötzi).$p1$,null,null,$p1$Non è un fungo commestibile (coriaceo, amaro). Tradizionalmente come fungo medicinale/vitale: corpi fruttiferi giovani e bianchi essiccati come tè/estratto. Non come piatto.$p1$,null,true),
($p1$galerina_marginata$p1$,$p1$it$p1$,$p1$Cappello piccolo 1-7 cm, da giallo-bruno a color miele/bruno scuro, spesso con centro più scuro, igrofano. Lamelle pallide da giovani, poi bruno-ruggine, adnate. Anello sottile e fugace sul gambo (spesso scompare rapidamente). In fascetti o isolato su legno morto di conifere (anche latifoglie), ceppi marcescenti.$p1$,$p1$Sindrome falloidea: 6-24 h di latenza, poi violento vomito, diarrea, dolori addominali, apparente ripresa, in seguito insufficienza epatica e renale. 100-150 g possono essere mortali.$p1$,$p1$Chiamare immediatamente il numero d'emergenza Tox Info Suisse 145 (oppure 144). Conservare i resti dei funghi. Clinica con sospetto di avvelenamento da amatossine. Terapia con Silibinin. Ogni ora conta.$p1$,$p1$Non consumare mai. Le amatossine sono termostabili, NON distruttibili con la cottura/essiccazione.$p1$,$p1$Confusione/sosia: Stockschwämmchen (Kuehneromyces mutabilis) – commestibile, ma la confusione più pericolosa; la Galerina non ha il gambo squamoso al di sotto dell'anello.$p1$,true),
($p1$gemeiner-fliegenpilz-var-alba$p1$,$p1$it$p1$,$p1$Cappello da bianco a grigio-brunastro senza fioccosità, velo bianco sotto l'anello, bulbo alla base del gambo con volva$p1$,$p1$Insorgenza ritardata dopo 6-24 h, violenti disturbi gastrici, insufficienza epatica, mortale$p1$,$p1$Chiamare immediatamente il medico d'urgenza, trattamento d'emergenza necessario$p1$,$p1$Non commestibile$p1$,$p1$Una delle specie di funghi più mortali d'Europa, pericolo di confusione con il prataiolo bianco$p1$,true),
($p1$hallimasch$p1$,$p1$it$p1$,$p1$ANELLO sul gambo, giallo miele, parassita sulle radici degli alberi, in fascetti$p1$,$p1$Crudo disturbi gastrointestinali$p1$,$p1$Se ci si sente male, ospedale$p1$,$p1$DEVE ESSERE COTTO 15+ min, mai crudo$p1$,$p1$Comparsa in massa. MAI crudo, molto buono se ben cotto$p1$,true),
($p1$herbsttrompete$p1$,$p1$it$p1$,$p1$Tromba cava grigio scuro-nera$p1$,null,null,$p1$essiccare come spezia invernale$p1$,$p1$Tesoro gastronomico svizzero$p1$,true),
($p1$hygrophoropsis_aurantiaca$p1$,$p1$it$p1$,$p1$Arancio(giallo) brillante, cappello 2-12 (15) cm, finemente feltrato, margine a lungo arrotolato; faccia inferiore con vere LAMELLE arancio-giallo, sottili, fortemente biforcate, decorrenti, che si staccano facilmente (il vero galletto ha pliche ottuse, saldamente fuse). Carne sottile, molle, mite/un po' di muffa.$p1$,$p1$Disturbi gastrointestinali con dolori addominali, diarrea, nausea, vomito in caso di quantità maggiori o in persone sensibili.$p1$,$p1$In caso di disturbi bere molto, contattare Tox Info Suisse 145; conservare i resti dei funghi.$p1$,$p1$Non raccomandato per il consumo; debolmente velenoso, in quantità elevate tossico per il tratto gastrointestinale. Prudenza: evitare.$p1$,$p1$Confusione/sosia: vero galletto (Cantharellus cibarius) - il falso è il più velenoso; attenzione inoltre al fungo dell'olivo (Omphalotus) nei ritrovamenti di colore arancio-rosso intenso.$p1$,true),
($p1$hypholoma_fasciculare$p1$,$p1$it$p1$,$p1$Cappello 2-6 cm, da giallo zolfo a giallo-verdastro, centro spesso bruno-arancio/rossastro. Caratteristico: lamelle da giovani giallo zolfo, poi verdastre, infine oliva-nerastre. Gambo giallo, senza vero anello (al massimo una fugace zona cortinata). In fascetti su ceppi/legno morto. Carne molto amara.$p1$,$p1$Sindrome gastrointestinale: vomito, diarrea, sudorazioni profuse, nei casi gravi disturbi della vista e aumento dei valori epatici. Il sapore fortemente amaro funge da avvertimento.$p1$,$p1$Tox Info Suisse 145. Per lo più trattamento sintomatico; nei decorsi gravi controllare i valori epatici.$p1$,$p1$Non consumare. Le sostanze amare e le tossine sono stabili alla cottura.$p1$,$p1$Confusione/sosia: Stockschwämmchen (Kuehneromyces mutabilis, commestibile, gambo squamoso/anello) e il commestibile Rauchblättriger Schwefelkopf (lamelle grigie, mite).$p1$,true),
($p1$infundibulicybe_geotropa$p1$,$p1$it$p1$,$p1$Grande cappello a imbuto con caratteristico umbone centrale; bruno-cuoio pallido, da giovane finemente feltrato; lamelle bianche decorrenti e fitte; gambo tenace e sodo. Utilizzare solo i cappelli giovani, quelli più vecchi sono coriacei. Crudo leggermente velenoso – solo cotto.$p1$,$p1$La specie in sé non è velenosa (crudo leggermente irritante per lo stomaco); il pericolo deriva solo dalla confusione con gli imbutini bianchi velenosi (sindrome muscarinica).$p1$,null,$p1$Solo cappelli giovani, rimuovere i gambi (coriacei); cuocere bene; apprezzato in zuppe e piatti misti.$p1$,$p1$Confusione/sosia: Clitocybe phyllophila (Bleiweisser Firnis-Trichterling) e i clitocibi bianchi velenosi – contenenti muscarina, velenosi (più piccoli, a carne sottile, senza umbone).$p1$,true),
($p1$inocybe_erubescens$p1$,$p1$it$p1$,$p1$Cappello 3-9 cm, da giovane biancastro-crema, fibrilloso radialmente/screpolato, con l'età e in caso di lesione vira da rosso mattone a rosso vinoso. Lamelle pallide da giovani, poi bruno-oliva/bruno argilla, spesso arrossanti. Compare in primavera/inizio estate (in concomitanza con il prugnolo). Odore spermatico.$p1$,$p1$Sindrome muscarinica (PSL): 15-30 minuti dopo il consumo forte sudorazione, salivazione/lacrimazione, miosi, dolori addominali, vomito, diarrea, calo della pressione arteriosa, bradicardia. 40-50 g freschi possono essere letali. Antidoto: Atropin.$p1$,$p1$Chiamare immediatamente Tox Info Suisse 145 / numero d'emergenza 144. Antidoto Atropin in clinica; monitorare la circolazione.$p1$,$p1$Non consumare mai. La muscarina è termostabile.$p1$,$p1$Confusione/sosia: prugnolo (Calocybe gambosa, commestibile) – stessa stagione primaverile; confondibile anche con il fungo di farina (Mehlräsling) e i giovani prataioli.$p1$,true),
($p1$kuehneromyces_mutabilis$p1$,$p1$it$p1$,$p1$A ciuffi su ceppi di latifoglie; cappello igrofano color bruno-miele che impallidisce dal margine in modo bi-/multicolore; evidente zona anulare sul gambo, AL DI SOTTO della zona anulare brunastro-squamoso (nessuna fibrillatura argentea); odore gradevolmente fungino. Raccogliere SOLO con il gambo completo – unica distinzione sicura dalla Galerina velenosa.$p1$,$p1$La specie in sé è commestibile; PERICOLO DI MORTE solo per confusione con Galerina marginata (sindrome amatossica: 6-24 ore senza sintomi, poi insufficienza epatica/renale).$p1$,$p1$In caso di sospetto di confusione con Galerina chiamare SUBITO Tox Info Suisse 145 (emergenza 144) – amatossine, ogni ritardo è potenzialmente letale; agire anche in caso di benessere dopo il periodo di latenza.$p1$,$p1$Cuocere bene a fondo; usare solo i cappelli (i gambi sono coriacei); i principianti dovrebbero rinunciarvi per il rischio di confusione mortale.$p1$,$p1$Confusione/sosia: Galerina marginata (Gifthäubling) – MORTALE, contiene amatossine come l'Amanita falloide (Grüner Knollenblätterpilz); cresce mescolata sullo stesso substrato.$p1$,true),
($p1$lactarius_deliciosus$p1$,$p1$it$p1$,$p1$LATTE ARANCIONE alla rottura, nessun viraggio di colore$p1$,null,null,$p1$saltare in padella, mettere sott'aceto, topping per pizza$p1$,$p1$Classico italiano. Il latte arancione è il segno distintivo.$p1$,true),
($p1$lactarius_deterrimus$p1$,$p1$it$p1$,$p1$Cappello 4-9 (12) cm, arancione/arancio-rosato carnicino, debolmente zonato, con evidenti MACCHIE VERDI, umido e vischioso, depresso al centro. CHIAVE: latte dapprima ROSSO CAROTA/ROSSO ARANCIO, vira in 15-20 min al ROSSO VINO/rosso scuro. Gambo arancione, SENZA fossette (differenza rispetto al Lactarius deliciosus!). Carne arancione, spesso verdeggiante. Sapore mite fino a leggermente amaro. Strettamente legato all'abete rosso.$p1$,null,null,$p1$Commestibile, ma meno apprezzato del Lactarius deliciosus (spesso leggermente amaro, frequentemente bacato). Saltare in padella/grigliare; non crudo. Preferire esemplari giovani e sodi.$p1$,$p1$Confusione/sosia: Nessuna confusione mortale. Confondibile con Lactarius deliciosus e con il lattario del salmone (tutti commestibili). IMPORTANTE: solo i lattari con latte ROSSO ARANCIO di questo gruppo dei lattari sono commestibili; evitare i lattari con latte bianco o che vira al giallo zolfo (es. Grubiger Milchling, Lactarius scrobiculatus).$p1$,true),
($p1$lactarius_piperatus$p1$,$p1$it$p1$,$p1$Grande, 6-16 cm, bianco fino a crema, da giovane macchiato di crema-giallastro, cappello a imbuto, superficie LISCIA/glabra (non feltrata – differenza rispetto a L. vellereus), non zonato. CHIAVE: lamelle molto FITTE e strette, spesso forcate, decorrenti; latte bianco abbondante, BRUCIANTE/PEPATO PICCANTE, secca a colore oliva/verdastro. Carne bianca, dura. Gambo relativamente lungo, bianco.$p1$,$p1$In caso di consumo fresco/crudo, a causa dell'acredine, possibile irritazione gastrointestinale (nausea, vomito, diarrea); principalmente immangiabile a causa del sapore bruciante e acre.$p1$,$p1$In caso di disturbi gastrointestinali Tox Info Suisse 145, reintegrare i liquidi.$p1$,$p1$Immangiabile – difficilmente commestibile per la piccantezza estrema e persistente; crudo/fresco fortemente irritante. Non raccomandato.$p1$,$p1$Confusione/sosia: Nessuna confusione mortale; molto simile al lattario lanoso (Wolliger Milchling, cappello feltrato, lamelle DISTANZIATE), al Lactifluus glaucescens e alle russule bianche (Weisstäublinge) – tutti piccanti/immangiabili. Distinzione tramite le lamelle fitte e il cappello liscio.$p1$,true),
($p1$lactarius_vellereus$p1$,$p1$it$p1$,$p1$Grande, 8-20 (25) cm, bianco gesso, cappello a imbuto/scodellato depresso, superficie finemente FELTRATA-LANOSA (vellutata), non zonata, da vecchio macchiato di ocra. CHIAVE: lamelle molto DISTANZIATE e spesse; il latte bianco fuoriesce solo scarsamente, ha sapore BRUCIANTE PICCANTE, secca a colore grigio-verdastro. Carne dura, bianca. Solleva spesso terra/foglie con sé (spostaterra).$p1$,$p1$In caso di consumo crudo/fresco, a causa dei terpeni, irritazione gastrointestinale fino a intossicazione moderata (nausea, vomito violento, crampi; inizio 30-60 minuti); con grandi quantità disturbi della vista e della coordinazione. Principalmente immangiabile (sapore acre, consistenza dura).$p1$,$p1$In caso di disturbi gastrointestinali Tox Info Suisse 145, reintegrare i liquidi.$p1$,$p1$Immangiabile (bruciante piccante, duro) – consumato crudo/fresco, a causa dei terpeni sono possibili intossicazioni gastrointestinali. Non raccomandato per la cucina.$p1$,$p1$Confusione/sosia: Nessuna confusione mortale; simile al lattario pepato (L. piperatus, cappello liscio, lamelle fitte) e alle russule bianche (Russula delica). Distinzione: vellereus ha lamelle DISTANZIATE + cappello feltrato.$p1$,true),
($p1$lactarius_volemus$p1$,$p1$it$p1$,$p1$Cappello 5-12 cm, bruno-arancio/bruno-cannella fino a bruno-giallo volpino, da giovane vellutato, depresso al centro, asciutto. CHIAVE: emette latte bianco MOLTO ABBONDANTE, MITE (non piccante!), che si colora rapidamente di BRUNO sulle dita/lamelle; odore caratteristico di pesce/aringa (scompare con la rosolatura energica). Lamelle color crema, fitte, brunescenti. Carne soda, bianca.$p1$,null,null,$p1$Eccellente fungo da saltare/grigliare (vedi il nome!); i giovani sono considerati consumabili crudi (a causa del rischio di tenia della volpe/Echinococcus in Svizzera il consumo crudo NON è comunque raccomandato). L'odore di pesce svanisce con la rosolatura energica. NON bollire/stufare – diventa viscido.$p1$,$p1$Confusione/sosia: Nessuna confusione pericolosa; simile solo il Lactifluus rugatus (lattario rugoso, immangiabile). Gli altri lattari con latte bianco sono per lo più piccanti (assaggio di prova).$p1$,true),
($p1$laetiporus_sulphureus$p1$,$p1$it$p1$,$p1$Corpi fruttiferi a mensola/embricati a forma di ventaglio, giallo zolfo fino a giallo-arancio, singola mensola fino a oltre 30 cm; da giovane molle-succoso, da vecchio coriaceo e pallido. Faccia inferiore con fini pori gialli (nessuna lamella). Cresce a ciuffi su tronchi di latifoglie. SOLO da giovane, ben cotto a fondo.$p1$,$p1$Disturbi gastrointestinali (diarrea, vomito) in caso di consumo crudo/cotto in modo insufficiente; in caso di ritrovamenti su legno velenoso (soprattutto tasso/Taxus) in più vertigini/sonnolenza, intossicazione potenzialmente più grave.$p1$,$p1$In caso di disturbi Tox Info Suisse 145; non mangiare mai crudo, non utilizzare come substrato tasso/robinia/quercia.$p1$,$p1$Solo i bordi giovani e succosi; MAI crudo – sempre cuocere bene a fondo (sbollentatura raccomandata), come una cotoletta impanata. Preferire ritrovamenti su alberi da frutto/salice. IMPORTANTE: EVITARE gli esemplari su TASSO (tassina!), robinia nonché quercia/faggio – il veleno del substrato può passare nel fungo.$p1$,null,true),
($p1$leccinum_aurantiacum$p1$,$p1$it$p1$,$p1$Cappello da arancio dorato a rosso-arancio a bruno-arancio, cuticola un po' sporgente; gambo biancastro con squamette prevalentemente rosso-brunastre (non nere); carne bianca, al taglio arrossante/rosso vino, poi grigio-nera. Su pioppo tremulo/pioppo (anche quercia).$p1$,$p1$Crudo o cotto in modo insufficiente: disturbi gastrointestinali; raramente intolleranza anche dopo la cottura$p1$,null,$p1$Ottimo fungo commestibile dalla carne soda. CRUDO INTOLLERABILE/VELENOSO – cuocere bene a fondo almeno 15-20 min. La carne scurisce in cottura. Solo piccole quantità, poiché anche cotto sono state segnalate sporadiche intolleranze gastrointestinali.$p1$,null,true),
($p1$leccinum_pseudoscabrum$p1$,$p1$it$p1$,$p1$Cappello da bruno-giallo a grigio- fino a bruno-nero, caratteristicamente rugoso-fossettato/martellato; gambo robusto con squamette bruno-scure; tubuli bianco-crema, da vecchi grigio-oliva; carne bianca, al taglio dapprima grigio-violacea/rosa, poi nera. Quasi solo su carpino bianco (anche nocciolo). Sin. Leccinellum pseudoscabrum.$p1$,$p1$Crudo o cotto in modo insufficiente: disturbi gastrointestinali$p1$,null,$p1$Buon fungo commestibile, da giovane. Come tutti i porcinelli (Raufüsse) cuocere bene a fondo; il valore alimentare diminuisce rapidamente con l'età, perciò raccogliere da giovane. La carne scurisce in cottura.$p1$,null,true),
($p1$leccinum_versipelle$p1$,$p1$it$p1$,$p1$Cappello da giallo-arancio acceso a rosso mattone, finemente feltrato, cuticola sporgente al margine; gambo biancastro con squamette bruno-nere (non rosse); tubuli grigi; carne al taglio dapprima grigio-violacea, poi nera, base del gambo bluastro-verdognola. Solo su betulla.$p1$,$p1$Crudo o cotto in modo insufficiente: disturbi gastrointestinali$p1$,null,$p1$Ottimo fungo commestibile, da giovane. CRUDO VELENOSO – cuocere bene a fondo almeno 15-20 min. La carne diventa nera in cottura (non diminuisce il valore alimentare). Rimuovere i tubuli vecchi spugnosi.$p1$,null,true),
($p1$lepista_nuda$p1$,$p1$it$p1$,$p1$Cappello carnoso da giovane colorato di blu-violetto, in seguito impallidente al bruno dal centro; lamelle e gambo violetti, fitti; odore gradevole simile a profumo; sporata rosa pallido (non bruno-ruggine) – distinzione importante dai cortinari.$p1$,$p1$Crudo è tossico (disturbi gastrointestinali, emolisine); deve essere riscaldato a fondo (>=15 min).$p1$,null,$p1$Mai crudo; cuocere bene a fondo almeno 15 minuti; adatto anche per la conservazione sott'aceto.$p1$,$p1$Confusione/sosia: Cortinari violetti (Cortinarius spp.) – sporata bruno-ruggine, velo cortiniforme ragnatelato; singoli Cortinarius (es. Cortinarius orellanus / Orangefuchsiger Raukopf) sono mortali.$p1$,true),
($p1$lycoperdon_perlatum$p1$,$p1$it$p1$,$p1$A forma di fiasco/pera con una parte di gambo ben distinta, alto 3-10 cm; superficie con aculei/verruche grossolani che si staccano facilmente e lasciano un disegno reticolato. Da giovane bianco, in seguito giallo-grigio-bruno. Mangiare solo finché la carne interna è perfettamente bianca; tagliare sempre.$p1$,null,$p1$Tagliare LONGITUDINALMENTE ogni fungo sferico/bianco: (1) in presenza di abbozzo di lamelle/contorno del cappello all'interno, gettarlo (mortale Amanita, tignosa verdognola); (2) in presenza di carne soda marmorizzata viola-nera, gettarlo (velenoso falso tartufo Scleroderma). Mangiare solo la gleba uniformemente bianca pura.$p1$,$p1$Solo da giovane con carne interna bianco-pura; come fungo da mescolanza. Diventa facilmente coriaceo durante la cottura; spesso solo come contorno.$p1$,$p1$Confusione/sosia: giovani Amanita phalloides/virosa (stadio sferico - all'interno inserzione delle lamelle); falso tartufo (Scleroderma, carne nero-violacea).$p1$,true),
($p1$marasmius_oreades$p1$,$p1$it$p1$,$p1$Cappello piccolo e tenace, da ocra chiaro a bruno cuoio, spesso piano con umbone; lamelle bianco-crema e marcatamente distanziate fra loro; gambo tenace-elastico, si lascia torcere senza spezzarsi; caratteristico odore aromatico (mandorla amara/garofano); i corpi fruttiferi secchi rivivono dopo l'inumidimento.$p1$,$p1$Crudo e in grandi quantità è indigesto a causa di lievi tracce di acido cianidrico; reso innocuo dalla cottura.$p1$,null,$p1$Cuocere bene fino in fondo; rimuovere solo i gambi coriacei oppure tagliarli finemente; eccellente fungo da condimento e da essiccazione.$p1$,$p1$Confusione/sosia: il falso imbuto delle aiuole (Clitocybe rivulosa/dealbata) – contenente muscarina, velenoso; nello stesso habitat di prato (bianco, lamelle fitte).$p1$,true),
($p1$marone$p1$,$p1$it$p1$,$p1$I tubuli si colorano di blu alla pressione, cappello bruno-castano$p1$,null,null,$p1$rosolare fresco, essiccare$p1$,$p1$Frequente alternativa al porcino$p1$,true),
($p1$maronenroehrling$p1$,$p1$it$p1$,$p1$Colorazione del cappello bruno-castana, pori gialli, fioccosità alla base del gambo, vira al blu alla pressione$p1$,null,null,$p1$Rimuovere la cuticola del cappello, intero o a pezzi, rosolare o lessare$p1$,$p1$Fungo commestibile apprezzato e frequente, meno pregiato del porcino ma affidabile$p1$,true),
($p1$morchelchampignon$p1$,$p1$it$p1$,$p1$superficie del cappello a nido d'ape, gambo alto, forma caratteristica$p1$,$p1$nessuna tossina$p1$,$p1$non necessario$p1$,$p1$utilizzare solo cotto o rosolato$p1$,$p1$Prelibatezza, primaverile, velenoso da crudo$p1$,true),
($p1$morchella_elata$p1$,$p1$it$p1$,$p1$Cappello conico-appuntito, alto 4-15 cm, con camere nettamente infossate a nido d'ape, costole scure orientate longitudinalmente, da oliva/grigio-bruno a nerastro; gambo biancastro, cappello E gambo completamente cavi e attaccati lisci alla base del cappello (differenza rispetto alla Gyromitra). VELENOSO DA CRUDO - solo ben cotto/essiccato.$p1$,$p1$In caso di consumo crudo/insufficientemente cotto: disturbi gastrointestinali, sindrome da Morchella con vertigini, disturbi dell'equilibrio/della coordinazione, tremori, stato di ebbrezza.$p1$,$p1$In caso di sintomi neurologici/vomito persistente Tox Info Suisse 145; mai crudo, cuocere sempre completamente per almeno 15 min. Escludere assolutamente la confusione con la Gyromitra (Lorchel) altamente velenosa.$p1$,$p1$MAI crudo! Cuocere bene per almeno 15 min OPPURE essiccare per diversi mesi; eliminare l'acqua di cottura. Crudo/cotto in modo insufficiente: avvelenamento gastrointestinale ovvero sindrome da Morchella. Anche cotto non combinare con l'alcol.$p1$,$p1$Confusione/sosia: Gyromitra di primavera (Gyromitra esculenta) - cerebriforme contorta invece che a nido d'ape, gambo a camere (non cavo), altamente velenosa/potenzialmente mortale (giromitrina/MMH).$p1$,true),
($p1$parasol$p1$,$p1$it$p1$,$p1$Anello MOBILE sul gambo, lamelle bianche, superficie del cappello squamosa$p1$,null,null,$p1$rosolare impanato come una cotoletta$p1$,$p1$Conosciuto come cotoletta di fungo$p1$,true),
($p1$paxillus_involutus$p1$,$p1$it$p1$,$p1$Cappello 5-15 cm, da ocra a bruno-ruggine/oliva, da giovane con margine arrotolato verso l'interno, feltrato e costolato (da cui il nome). Lamelle decorrenti, giallo-ocra, facilmente staccabili dal cappello, macchiate di bruno scuro alla pressione. L'intero fungo vira al bruno se ferito.$p1$,$p1$Acuto gastrointestinale (vomito, diarrea, dolori addominali/lombari). Pericoloso: sindrome immuno-emolitica da Paxillus dopo consumo ripetuto – gli anticorpi distruggono gli eritrociti (emolisi), insufficienza renale acuta, shock; raro, ma in tal caso spesso grave e potenzialmente MORTALE.$p1$,$p1$Tox Info Suisse 145. In caso di crisi emolitica emergenza: clinica, monitoraggio rene/emocromo, eventualmente plasmaferesi/dialisi.$p1$,$p1$Non consumare. Velenoso anche cotto; la sensibilizzazione immunitaria non è evitabile con il riscaldamento. Il precedente status di fungo commestibile è considerato superato.$p1$,$p1$Confusione/sosia: confusione con altri funghi bruni a lamelle; in passato raccolto erroneamente come fungo commestibile.$p1$,true),
($p1$roehrling_flockenstielig$p1$,$p1$it$p1$,$p1$Tubuli spessi, pori rossi, fioccosità rosse sulla base giallastra del gambo, non vira al blu$p1$,$p1$Nausea, vomito, diarrea, crampi allo stomaco$p1$,$p1$Contattare il numero d'emergenza tossicologica 145, trattamento sintomatico$p1$,$p1$Non commestibile$p1$,$p1$Spesso confuso con il commestibile boleto lurido (Hexen-Röhrling dal gambo fioccoso)$p1$,true),
($p1$roetling$p1$,$p1$it$p1$,$p1$Anello sul gambo, viraggio rossastro$p1$,$p1$nessuna tossina$p1$,$p1$non necessario$p1$,$p1$rosolare, brasare, zuppa$p1$,$p1$diventato raro, pericolo di confusione con specie velenose$p1$,true),
($p1$rotfuss_hexen_roehrling$p1$,$p1$it$p1$,$p1$Spore rosse, pori rossi, caratteristica colorazione rossa alla base del gambo, superficie inferiore del cappello rossa$p1$,$p1$Disturbi gastrointestinali in caso di preparazione cruda$p1$,$p1$Numero d'emergenza tossicologica solo in caso di consumo massiccio$p1$,$p1$Preparare solo dopo accurata sbollentatura, non crudo$p1$,$p1$Valutato in modo controverso, in alcuni Paesi considerato fungo commestibile, sicuro solo dopo sbollentatura$p1$,true),
($p1$rotkappe_birken$p1$,$p1$it$p1$,$p1$Solo sotto le betulle, gambo con squame scure$p1$,null,null,$p1$arrostire, zuppa$p1$,$p1$Accompagna obbligatoriamente la betulla$p1$,true),
($p1$rubroboletus_satanas$p1$,$p1$it$p1$,$p1$Cappello vistosamente chiaro, da biancastro-grigio a grigio crema; pori rosso sangue/carminio brillante; gambo spesso, bulboso, giallo con reticolo rosso; carne da bianca a giallastra, vira al blu solo debolmente/in ritardo; da vecchio odore sgradevole di carogna. Boschi caldi di latifoglie su calcare (quercia/faggio).$p1$,$p1$Gravi sintomi gastrointestinali (nausea, vomito ripetuto, dolori addominali crampiformi, diarrea), per lo più entro 1-6 ore dopo il consumo; in grandi quantità con effetti sul sistema circolatorio, raramente potenzialmente letale. La bolesatina inibisce la sintesi proteica e ha azione emoagglutinante.$p1$,$p1$Chiamare subito Tox Info Suisse: 145 (24h). Conservare i resti dei funghi/il vomito. In caso di vomito/diarrea reintegrare i liquidi, trattamento medico; nessuna autoterapia con sostanze che inducono il vomito.$p1$,$p1$NON CONSUMARE – velenoso. Crudo fortemente velenoso; anche cotto non è sicuramente tollerato. Non considerarlo mai un fungo commestibile.$p1$,$p1$Confusione/sosia: Suillellus luridus (boleto lurido) e Neoboletus erythropus (boleto dal piede rosso) – entrambi commestibili da cotti, ma la confusione è pericolosa; il Rubroboletus satanas ha il cappello chiaro e vira al blu solo debolmente.$p1$,true),
($p1$russula_cyanoxantha$p1$,$p1$it$p1$,$p1$Cappello 5-15 cm, da verde-violaceo/lilla-verde a blu-verde, spesso variegato a più colori; cuticola asportabile fino a metà. CARATTERE DECISIVO: lamelle morbide, flessibili, lucide e untuose che NON si rompono (al tatto come sapone molle/lardo) - quasi tutte le altre russule hanno lamelle fragili che si spezzano. Carne bianca, mite, immutabile; sotto la cuticola violetto-blu. Gambo bianco, sodo. Reazione FeSO4 negativa/molto debole (differenza rispetto alle altre russule).$p1$,null,$p1$In caso di sospetta confusione con l'amanita falloide / tignosa verdognola (nausea/diarrea 6-24h dopo il pasto) chiamare SUBITO Tox Info Suisse 145 - il tempo di latenza è potenzialmente letale.$p1$,$p1$Esemplari giovani arrostiti, stufati o in piatti di funghi misti; aroma mite e nocciolato. Esemplari più vecchi spesso bacati - scartare.$p1$,$p1$Confusione/sosia: Amanita phalloides (amanita falloide verde) - mortalmente velenosa: esemplari di colore verde/violaceo possono essere confusi con essa in una determinazione puramente visiva. La distinzione SICURA AVVIENE SOLO tramite l'assenza dell'anello (manicotto) e l'assenza di bulbo/volva alla base del gambo, nonché tramite le lamelle flessibili ed elastiche della Russula cyanoxantha. All'interno del genere: escludere le russule piccanti con un assaggio.$p1$,true),
($p1$russula_emetica$p1$,$p1$it$p1$,$p1$Cappello 4-10 cm, da rosso vermiglio brillante a rosso sangue/rosso ciliegia, sbiadito a chiazze; cuticola lucida, vischiosa, asportabile facilmente e ampiamente. CHIAVE: sapore SUBITO BRUCIANTE PICCANTE (sputare l'assaggio!). Carne bianca, sotto la cuticola rossa rosa, odore fruttato-dolciastro. Lamelle bianco puro, gambo bianco, fragile. Tipico negli sfagni/muschi di torbiera di boschi di conifere umidi.$p1$,$p1$Sindrome gastrointestinale: nausea, vomito violento, crampi gastrointestinali, diarrea; insorgenza da 15 min a circa 2-4 ore. Autolimitante, raramente pericolosa salvo in caso di perdita di liquidi.$p1$,$p1$In caso di disturbi Tox Info Suisse 145 (24h). Reintegrare liquidi/elettroliti; conservare i resti dei funghi.$p1$,$p1$Non consumabile - velenoso. Sapore bruciante piccante = non commestibile/velenoso.$p1$,$p1$Confusione/sosia: confondibile con russule rosse commestibili (es. Russula paludosa) - separazione sicura SOLO tramite assaggio (piccante = velenoso).$p1$,true),
($p1$russula_vesca$p1$,$p1$it$p1$,$p1$Cappello 4-12 (15) cm, da rosso carne a bruno-vinoso, bruno nocciola/cuoio, grigio-lilla, spesso sbiadito a chiazze; opaco, leggermente vischioso solo da giovane. CARATTERE CHIAVE: cuticola troppo corta (accorciata) che si ritira sul margine e lascia scoperte le punte bianche delle lamelle come piccoli dentini. Carne bianca, mite, quasi inodore. Gambo bianco (mai rossastro), spesso assottigliato verso la base, da vecchio macchiato di bruno-giallastro. Reazione FeSO4 nettamente rosa-carne/rosa-arancio (buon carattere identificativo).$p1$,null,null,$p1$Ottimo fungo commestibile, dal sapore mite-nocciolato; arrostire, stufare, per piatti misti. Considerato una delle migliori russule.$p1$,$p1$Confusione/sosia: all'interno del genere confusione con altre russule, in parte piccanti o non commestibili (assaggio: piccante = non mangiare); la Russula exalbicans (russula scolorante) può anch'essa mostrare la cuticola accorciata, ma ha sapore tendente al piccante. Nessuna confusione direttamente mortale, ma i principianti devono distinguere con sicurezza le russule dai funghi a lamelle dal cappello bruno.$p1$,true),
($p1$russula_virescens$p1$,$p1$it$p1$,$p1$Cappello 4-15 (20) cm, verde/verde erba/verde rame su fondo verde pallido-biancastro (MAI violetto); CARATTERE CHIAVE: la cuticola si screpola a placche/zolle come un mosaico/pelle di rospo, spesso con fessure giallo-sporco. Carne bianca, soda, fragile, mite, gradevolmente nocciolata. Lamelle bianco-crema, fragili. Gambo bianco, fragile, SENZA anello e SENZA bulbo. Attenzione: da giovane il cappello può essere quasi bianco e la screpolatura a placche della cuticola non ancora marcata.$p1$,null,$p1$In caso di sospetta confusione con l'amanita falloide / tignosa verdognola (nausea/diarrea ritardata 6-24h dopo il pasto) chiamare SUBITO Tox Info Suisse 145 - il tempo di latenza è potenzialmente letale, il trattamento precoce è decisivo.$p1$,$p1$Eccellente fungo commestibile, dal sapore nocciolato, una delle poche russule consumabili crude; arrostire, stufare. Raccogliere SOLO con determinazione assolutamente sicura - per i principianti NON raccomandato.$p1$,$p1$Confusione/sosia: Amanita phalloides (amanita falloide verde) - MORTALMENTE velenosa. In particolare gli esemplari giovani sono facili da confondere (colorazione verde simile, stessi habitat). Distinzione SICURA SOLO scavando ed esaminando il fungo intero: alla Russula virescens MANCANO il manicotto del gambo (anello) E il bulbo/volva alla base del gambo; inoltre cuticola screpolata a placche + lamelle fragili.$p1$,true),
($p1$sarcodon_imbricatus$p1$,$p1$it$p1$,$p1$Cappello 6-15 (30) cm, da grigio a bruno chiaro con squame grossolane bruno scure rialzate a tegole; faccia inferiore con aculei grigio-bruni, fragili (nessun poro/lamella). Fungo simbionte nei boschi di conifere (abete rosso). Da giovane mite, da vecchio sempre più amaro.$p1$,$p1$Se consumato crudo/poco cotto oppure in esemplari vecchi/amari, disturbi gastrointestinali (nausea, diarrea).$p1$,null,$p1$Solo esemplari giovani; crudo/poco cotto è indigesto, perciò cuocere bene oppure sbollentare. Noto fungo da condimento: essiccare e macinare in polvere di funghi. Evitare esemplari vecchi/amari.$p1$,null,true),
($p1$schopftintling$p1$,$p1$it$p1$,$p1$Mangiare SOLO da GIOVANE, da vecchio si dissolve in una massa simile a inchiostro$p1$,null,$p1$consumare subito; raccogliere e preparare entro 1 ora$p1$,$p1$arrostire subito, zuppa$p1$,$p1$ATTENZIONE con l'alcol, coprina - nessun alcol per 24h$p1$,true),
($p1$semmelstoppelpilz$p1$,$p1$it$p1$,$p1$Aculei invece di lamelle, ocra chiaro$p1$,null,null,$p1$arrostire fresco, condire$p1$,$p1$Poco rischio di confusione per i principianti$p1$,true),
